/* v451 · Módulo 4 adaptado para Kids (9-11) y Teens (12-17): mismo tema y gramática, con situaciones de su mundo (sin trabajo, jefe ni dinero de adultos) */
window.MYAGE4={"young": {"t1p1": {"tip": "<p>El <b>primer condicional</b> habla de situaciones <b>reales o muy probables</b> en el presente o el futuro.</p>\n<p><b>If + presente simple, will / imperativo / modal + verbo</b><br><i>If it <b>rains</b>, we<b>'ll stay</b> in.</i> · <i>If Mom calls, <b>tell</b> her I'm at practice.</i> · <i>If you don't save your game, you <b>could</b> lose everything.</i></p>\n<p><b>Unless</b> = <i>if … not</i> (a menos que): <i>Unless we leave now, we'll miss the bus</i> = <i>If we don't leave now…</i></p>\n<p>⏱Con <b>when, as soon as, before, after, until</b> también usamos <b>presente</b> para hablar del futuro: <i>I'll call you <b>as soon as I get home</b>.</i></p>\n<p>Si la oración empieza con <b>if</b>, pon <b>coma</b>; si el <i>if</i> va en medio, no hace falta: <i>We'll stay in if it rains.</i></p>", "vocab": [{"en": "unless", "es": "a menos que", "v": "f", "img": "u:photo-1697204120925-4852eb4bb48f", "au": "y45312adeaa"}, {"en": "as soon as", "es": "tan pronto como", "v": "m", "img": "u:photo-1758925403640-95e2a480c235", "au": "y45c4ba7c92"}, {"en": "miss the bus", "es": "perder el bus", "v": "f", "img": "u:photo-1653147496338-b07db1c4acc9", "au": "y450a583708"}, {"en": "finish on time", "es": "terminar a tiempo", "v": "m", "img": "u:photo-1560785496-3c9d27877182", "au": "y4626972b83"}, {"en": "run late", "es": "ir con retraso", "v": "f", "img": "u:photo-1524603642524-b02ea114f009", "au": "y466cb25ae8"}, {"en": "call it off", "es": "cancelarlo / suspenderlo", "v": "m", "img": "u:photo-1701277050203-eabfa03e64eb", "au": "y483005dfc8"}, {"en": "get stuck in traffic", "es": "quedarse atascado en el tráfico", "v": "f", "img": "u:photo-1602951172321-fe0aa8865e6b", "au": "y4c87165b7e"}, {"en": "the odds are", "es": "lo más probable es que", "v": "m", "img": "u:photo-1791909867713-aa7ec3149960", "au": "y42e043859d"}], "sentences": [{"en": "If you don't finish your homework, you won't play video games.", "es": "Si no terminas tu tarea, no jugarás videojuegos.", "v": "m", "img": "u:photo-1758612898701-e2f2958f219d", "au": "y4656e43d71"}, {"en": "Unless we leave now, we'll get stuck in traffic.", "es": "A menos que salgamos ya, nos quedaremos atascados en el tráfico.", "v": "f", "img": "u:photo-1602951172321-fe0aa8865e6b", "au": "y4db0e12a53"}, {"en": "If the bus is late, text me.", "es": "Si el bus se retrasa, escríbeme.", "v": "m", "img": "u:photo-1644952176515-35f100da4fe3", "au": "y4530b34e3b"}, {"en": "I'll call you as soon as I get home.", "es": "Te llamaré tan pronto como llegue a casa.", "v": "f", "img": "u:photo-1674931506140-851b86ece696", "au": "y4324e2b7c7"}, {"en": "If you feel sick, you should stay home.", "es": "Si te sientes enfermo, deberías quedarte en casa.", "v": "m", "img": "u:photo-1672928499632-1d040212e3f4", "au": "y4c9ad8e20d"}, {"en": "We might call off the picnic if it rains.", "es": "Puede que suspendamos el picnic si llueve.", "v": "f", "img": "u:photo-1681311311317-a0561a8eef74", "au": "y4d5551fd56"}]}, "t1p2": {"tip": "<p>Cuando negociamos (con papás, amigos o el equipo) usamos conectores más precisos que <b>if</b>:</p>\n<p><b>as long as / provided (that) / providing</b> = siempre y cuando (una condición obligatoria):<br><i>You can play video games <b>as long as</b> you finish your homework.</i><br><i><b>Provided that</b> it doesn't rain, we'll go to the beach on Saturday.</i></p>\n<p><b>in case</b> = por si acaso (precaución, NO condición): <i>Take an umbrella <b>in case</b> it rains.</i> (llévala ya, llueva o no)<br>Compara: <i>Take an umbrella <b>if</b> it rains</i> (llévala solo si llueve).</p>\n<p><b>Only if</b> enfatiza la única condición: <i>I'll lend you my bike <b>only if</b> you bring it back today.</i></p>\n<p>Después de todos ellos: <b>presente simple</b>, nunca <i>will</i>.</p>", "vocab": [{"en": "as long as", "es": "siempre y cuando", "v": "f", "img": "u:photo-1758687125687-512a331f6a0a", "au": "y4fee2cfc56"}, {"en": "provided that", "es": "con tal de que / siempre que", "v": "m", "img": "u:photo-1537160833943-1b610e77231c", "au": "y4d7de3f0c2"}, {"en": "in case", "es": "por si acaso", "v": "f", "img": "u:photo-1636215979822-fd3e6f63d18e", "au": "y4c0f4ee3c8"}, {"en": "a counteroffer", "es": "una contraoferta", "v": "m", "img": "u:photo-1647893976852-71b2f6ba10e4", "au": "y4fbe171ec1"}, {"en": "meet halfway", "es": "llegar a un punto medio", "v": "f", "img": "u:photo-1634188157846-c6e3bdf99420", "au": "y4231d02371"}, {"en": "a deal-breaker", "es": "un factor decisivo (para no aceptar)", "v": "m", "img": "u:photo-1483193722442-5422d99849bc", "au": "y4bacf97899"}, {"en": "on one condition", "es": "con una condición", "v": "f", "img": "u:photo-1758687127405-f45f90509902", "au": "y47ac94b990"}, {"en": "a fair deal", "es": "un trato justo", "v": "m", "img": "u:photo-1762499923943-fe9ab5ee79f7", "au": "y40508f1d97"}], "sentences": [{"en": "You can stay up late as long as you clean your room.", "es": "Puedes acostarte tarde siempre y cuando ordenes tu cuarto.", "v": "m", "img": "u:photo-1763478958800-3a2a6321f645", "au": "y42a012d123"}, {"en": "Provided that it doesn't rain, we'll have the party outside.", "es": "Siempre que no llueva, haremos la fiesta afuera.", "v": "f", "img": "u:photo-1777613035401-a59d642a04e6", "au": "y4e9ad95129"}, {"en": "Bring a jacket in case it gets cold.", "es": "Trae una chaqueta por si hace frío.", "v": "m", "img": "u:photo-1759473434572-64c4bfd8cb31", "au": "y464b3b2c42"}, {"en": "I'll trade with you on one condition: I pick first.", "es": "Cambiaré contigo con una condición: yo escojo primero.", "v": "f", "img": "u:photo-1753430708971-892048584cf3", "au": "y4e9c75d136"}, {"en": "If you can't meet halfway, there's no deal.", "es": "Si no puedes llegar a un punto medio, no hay trato.", "v": "m", "img": "u:photo-1604179129250-20e67a1b6c9d", "au": "y4a0d69cdcc"}, {"en": "You can borrow my game only if you return it Friday.", "es": "Te presto mi juego solo si me lo devuelves el viernes.", "v": "f", "img": "u:photo-1741321650126-32cbd6990f94", "au": "y4acb53d986"}]}, "t2p1": {"tip": "<p>El <b>segundo condicional</b> habla de situaciones <b>imaginarias, improbables o contrarias a la realidad</b> en el presente o el futuro.</p>\n<p><b>If + pasado simple, would / could / might + verbo</b><br><i>If I <b>found</b> a magic lamp, I<b>'d wish</b> for a puppy.</i> (no espero encontrarla)</p>\n<p>El pasado aquí <b>NO</b> habla del pasado: es \"distancia de la realidad\". <i>If I <b>had</b> a dog</i> = no tengo perro ahora.</p>\n<p>Con <b>be</b>, el inglés cuidado usa <b>were</b> para todas las personas: <i>If she <b>were</b> here…</i> (<i>was</i> es aceptable en conversación).</p>\n<p><b>would</b> = resultado seguro · <b>could</b> = habilidad/posibilidad · <b>might</b> = quizás.</p>\n<p>Compara: <i>If I <b>make</b> the team, I'll train every day</i> (probable) vs. <i>If I <b>made</b> the team, I'd train every day</i> (lo veo difícil).</p>", "vocab": [{"en": "find a magic lamp", "es": "encontrar una lámpara mágica", "v": "f", "img": "u:photo-1758179762133-c43e0c8e66a3", "au": "y487e5a3391"}, {"en": "have superpowers", "es": "tener superpoderes", "v": "m", "img": "u:photo-1519340241574-2cec6aef0c01", "au": "y4afe77b6b8"}, {"en": "be invisible", "es": "ser invisible", "v": "f", "img": "u:photo-1580582932707-520aed937b7b", "au": "y4efd75f82b"}, {"en": "move abroad", "es": "mudarse al extranjero", "v": "m", "img": "u:photo-1792257830916-4650ac029055", "au": "y4475c3415e"}, {"en": "travel the world", "es": "viajar por el mundo", "v": "f", "img": "u:photo-1540402871140-1e9e22e05299", "au": "y4d02be2288"}, {"en": "live on a farm", "es": "vivir en una granja", "v": "m", "img": "u:photo-1665171567333-f3d6bc0951ab", "au": "y4830f2758b"}, {"en": "afford", "es": "permitirse (económicamente)", "v": "f", "img": "u:photo-1580508174046-170816f65662", "au": "y4fb09aedb2"}, {"en": "a dream come true", "es": "un sueño hecho realidad", "v": "m", "img": "u:photo-1624272949900-9ae4c56397e8", "au": "y460218e74b"}], "sentences": [{"en": "If I found a magic lamp, I'd wish for a puppy.", "es": "Si encontrara una lámpara mágica, pediría un cachorro.", "v": "m", "img": "u:photo-1600804340584-c7db2eacf0bf", "au": "y44e12cc6b5"}, {"en": "If I had more time, I'd learn to play the piano.", "es": "Si tuviera más tiempo, aprendería a tocar el piano.", "v": "f", "img": "u:photo-1552422530-9b41dc72286b", "au": "y4b9b7b0f0b"}, {"en": "If she were our teacher, she'd give us less homework.", "es": "Si ella fuera nuestra profesora, nos dejaría menos tarea.", "v": "m", "img": "u:photo-1758270704262-ecc82b23dc37", "au": "y499326a329"}, {"en": "We could travel the world if we had a flying car.", "es": "Podríamos viajar por el mundo si tuviéramos un carro volador.", "v": "f", "img": "u:photo-1791714518063-9f7988f37df0", "au": "y493e84406e"}, {"en": "If I lived near the ocean, I might learn to surf.", "es": "Si viviera cerca del océano, quizás aprendería a surfear.", "v": "m", "img": "u:photo-1730564725670-11ce15658ac8", "au": "y4e93d49fa7"}, {"en": "What would you do if you could be invisible?", "es": "¿Qué harías si pudieras ser invisible?", "v": "f", "img": "u:photo-1758612898181-d7c92f0e21d5", "au": "y4e76271362"}]}, "t2p2": {"tip": "<p>Para dar consejos con el segundo condicional:<br><b>If I were you, I'd …</b> / <b>If I were in your shoes, I wouldn't …</b><br><i>If I were you, I'd <b>turn down</b> the invitation.</i></p>\n<p>Para plantear dilemas: <b>What would you do if …?</b><br><i>What would you do if you found a wallet with $50 in it?</i> → <i>I'd return it, of course.</i></p>\n<p><b>unless</b> también funciona aquí: <i>I wouldn't join the club <b>unless</b> my friends joined too.</i></p>\n<p>Respuestas cortas: <i>Would you accept? — Yes, I <b>would</b>. / No, I <b>wouldn't</b>.</i></p>\n<p>Siempre <b>If I were you</b> (no <i>If I was you</i>) en contextos formales: es la expresión fija.</p>", "vocab": [{"en": "If I were in your shoes", "es": "si yo estuviera en tu lugar", "v": "f", "img": "u:photo-1511988617509-a57c8a288659", "au": "y4a020a3d9e"}, {"en": "I'd think twice.", "es": "Lo pensaría dos veces.", "v": "m", "img": "u:photo-1581275789912-7147ae341512", "au": "y405dfd085c"}, {"en": "weigh the pros and cons", "es": "sopesar los pros y los contras", "v": "f", "img": "u:photo-1517971071642-34a2d3ecc9cd", "au": "y4407cda4a8"}, {"en": "turn down an invitation", "es": "rechazar una invitación", "v": "m", "img": "u:photo-1764385827792-0d3682a416de", "au": "y4c8256f607"}, {"en": "speak up", "es": "hablar claro / dar tu opinión", "v": "f", "img": "u:photo-1758270704021-361c165d68fd", "au": "y4151985759"}, {"en": "a tough call", "es": "una decisión difícil", "v": "m", "img": "u:photo-1637195140076-31e92f35c256", "au": "y4ea049cbe9"}, {"en": "I wouldn't dream of it.", "es": "Ni se me ocurriría.", "v": "f", "img": "u:photo-1590308860873-c9b6f86d1bbe", "au": "y48e80d6bce"}, {"en": "return the wallet", "es": "devolver la billetera", "v": "m", "img": "u:photo-1614260938313-a7fc1a7ad0d2", "au": "y46f0091cef"}], "sentences": [{"en": "If I were you, I'd talk to the teacher first.", "es": "Si yo fuera tú, hablaría primero con la profesora.", "v": "m", "img": "u:photo-1577896851231-70ef18881754", "au": "y48d6295cae"}, {"en": "I wouldn't join the team unless my best friend joined too.", "es": "No me uniría al equipo a menos que mi mejor amigo también se uniera.", "v": "f", "img": "u:photo-1622659097509-4d56de14539e", "au": "y4fc3c2baf0"}, {"en": "What would you do if you found a wallet?", "es": "¿Qué harías si encontraras una billetera?", "v": "m", "img": "u:photo-1728071691969-0d4e893b6b20", "au": "y4c34060396"}, {"en": "If I were in your shoes, I'd speak up.", "es": "Si estuviera en tu lugar, daría mi opinión.", "v": "f", "img": "u:photo-1715610258704-e8f9f5710fe0", "au": "y42d30ceeff"}, {"en": "I'd give it a shot if I were taller.", "es": "Lo intentaría si fuera más alto.", "v": "m", "img": "u:photo-1629901925121-8a141c2a42f4", "au": "y4dc6ff94d3"}, {"en": "Would you change schools to play on a better team?", "es": "¿Te cambiarías de colegio para jugar en un mejor equipo?", "v": "f", "img": "u:photo-1622659097509-4d56de14539e", "au": "y4f30725004"}]}, "t3p1": {"tip": "<p>El <b>tercer condicional</b> imagina un <b>pasado diferente</b>: algo que NO pasó y su resultado imaginario.</p>\n<p><b>If + had + participio, would have + participio</b><br><i>If I <b>hadn't overslept</b>, I <b>would have caught</b> the bus.</i><br>(Realidad: me quedé dormido y perdí el bus.)</p>\n<p>Cambia el modal según la certeza: <b>would have</b> (seguro) · <b>could have</b> (habría podido) · <b>might have</b> (quizás habría).</p>\n<p><b>If only + had + participio</b> expresa un lamento fuerte: <i>If only I <b>had listened</b> to you!</i></p>\n<p>En el habla rápida: <i>would have</i> → <b>would've</b> (<i>wúdov</i>), <i>hadn't</i> → <i>jádent</i>.</p>", "vocab": [{"en": "miss the bus", "es": "perder el bus", "v": "f", "img": "u:photo-1613688263142-67f1e0c25ef1", "au": "y450a583708"}, {"en": "oversleep", "es": "quedarse dormido", "v": "m", "img": "u:photo-1721815714586-73849a2a163b", "au": "y472cb16c5e"}, {"en": "a close call", "es": "algo que casi pasa", "v": "f", "img": "u:photo-1711581804833-ec0f662448dd", "au": "y43010eb191"}, {"en": "if only", "es": "ojalá / si tan solo", "v": "m", "img": "u:photo-1512981548919-4a460438cb4e", "au": "y436e704fae"}, {"en": "in hindsight", "es": "en retrospectiva", "v": "f", "img": "u:photo-1551085780-35e6a3fe7871", "au": "y47d6953540"}, {"en": "take the wrong path", "es": "tomar el camino equivocado", "v": "m", "img": "u:photo-1774886130135-2c5650465511", "au": "y4d3a76685b"}, {"en": "pass up a chance", "es": "dejar pasar una oportunidad", "v": "f", "img": "u:photo-1630086349260-daaf711a8f44", "au": "y42cd44d95a"}, {"en": "it would have been", "es": "habría sido", "v": "m", "img": "u:photo-1524503033411-c9566986fc8f", "au": "y4ec8f799c4"}], "sentences": [{"en": "If I hadn't overslept, I would have caught the bus.", "es": "Si no me hubiera quedado dormido, habría alcanzado el bus.", "v": "m", "img": "u:photo-1583508805133-8fd03a9916d4", "au": "y4d39ad18b9"}, {"en": "If we had taken the right path, we'd have arrived on time.", "es": "Si hubiéramos tomado el camino correcto, habríamos llegado a tiempo.", "v": "f", "img": "u:photo-1770196567087-b59ba06aef12", "au": "y4cb7c2e157"}, {"en": "She might have made the team if she'd tried out earlier.", "es": "Quizás habría entrado al equipo si hubiera hecho la prueba antes.", "v": "m", "img": "u:photo-1567781830902-685fb3401f1d", "au": "y43126db1b9"}, {"en": "If only I had listened to my mom!", "es": "¡Si tan solo hubiera escuchado a mi mamá!", "v": "f", "img": "u:photo-1475609471617-0ef53b59cff5", "au": "y4c36e1cc69"}, {"en": "It would have been a disaster if you hadn't called.", "es": "Habría sido un desastre si no hubieras llamado.", "v": "m", "img": "u:photo-1615477618234-c79fcdf30fe2", "au": "y4859a4e94a"}, {"en": "In hindsight, we could have saved a lot of time.", "es": "En retrospectiva, habríamos podido ahorrar mucho tiempo.", "v": "f", "img": "u:photo-1602162786736-1575a5b1be76", "au": "y4b1b15d95c"}]}, "t3p2": {"tip": "<p><b>should have / shouldn't have + participio</b> = crítica o arrepentimiento sobre el pasado:<br><i>I <b>should have saved</b> my game.</i> (no lo hice) · <i>You <b>shouldn't have said</b> that.</i> (lo dijiste)</p>\n<p><b>Condicionales mixtos</b> combinan tiempos:</p>\n<p>1. <b>Pasado → presente</b>: <b>If + had + participio, would + verbo</b><br><i>If I <b>had practiced</b> more last year, I <b>would be</b> on the team now.</i></p>\n<p>2. <b>Presente → pasado</b>: <b>If + pasado simple, would have + participio</b><br><i>If I <b>spoke</b> Japanese, I <b>would have understood</b> the movie yesterday.</i></p>\n<p>Pista: busca palabras como <b>now, today, still</b> (resultado presente) o <b>yesterday, last year</b> (resultado pasado).</p>", "vocab": [{"en": "should have known", "es": "debí haberlo sabido", "v": "f", "img": "u:photo-1528820713738-a43de1b61084", "au": "y493f3b4427"}, {"en": "shouldn't have said that", "es": "no debí haber dicho eso", "v": "m", "img": "u:photo-1773789203144-0a2b3a918e9d", "au": "y45697bd7c9"}, {"en": "learn the hard way", "es": "aprender a las malas", "v": "f", "img": "u:photo-1762256268350-7b11c9f859df", "au": "y461bc0a31a"}, {"en": "jump to conclusions", "es": "sacar conclusiones apresuradas", "v": "m", "img": "u:photo-1593793602373-ca02114d4a3f", "au": "y47a1440324"}, {"en": "blow it", "es": "echarlo a perder", "v": "f", "img": "u:photo-1633828763399-e29f1cd3f4c1", "au": "y400458358a"}, {"en": "burn bridges", "es": "quemar los puentes", "v": "m", "img": "u:photo-1634672373674-078a1f6134af", "au": "y4b2886ce55"}, {"en": "second-guess", "es": "dudar de (una decisión)", "v": "f", "img": "u:photo-1502466650593-b65a2c690da0", "au": "y42b424a225"}, {"en": "a wake-up call", "es": "una llamada de atención", "v": "m", "img": "u:photo-1550534791-2677533605ab", "au": "y4c99f59a36"}], "sentences": [{"en": "I should have saved my game.", "es": "Debí haber guardado mi partida.", "v": "m", "img": "u:photo-1554410637-1a8267402b57", "au": "y42e3c33a6d"}, {"en": "You shouldn't have jumped to conclusions.", "es": "No debiste sacar conclusiones apresuradas.", "v": "f", "img": "u:photo-1772471586699-a770c551f442", "au": "y4fc3be61c5"}, {"en": "If I had practiced more, I would be on the team now.", "es": "Si hubiera practicado más, ahora estaría en el equipo.", "v": "m", "img": "u:photo-1520399636535-24741e71b160", "au": "y405735b6b0"}, {"en": "If she weren't so shy, she would have spoken up.", "es": "Si no fuera tan tímida, habría dado su opinión.", "v": "f", "img": "u:photo-1649386525679-214da4fa6676", "au": "y47114a2285"}, {"en": "We shouldn't have left the project until the last minute.", "es": "No debimos dejar el proyecto para el último minuto.", "v": "m", "img": "u:photo-1557734864-c78b6dfef1b1", "au": "y4c88af1ab0"}, {"en": "If we had planted the seeds earlier, our garden would look better today.", "es": "Si hubiéramos sembrado las semillas antes, nuestro jardín se vería mejor hoy.", "v": "f", "img": "u:photo-1611735341450-74d61e660ad2", "au": "y445f9eefad"}]}, "t4p1": {"tip": "<p>Algunos verbos van seguidos de <b>-ing</b> (gerundio) y otros de <b>to + verbo</b> (infinitivo). ¡Hay que memorizarlos!</p>\n<p><b>+ -ing</b>: enjoy, avoid, consider, keep, mind, finish, suggest, recommend, deny, miss, practice, can't stand, can't help, give up, put off<br><i>I <b>avoid eating</b> junk food before a game.</i> · <i>Would you <b>mind closing</b> the window?</i></p>\n<p><b>+ to</b>: decide, agree, refuse, afford, manage, plan, hope, expect, offer, promise, seem, pretend, tend, learn, want, would like<br><i>She <b>refused to share</b> her fries.</i> · <i>We <b>can't afford to buy</b> a new game console.</i></p>\n<p>Después de una <b>preposición</b> siempre <b>-ing</b>: <i>I'm looking forward <b>to seeing</b> you</i> (aquí <i>to</i> es preposición) · <i>I'm used <b>to getting up</b> early.</i></p>\n<p><b>like, love, hate, prefer, start, begin, continue</b> aceptan ambos sin cambiar mucho el sentido.</p>", "vocab": [{"en": "enjoy playing outside", "es": "disfrutar jugar afuera", "v": "f", "img": "u:photo-1627764940620-90393d0e8c34", "au": "y44bc594078"}, {"en": "avoid eating junk food", "es": "evitar comer comida chatarra", "v": "m", "img": "u:photo-1569420067112-b57b4f024595", "au": "y4a3c918131"}, {"en": "consider joining", "es": "considerar unirse", "v": "f", "img": "u:photo-1725818660598-43b9012a8168", "au": "y4b660ea097"}, {"en": "keep trying", "es": "seguir intentando", "v": "m", "img": "u:photo-1663243216708-a7831e1a9c55", "au": "y471972237e"}, {"en": "can't stand waiting", "es": "no soportar esperar", "v": "f", "img": "u:photo-1677091407437-5c0a10905046", "au": "y4d24a2fe64"}, {"en": "decide to learn", "es": "decidir aprender", "v": "m", "img": "u:photo-1758524944402-1903b38f848f", "au": "y47584b1018"}, {"en": "agree to help", "es": "aceptar ayudar", "v": "f", "img": "u:photo-1627764940620-90393d0e8c34", "au": "y481d170041"}, {"en": "refuse to share", "es": "negarse a compartir", "v": "m", "img": "u:photo-1648171022716-a21cbc8ca5b9", "au": "y48d9977cd7"}], "sentences": [{"en": "I really enjoy playing outside after school.", "es": "Disfruto mucho jugar afuera después del colegio.", "v": "m", "img": "u:photo-1606092195730-5d7b9af1efc5", "au": "y4cea161b70"}, {"en": "We're considering joining the chess club.", "es": "Estamos considerando unirnos al club de ajedrez.", "v": "f", "img": "u:photo-1725818660598-43b9012a8168", "au": "y44aa4194da"}, {"en": "He refused to share his popcorn.", "es": "Se negó a compartir sus palomitas.", "v": "m", "img": "u:photo-1701588783356-31cd5529dbaa", "au": "y43bb39e676"}, {"en": "We can't afford to buy a new game console.", "es": "No podemos permitirnos comprar una consola nueva.", "v": "f", "img": "u:photo-1768166210760-9c9a4299c436", "au": "y421c7cb263"}, {"en": "I'm looking forward to seeing your family.", "es": "Tengo muchas ganas de conocer a tu familia.", "v": "m", "img": "u:photo-1581952976147-5a2d15560349", "au": "y407668c135"}, {"en": "She finally managed to finish her science project.", "es": "Por fin logró terminar su proyecto de ciencias.", "v": "f", "img": "u:photo-1780265596033-47b8cb06c794", "au": "y438237ff0a"}]}, "t4p2": {"tip": "<p>Estos verbos aceptan <b>-ing</b> y <b>to</b>, pero <b>cambia el significado</b>:</p>\n<p><b>remember / forget + to</b> = acordarse/olvidar <b>hacer</b> algo (tarea pendiente) · <b>+ -ing</b> = recordar algo que <b>ya hiciste</b>.<br><i>Remember <b>to lock</b> the door.</i> vs. <i>I remember <b>locking</b> the door.</i></p>\n<p><b>stop + -ing</b> = dejar de hacer · <b>stop + to</b> = parar <b>para</b> hacer otra cosa.<br><i>She stopped <b>talking</b>.</i> (ya no habla) vs. <i>She stopped <b>to talk</b> to a friend.</i> (paró para hablar)</p>\n<p><b>try + to</b> = esforzarse (es difícil) · <b>try + -ing</b> = probar algo como experimento.<br><i>Try <b>to stay</b> calm.</i> vs. <i>Try <b>restarting</b> the tablet.</i></p>\n<p><b>regret + to</b> = lamentar informar (formal) · <b>regret + -ing</b> = arrepentirse de algo hecho.</p>\n<p>Después de preposición (<b>in, of, about, at, without, instead of, before, after</b>) → siempre <b>-ing</b>: <i>She's good <b>at drawing</b>.</i></p>", "vocab": [{"en": "remember to lock the door", "es": "acordarse de cerrar con llave", "v": "f", "img": "u:photo-1725940900270-84162cbe60e9", "au": "y4987c5a163"}, {"en": "remember locking the door", "es": "recordar haber cerrado con llave", "v": "m", "img": "u:photo-1677951570313-b0750351c461", "au": "y414ad76a3b"}, {"en": "forget to call", "es": "olvidar llamar", "v": "f", "img": "u:photo-1703868175568-d5e194332ed4", "au": "y496f752bc9"}, {"en": "never forget seeing", "es": "nunca olvidar haber visto", "v": "m", "img": "u:photo-1543266502-7a301a17e75e", "au": "y4a9c4c0223"}, {"en": "stop to buy ice cream", "es": "parar para comprar helado", "v": "f", "img": "u:photo-1505616485412-adfcd5561e31", "au": "y400e0cd9ba"}, {"en": "stop eating candy", "es": "dejar de comer dulces", "v": "m", "img": "u:photo-1708528182738-28601672f14c", "au": "y466df05e47"}, {"en": "try restarting it", "es": "probar reiniciándolo", "v": "f", "img": "u:photo-1495654794940-1c0cd2aeedc1", "au": "y49654e2316"}, {"en": "try to stay calm", "es": "tratar de mantener la calma", "v": "m", "img": "u:photo-1504696787079-f4d70e6800be", "au": "y43f5074afc"}], "sentences": [{"en": "Remember to lock the door when you leave.", "es": "Acuérdate de cerrar con llave cuando salgas.", "v": "m", "img": "u:photo-1607900840367-a83dcd63296d", "au": "y497db74d8e"}, {"en": "I don't remember feeding the fish.", "es": "No recuerdo haberles dado de comer a los peces.", "v": "f", "img": "u:photo-1764175760902-9cf284d444de", "au": "y4b60dde6b5"}, {"en": "He stopped eating candy last year.", "es": "Dejó de comer dulces el año pasado.", "v": "m", "img": "u:photo-1629646546565-47267ed247b4", "au": "y44f4018f8b"}, {"en": "We stopped to buy ice cream on the way.", "es": "Paramos para comprar helado en el camino.", "v": "f", "img": "u:photo-1629385701021-fcd568a743e8", "au": "y435cf12eea"}, {"en": "Have you tried restarting the tablet?", "es": "¿Has probado reiniciando la tableta?", "v": "m", "img": "u:photo-1542751110-97427bbecf20", "au": "y4cfd569620"}, {"en": "I'll never forget seeing the Grand Canyon.", "es": "Nunca olvidaré haber visto el Gran Cañón.", "v": "f", "img": "u:photo-1575527048208-6475b441e0a0", "au": "y40cc84c59c"}]}, "t5p1": {"tip": "<p>Para decir que estás <b>de acuerdo</b> (yo también / yo tampoco) repites el <b>auxiliar</b> de la oración:</p>\n<p>Oración positiva → <b>So + auxiliar + sujeto</b><br><i>I love pizza. → <b>So do I.</b></i> · <i>I've been to Chicago. → <b>So have I.</b></i> · <i>I'm tired. → <b>So am I.</b></i></p>\n<p>Oración negativa → <b>Neither + auxiliar (positivo) + sujeto</b><br><i>I don't eat meat. → <b>Neither do I.</b></i> · <i>I can't swim. → <b>Neither can I.</b></i></p>\n<p>Para estar <b>en desacuerdo</b>, usa sujeto + auxiliar contrario: <i>I love pizza. → <b>Oh, I don't.</b></i> · <i>I haven't seen it. → <b>Really? I have.</b></i></p>\n<p>El auxiliar depende del tiempo: presente → <b>do/does</b> · pasado → <b>did</b> · perfecto → <b>have/has</b> · <b>be, can, will, would</b> se repiten.</p>", "vocab": [{"en": "So do I.", "es": "Yo también.", "v": "f", "img": "u:photo-1530047139082-5435ca3c4614", "au": "y40d8d15ef0"}, {"en": "Neither do I.", "es": "Yo tampoco.", "v": "m", "img": "u:photo-1524503033411-c9566986fc8f", "au": "y4f100b1fe9"}, {"en": "Me too.", "es": "Yo también (informal).", "v": "f", "img": "u:photo-1752650735509-58f11eaa2e10", "au": "y43def550b6"}, {"en": "Me neither.", "es": "Yo tampoco (informal).", "v": "m", "img": "u:photo-1653576840776-47a12be506e4", "au": "y44f80be77d"}, {"en": "I do. / I don't.", "es": "Yo sí. / Yo no.", "v": "f", "img": "u:photo-1611003996105-3899f47c0b5b", "au": "y41f20f87ca"}, {"en": "So have I.", "es": "Yo también (con have).", "v": "m", "img": "u:photo-1588792164216-c72e6a14ae0b", "au": "y4702188525"}, {"en": "Neither can I.", "es": "Yo tampoco puedo.", "v": "f", "img": "u:photo-1592484806287-7bc9c8af5405", "au": "y4714e0288d"}, {"en": "Same here.", "es": "Lo mismo digo.", "v": "m", "img": "u:photo-1582298538104-fe2e74c27f59", "au": "y4e6d9499c4"}], "sentences": [{"en": "I've never been to Alaska. Neither have I.", "es": "Nunca he ido a Alaska. Yo tampoco.", "v": "m", "img": "u:photo-1483921020237-2ff51e8e4b22", "au": "y45127ebe36"}, {"en": "I'm exhausted after this week. So am I.", "es": "Estoy agotado después de esta semana. Yo también.", "v": "f", "img": "u:photo-1710207656228-2c3330a14c49", "au": "y4852b401ca"}, {"en": "I can't stand long car rides. Neither can I.", "es": "No soporto los viajes largos en carro. Yo tampoco.", "v": "m", "img": "u:photo-1527387605057-758074d259eb", "au": "y4cf26cbaaa"}, {"en": "I loved the movie last night. So did I.", "es": "Me encantó la película de anoche. A mí también.", "v": "f", "img": "u:photo-1665827491450-c6f329f2285c", "au": "y4610934b9d"}, {"en": "I don't like spicy food. Oh, really? I do.", "es": "No me gusta la comida picante. ¿En serio? A mí sí.", "v": "m", "img": "u:photo-1777598405371-e657109ddd50", "au": "y42b5d865a2"}, {"en": "We have a lot in common.", "es": "Tenemos mucho en común.", "v": "f", "img": "u:photo-1489942986787-cded4ecf962e", "au": "y4f06b12a99"}]}, "t5p2": {"tip": "<p>Hay varias formas de decir <b>yo tampoco</b>:<br><i>I don't drink soda.</i> → <b>Neither do I.</b> = <b>Nor do I.</b> (formal) = <b>I don't either.</b> = <b>Me neither.</b> (informal)</p>\n<p><b>either</b> va al final con verbo <b>negativo</b>; <b>neither</b> va al principio con verbo <b>positivo</b>.<br>Incorrecto: <i>I don't neither</i> · Correcto: <i>I don't <b>either</b></i> · Correcto: <i><b>Neither</b> do I</i></p>\n<p><b>neither A nor B</b> = ni A ni B (verbo positivo): <i><b>Neither</b> the teacher <b>nor</b> the principal answered.</i><br><b>either A or B</b> = o A o B: <i>You can have <b>either</b> pizza <b>or</b> pasta.</i><br><b>both A and B</b> = tanto A como B: <i><b>Both</b> Miami <b>and</b> Orlando are hot.</i></p>\n<p><b>Reacciones cortas</b> con auxiliar muestran interés: <i>I made the team. → <b>You did?</b></i> · <i>I'm getting a puppy. → <b>Are you?</b> Congrats!</i></p>", "vocab": [{"en": "I don't either.", "es": "Yo tampoco (con either).", "v": "f", "img": "u:photo-1651044454119-3535e0b28861", "au": "y49ff53f34e"}, {"en": "not… either", "es": "tampoco (con verbo negativo)", "v": "m", "img": "u:photo-1483193722442-5422d99849bc", "au": "y4d1fc8da99"}, {"en": "neither… nor", "es": "ni… ni", "v": "f", "img": "u:photo-1567934124115-2eca8953796b", "au": "y45d0b24342"}, {"en": "either… or", "es": "o… o", "v": "m", "img": "u:photo-1552580715-4d9bc27f1e2f", "au": "y4a69df4461"}, {"en": "both… and", "es": "tanto… como", "v": "f", "img": "u:photo-1450778869180-41d0601e046e", "au": "y46975d4377"}, {"en": "So did she.", "es": "Ella también (pasado).", "v": "m", "img": "u:photo-1774748855472-aee13a133fd1", "au": "y4f393eefee"}, {"en": "Neither was I.", "es": "Yo tampoco estaba.", "v": "f", "img": "u:photo-1763098844157-d0fffcc966a1", "au": "y4598f3d73c"}, {"en": "Nor do I.", "es": "Ni yo (formal).", "v": "m", "img": "u:photo-1771185716594-4cf3f0b284a7", "au": "y48649e2dcd"}], "sentences": [{"en": "I didn't get the message either.", "es": "Yo tampoco recibí el mensaje.", "v": "m", "img": "u:photo-1703868175568-d5e194332ed4", "au": "y420abd46b0"}, {"en": "Neither my teacher nor my classmates knew about it.", "es": "Ni mi profesora ni mis compañeros lo sabían.", "v": "f", "img": "u:photo-1509062522246-3755977927d7", "au": "y4417517ec9"}, {"en": "You can have either pizza or pasta for dinner.", "es": "Puedes comer pizza o pasta en la cena.", "v": "m", "img": "u:photo-1707870678076-40ba56a65ece", "au": "y4b102b7a4e"}, {"en": "Both Miami and San Diego have great beaches.", "es": "Tanto Miami como San Diego tienen excelentes playas.", "v": "f", "img": "u:photo-1763113975476-e9037317497f", "au": "y4d6eb90b2b"}, {"en": "She wasn't at practice, and neither was I.", "es": "Ella no estuvo en el entrenamiento, y yo tampoco.", "v": "m", "img": "u:photo-1517747614396-d21a78b850e8", "au": "y4f6d8d05d1"}, {"en": "I'd love to study abroad. So would I!", "es": "Me encantaría estudiar en el extranjero. ¡A mí también!", "v": "f", "img": "u:photo-1594608661623-aa0bd3a69d98", "au": "y4845daba84"}]}, "t6p1": {"tip": "<p><b>Presente perfecto continuo</b>: <b>have / has + been + -ing</b></p>\n<p><b>Duración</b> de algo que empezó en el pasado y <b>sigue</b>: <i>I<b>'ve been playing</b> soccer <b>since</b> 2020 / <b>for</b> five years.</i><br>Pregunta: <i><b>How long have you been</b> learning the piano?</i></p>\n<p><b>Evidencia visible</b> de una actividad reciente: <i>Your eyes are red. <b>Have you been crying?</b></i> · <i>The streets are wet. It<b>'s been raining</b>.</i></p>\n<p><b>been doing</b> (actividad, proceso) vs. <b>have done</b> (resultado, cantidad):<br><i>I<b>'ve been reading</b> comics all morning.</i> (la actividad) · <i>I<b>'ve read</b> five comics.</i> (el resultado)</p>\n<p><b>for</b> + periodo (for two hours) · <b>since</b> + punto de inicio (since Monday, since 2019).</p>", "vocab": [{"en": "I've been playing soccer since 2020.", "es": "Juego fútbol desde 2020.", "v": "f", "img": "u:photo-1777489689168-497290f235d5", "au": "y49a65d7672"}, {"en": "have been waiting for ages", "es": "llevar una eternidad esperando", "v": "m", "img": "u:photo-1696545720052-b2c622c058b5", "au": "y4b762bb0fb"}, {"en": "out of breath", "es": "sin aliento", "v": "f", "img": "u:photo-1511031579861-4b57e01e19e5", "au": "y4f90d52cc3"}, {"en": "covered in paint", "es": "cubierto de pintura", "v": "m", "img": "u:photo-1607211851821-8be3cd6146f0", "au": "y48a0f0b64f"}, {"en": "puffy eyes", "es": "ojos hinchados", "v": "f", "img": "u:photo-1728287186395-c230e0e016f0", "au": "y46ed2ce481"}, {"en": "It's been pouring.", "es": "Ha estado lloviendo a cántaros.", "v": "m", "img": "u:photo-1576514864427-f0809d2b66eb", "au": "y4fa14cbb32"}, {"en": "binge-watch", "es": "ver series en maratón", "v": "f", "img": "u:photo-1714978444538-9097293e5b20", "au": "y4c790b9162"}, {"en": "lately", "es": "últimamente", "v": "m", "img": "u:photo-1599689868384-59cb2b01bb21", "au": "y482f307de0"}], "sentences": [{"en": "I've been taking guitar lessons since 2021.", "es": "Tomo clases de guitarra desde 2021.", "v": "f", "img": "u:photo-1474752651386-dc296d69dc90", "au": "y464d33e269"}, {"en": "You're out of breath. Have you been running?", "es": "Estás sin aliento. ¿Has estado corriendo?", "v": "m", "img": "u:photo-1532341556711-1c37110eaaac", "au": "y419809559e"}, {"en": "It's been pouring all morning, so recess is inside.", "es": "Ha llovido a cántaros toda la mañana, así que el recreo es adentro.", "v": "f", "img": "u:photo-1759328380815-ddf77dca65ad", "au": "y44a261b301"}, {"en": "How long have you been learning English?", "es": "¿Cuánto tiempo llevas aprendiendo inglés?", "v": "m", "img": "u:photo-1514369118554-e20d93546b30", "au": "y49474e4db4"}, {"en": "We've been binge-watching that cartoon all weekend.", "es": "Hemos visto esa caricatura en maratón todo el fin de semana.", "v": "f", "img": "u:photo-1752652010704-11c6a68ce66e", "au": "y440ba409c8"}, {"en": "My little brother is covered in paint. He's been painting!", "es": "Mi hermanito está cubierto de pintura. ¡Ha estado pintando!", "v": "m", "img": "u:photo-1560421683-6856ea585c78", "au": "y479817e0f2"}]}, "t6p2": {"tip": "<p><b>Pasado perfecto continuo</b>: <b>had been + -ing</b> = una acción que <b>duró</b> hasta un momento del pasado.</p>\n<p><i>We <b>had been waiting</b> for two hours <b>when</b> the concert finally started.</i><br><i>She was exhausted because she <b>had been studying</b> nonstop.</i> (causa en el pasado)</p>\n<p>Compara: <b>has been doing</b> (hasta <u>ahora</u>) · <b>had been doing</b> (hasta un momento del <u>pasado</u>).</p>\n<p><b>Verbos de estado</b> NO usan forma continua: <b>know, own, belong, believe, understand, like, love, hate, need, want, seem, prefer, mean</b>.<br>Mal: <i>I've been knowing him for years.</i> → Bien: <i>I<b>'ve known</b> him for years.</i><br>Mal: <i>She had been owning the bike.</i> → Bien: <i>She <b>had owned</b> the bike for three years.</i></p>", "vocab": [{"en": "had been waiting", "es": "había estado esperando", "v": "f", "img": "u:photo-1594608661623-aa0bd3a69d98", "au": "y47e0ff954a"}, {"en": "had been saving up", "es": "había estado ahorrando", "v": "m", "img": "u:photo-1656049471454-ff3c59812741", "au": "y41196aa0bd"}, {"en": "run out of battery", "es": "quedarse sin batería", "v": "f", "img": "u:photo-1536692192939-f1547f1cde39", "au": "y4f6422ee42"}, {"en": "exhausted", "es": "agotado", "v": "m", "img": "u:photo-1608354580566-8cdf7e570924", "au": "y4625609e7d"}, {"en": "make the team", "es": "quedar en el equipo", "v": "f", "img": "u:photo-1622659097509-4d56de14539e", "au": "y4545139ad2"}, {"en": "own", "es": "ser dueño de", "v": "m", "img": "u:photo-1650946429014-2320f0539a7e", "au": "y4f5fd9fbc7"}, {"en": "belong to", "es": "pertenecer a", "v": "f", "img": "u:photo-1528569937393-ee892b976859", "au": "y4644e0c71c"}, {"en": "believe", "es": "creer", "v": "m", "img": "u:photo-1758876022649-ab858801c6dc", "au": "y4b0d50a8be"}], "sentences": [{"en": "We had been waiting for two hours when the concert started.", "es": "Llevábamos dos horas esperando cuando empezó el concierto.", "v": "f", "img": "u:photo-1501386761578-eac5c94b800a", "au": "y49856bca69"}, {"en": "She was exhausted because she had been studying nonstop.", "es": "Estaba agotada porque había estado estudiando sin parar.", "v": "m", "img": "u:photo-1713947503867-3b27964f042b", "au": "y4f60f748b9"}, {"en": "He had been saving up for months before he bought the bike.", "es": "Había estado ahorrando durante meses antes de comprar la bicicleta.", "v": "f", "img": "u:photo-1650946429014-2320f0539a7e", "au": "y4743d5e301"}, {"en": "I've known my best friend since first grade.", "es": "Conozco a mi mejor amigo desde primer grado.", "v": "m", "img": "u:photo-1530047139082-5435ca3c4614", "au": "y44352adeea"}, {"en": "She had been training for months, so she finally made the team.", "es": "Había entrenado durante meses, así que por fin quedó en el equipo.", "v": "f", "img": "u:photo-1650501890232-886c08e79a27", "au": "y48e69031cc"}, {"en": "This old guitar has belonged to my family for fifty years.", "es": "Esta guitarra vieja ha pertenecido a mi familia durante cincuenta años.", "v": "m", "img": "u:photo-1558098329-a11cff621064", "au": "y441200a1e5"}]}, "t7p1": {"tip": "<p>Las <b>cláusulas relativas especificativas</b> (defining) dicen <b>exactamente de quién o de qué</b> hablamos. No llevan comas.</p>\n<p><b>who</b> (o <b>that</b>) → personas: <i>The girl <b>who</b> called you is my cousin.</i><br><b>which</b> (o <b>that</b>) → cosas: <i>This is the app <b>which/that</b> helps me with math.</i><br><b>whose</b> → posesión (cuyo): <i>He's the neighbor <b>whose</b> dog barks all night.</i><br><b>where</b> → lugares: <i>That's the park <b>where</b> we met.</i><br><b>when</b> → momentos: <i>I remember the day <b>when</b> I got my puppy.</i><br><b>why</b> → razones: <i>That's the reason <b>why</b> I was late.</i></p>\n<p>No repitas el sujeto: Mal: <i>The man who <b>he</b> lives next door</i> → Bien: <i>The man who lives next door</i>.</p>", "vocab": [{"en": "who", "es": "que / quien (personas)", "v": "f", "img": "u:photo-1577896851231-70ef18881754", "au": "y473d3fe304"}, {"en": "which", "es": "que / el cual (cosas)", "v": "m", "img": "u:photo-1495654794940-1c0cd2aeedc1", "au": "y444df8f797"}, {"en": "whose", "es": "cuyo / cuya", "v": "f", "img": "u:photo-1758633226887-8a1164f408a7", "au": "y4b192d4454"}, {"en": "where", "es": "donde (lugares)", "v": "m", "img": "u:photo-1786453732488-e4ea65d0d0e8", "au": "y411128b6c2"}, {"en": "when", "es": "cuando (momentos)", "v": "f", "img": "u:photo-1772724317403-63337bf58fff", "au": "y4abcbd9f67"}, {"en": "classmate", "es": "compañero de clase", "v": "m", "img": "u:photo-1577896851231-70ef18881754", "au": "y4173507fe8"}, {"en": "neighbor", "es": "vecino", "v": "f", "img": "u:photo-1770563181157-f57aa478799b", "au": "y4d923ea6c6"}, {"en": "neighborhood", "es": "barrio / vecindario", "v": "m", "img": "u:photo-1784854519200-8ba4da39d703", "au": "y470d918650"}], "sentences": [{"en": "A classmate is a person who studies in your class.", "es": "Un compañero de clase es una persona que estudia en tu clase.", "v": "f", "img": "u:photo-1509062522246-3755977927d7", "au": "y4305b1730b"}, {"en": "This is the app that helped me learn English.", "es": "Esta es la app que me ayudó a aprender inglés.", "v": "m", "img": "u:photo-1495654794940-1c0cd2aeedc1", "au": "y46a2c5a724"}, {"en": "She's the classmate whose idea won the science fair.", "es": "Ella es la compañera cuya idea ganó la feria de ciencias.", "v": "f", "img": "u:photo-1633828763399-e29f1cd3f4c1", "au": "y4303177158"}, {"en": "That's the neighborhood where I grew up.", "es": "Ese es el barrio donde crecí.", "v": "m", "img": "u:photo-1555636222-cae831e670b3", "au": "y42e3d22a63"}, {"en": "I'll never forget the day when I got my puppy.", "es": "Nunca olvidaré el día en que recibí a mi cachorro.", "v": "f", "img": "u:photo-1586537333626-238ebc85e19f", "au": "y48f8f24aad"}, {"en": "The reason why I called is to invite you.", "es": "La razón por la que llamé es para invitarte.", "v": "m", "img": "u:photo-1758874961005-9da9077cd44d", "au": "y4279e86f76"}]}, "t7p2": {"tip": "<p><b>Explicativas (non-defining)</b>: dan información <b>extra</b> y van <b>entre comas</b>. Aquí <b>NO</b> se puede usar <i>that</i>.<br><i>My brother<b>, who is sixteen,</b> plays the drums.</i> (solo tengo un hermano)</p>\n<p><b>which</b> puede referirse a <b>toda la oración anterior</b>: <i>The school trip was canceled<b>, which</b> ruined our plans.</i> (lo cual)</p>\n<p><b>Omitir el pronombre</b>: en las especificativas, si el pronombre es <b>objeto</b> (va seguido de otro sujeto), puedes quitarlo:<br><i>The friends (<s>who</s>) I play with are great.</i> · Pero NO si es sujeto: <i>The boy <b>who</b> called…</i></p>\n<p><b>Preposiciones</b>: informal al final → <i>the city I live <b>in</b></i> · formal antes del pronombre → <i>the city <b>in which</b> I live</i> · <i>the people <b>with whom</b> I study</i>.</p>\n<p>Cuantificadores: <b>most of whom, some of which, all of which, none of whom</b>.</p>", "vocab": [{"en": ", which surprised everyone", "es": ", lo cual sorprendió a todos", "v": "f", "img": "u:photo-1593793602373-ca02114d4a3f", "au": "y4c39eaa658"}, {"en": "the city in which", "es": "la ciudad en la que", "v": "m", "img": "u:photo-1767398910226-f4f205965da9", "au": "y42053f3d9d"}, {"en": "the friends I play with", "es": "los amigos con los que juego", "v": "f", "img": "u:photo-1614113036347-9f60df80730a", "au": "y48980b5b8e"}, {"en": "most of whom", "es": "la mayoría de los cuales", "v": "m", "img": "u:photo-1758270704763-22072a90d3b6", "au": "y4d4845d18a"}, {"en": "whom", "es": "a quien (formal)", "v": "f", "img": "u:photo-1646617747566-b7e784435a48", "au": "y4aaad05925"}, {"en": "the house where I grew up", "es": "la casa donde crecí", "v": "m", "img": "u:photo-1734616048414-94ba753a46b4", "au": "y453bb71b5a"}, {"en": "my sister, who lives in Boston", "es": "mi hermana, que vive en Boston", "v": "f", "img": "u:photo-1723066496620-6bee4e3f1c7b", "au": "y43e164ca17"}, {"en": "which is why", "es": "razón por la cual", "v": "m", "img": "u:photo-1789265176455-1c8dfe12de18", "au": "y4b06390847"}], "sentences": [{"en": "My brother, who is sixteen, plays the drums.", "es": "Mi hermano, que tiene dieciséis años, toca la batería.", "v": "f", "img": "u:photo-1523450953970-3a645b5484f7", "au": "y4b45a69974"}, {"en": "The school trip was canceled, which ruined our plans.", "es": "Cancelaron la excursión del colegio, lo cual arruinó nuestros planes.", "v": "m", "img": "u:photo-1697204120925-4852eb4bb48f", "au": "y43b1dace26"}, {"en": "The friends I play with are really kind.", "es": "Los amigos con los que juego son muy amables.", "v": "f", "img": "u:photo-1599376672737-bd66af54c8f5", "au": "y47c094e8db"}, {"en": "Bogotá is the city in which I was born.", "es": "Bogotá es la ciudad en la que nací.", "v": "m", "img": "u:photo-1689792528953-8f54cdea381a", "au": "y4c46f1e448"}, {"en": "Our class has thirty students, most of whom love sports.", "es": "Nuestra clase tiene treinta estudiantes, la mayoría de los cuales aman los deportes.", "v": "f", "img": "u:photo-1525088068454-ff2c453e50e9", "au": "y495ad2131b"}, {"en": "I missed the bus, which is why I was late.", "es": "Perdí el bus, razón por la cual llegué tarde.", "v": "m", "img": "u:photo-1613688263142-67f1e0c25ef1", "au": "y4ee90589ba"}]}, "t8p1": {"tip": "<p>Una <b>tag question</b> (pregunta coletilla) es la pequeña pregunta al final de una oración: equivale a <i>¿verdad?</i>, <i>¿no?</i>, <i>¿cierto?</i> en español.</p>\n<p><b>Regla de oro:</b> oración <b>positiva</b> → coletilla <b>negativa</b>; oración <b>negativa</b> → coletilla <b>positiva</b>.<br>\n<i>You <b>are</b> tired, <b>aren't</b> you?</i> · <i>You <b>aren't</b> tired, <b>are</b> you?</i></p>\n<p>La coletilla repite el <b>auxiliar</b> de la oración (be, have, can, will, should…). Si no hay auxiliar, usa <b>do / does / did</b>:<br>\n<i>She <b>plays</b> the piano, <b>doesn't</b> she?</i> · <i>They <b>called</b>, <b>didn't</b> they?</i></p>\n<p>La coletilla siempre usa un <b>pronombre</b>: <i>Your teacher</i> → <b>he/she</b>; <i>The party</i> → <b>it</b>; <i>There is…</i> → <b>isn't there?</b></p>\n<p>Cuidado con <b>'s</b>: puede ser <b>is</b> o <b>has</b>. <i>She's finished, <b>hasn't</b> she?</i> (has finished) · <i>She's tired, <b>isn't</b> she?</i> (is tired)</p>", "vocab": [{"en": "It's freezing, isn't it?", "es": "Hace un frío terrible, ¿verdad?", "v": "f", "img": "u:photo-1768087038176-76d822849575", "au": "y49ace2268a"}, {"en": "You've met Laura, haven't you?", "es": "Ya conoces a Laura, ¿no?", "v": "m", "img": "u:photo-1573497491208-6b1acb260507", "au": "y4e63bde674"}, {"en": "She can't swim, can she?", "es": "Ella no sabe nadar, ¿o sí?", "v": "f", "img": "u:photo-1536331568701-0b15cbb1a918", "au": "y45b48ca97d"}, {"en": "They didn't call back, did they?", "es": "No devolvieron la llamada, ¿cierto?", "v": "m", "img": "u:photo-1625850344758-8c4ff87559ad", "au": "y4d2ccaeaf1"}, {"en": "He'll be late again, won't he?", "es": "Va a llegar tarde otra vez, ¿no?", "v": "f", "img": "u:photo-1659352783247-54f4db3cff87", "au": "y4ff30e43c8"}, {"en": "We should leave now, shouldn't we?", "es": "Deberíamos irnos ya, ¿no?", "v": "m", "img": "u:photo-1631079250215-525a723f6081", "au": "y40a0acb06f"}, {"en": "The game was canceled, wasn't it?", "es": "El partido se canceló, ¿no?", "v": "f", "img": "u:photo-1730812256117-515888760e76", "au": "y4d79e36044"}, {"en": "You don't like broccoli, do you?", "es": "No te gusta el brócoli, ¿verdad?", "v": "m", "img": "u:photo-1653576840776-47a12be506e4", "au": "y467c002d14"}], "sentences": [{"en": "The project is due on Friday, isn't it?", "es": "El proyecto se entrega el viernes, ¿no?", "v": "f", "img": "u:photo-1719159381916-062fa9f435a6", "au": "y44d4fedb36"}, {"en": "You haven't seen my charger, have you?", "es": "No has visto mi cargador, ¿o sí?", "v": "m", "img": "u:photo-1557767382-97b28f5488e7", "au": "y41ab02b1da"}, {"en": "Your cousin lives in Medellín, doesn't she?", "es": "Tu prima vive en Medellín, ¿cierto?", "v": "f", "img": "u:photo-1633627422584-853a4ecfc7ae", "au": "y4146d93639"}, {"en": "We met at summer camp, didn't we?", "es": "Nos conocimos en el campamento de verano, ¿no?", "v": "m", "img": "u:photo-1606092195730-5d7b9af1efc5", "au": "y4dab6c385d"}, {"en": "The test has been moved again, hasn't it?", "es": "Cambiaron el examen de fecha otra vez, ¿no?", "v": "f", "img": "u:photo-1557989048-03456d01a26e", "au": "y46926d9542"}, {"en": "She can speak three languages, can't she?", "es": "Ella habla tres idiomas, ¿no?", "v": "m", "img": "u:photo-1713370638896-a2f113ccbe7d", "au": "y46346e6fb9"}]}, "t8p2": {"tip": "<p>Hay coletillas <b>especiales</b> que no siguen la regla normal:</p>\n<p><b>I am</b> → <b>aren't I?</b> <i>(nunca \"amn't I\")</i>: <i>I'm invited, <b>aren't I</b>?</i><br>\n<b>Let's</b> → <b>shall we?</b>: <i>Let's start, <b>shall we</b>?</i><br>\n<b>Imperativo</b> → <b>will you? / would you? / can you?</b>: <i>Close the door, <b>will you</b>?</i> · <i>Don't tell anyone, <b>will you</b>?</i></p>\n<p>Palabras <b>negativas</b> (<b>never, nobody, nothing, hardly, rarely, no one</b>) hacen la oración negativa → coletilla <b>positiva</b>: <i>You <b>never</b> complain, <b>do</b> you?</i><br>\n<b>nobody / somebody / everyone</b> → <b>they</b>; <b>nothing / everything</b> → <b>it</b>.</p>\n<p><b>Entonación:</b> ↘ <b>descendente</b> = estás seguro y solo buscas que te den la razón. ↗ <b>ascendente</b> = de verdad no sabes y preguntas.</p>", "vocab": [{"en": "I'm right, aren't I?", "es": "Tengo razón, ¿no?", "v": "f", "img": "u:photo-1662850886700-4ec19bd30d11", "au": "y4bd70febac"}, {"en": "Let's grab lunch, shall we?", "es": "Vamos a almorzar, ¿sí?", "v": "m", "img": "u:photo-1556543365-e08680c86612", "au": "y408711dbfd"}, {"en": "Pass me the ball, will you?", "es": "Pásame el balón, ¿sí?", "v": "f", "img": "u:photo-1502086223501-7ea6ecd79368", "au": "y485541fcdb"}, {"en": "Don't be late, will you?", "es": "No llegues tarde, ¿vale?", "v": "m", "img": "u:photo-1550534791-2677533605ab", "au": "y4509aabee3"}, {"en": "Nobody noticed, did they?", "es": "Nadie se dio cuenta, ¿verdad?", "v": "f", "img": "u:photo-1621452773781-0f992fd1f5cb", "au": "y4403a03773"}, {"en": "Nothing happened, did it?", "es": "No pasó nada, ¿cierto?", "v": "m", "img": "u:photo-1608975321345-3e26cbf0f017", "au": "y4cc6b2f6a5"}, {"en": "You've never been to Alaska, have you?", "es": "Nunca has ido a Alaska, ¿o sí?", "v": "f", "img": "u:photo-1628211070630-a8dd88789836", "au": "y4ee8136d6d"}, {"en": "Everyone's here, aren't they?", "es": "Ya están todos, ¿no?", "v": "m", "img": "u:photo-1608790672275-309c02d888ff", "au": "y47fd48fd4b"}], "sentences": [{"en": "I'm invited to the party, aren't I?", "es": "Estoy invitado a la fiesta, ¿no?", "v": "f", "img": "u:photo-1727323853481-a2aebdf3ff6b", "au": "y428c81a0ed"}, {"en": "Let's not argue about it, shall we?", "es": "No discutamos por eso, ¿sí?", "v": "m", "img": "u:photo-1604179129250-20e67a1b6c9d", "au": "y4854ed3a7f"}, {"en": "Close the door on your way out, will you?", "es": "Cierra la puerta al salir, ¿sí?", "v": "f", "img": "u:photo-1614872643157-f745e21753f5", "au": "y435ddf769e"}, {"en": "Nobody has finished the test yet, have they?", "es": "Nadie ha terminado el examen todavía, ¿verdad?", "v": "m", "img": "u:photo-1557989048-03456d01a26e", "au": "y4bb8596266"}, {"en": "Somebody left the lights on, didn't they?", "es": "Alguien dejó las luces encendidas, ¿no?", "v": "f", "img": "u:photo-1473893604213-3df9c15611c0", "au": "y4cfe4af97a"}, {"en": "You hardly ever miss soccer practice, do you?", "es": "Casi nunca faltas al entrenamiento de fútbol, ¿verdad?", "v": "m", "img": "u:photo-1622659097509-4d56de14539e", "au": "y45bf7559f3"}]}, "t9p1": {"tip": "<p>El <b>estilo indirecto</b> (reported speech) sirve para contar lo que otra persona dijo.</p>\n<p><b>Backshift:</b> cuando el verbo que introduce está en pasado (<i>said, told</i>), el tiempo verbal \"retrocede\":<br>\n<b>am/is → was</b> · <b>are → were</b> · <b>do → did</b> · <b>did / have done → had done</b> · <b>will → would</b> · <b>can → could</b> · <b>may → might</b>.<br>\n<i>\"I'm exhausted.\"</i> → <i>She said she <b>was</b> exhausted.</i></p>\n<p><b>say vs tell:</b> <b>say</b> (something) <i>— He said that…</i> · <b>tell</b> + <b>persona</b> <i>— He told <b>me</b> that…</i> (nunca <i>said me</i>).</p>\n<p>Cambian también tiempo y lugar: <b>today → that day</b> · <b>tomorrow → the next day</b> · <b>yesterday → the day before</b> · <b>now → then</b> · <b>here → there</b> · <b>this → that</b>.</p>\n<p>Si lo dicho <b>sigue siendo cierto</b>, el backshift es opcional: <i>She said she <b>lives</b> in Medellín.</i></p>", "vocab": [{"en": "He said (that)…", "es": "Él dijo que…", "v": "f", "img": "u:photo-1778809246888-252fd29491a1", "au": "y480c3d5cbb"}, {"en": "She told me (that)…", "es": "Ella me dijo que…", "v": "m", "img": "u:photo-1621452773781-0f992fd1f5cb", "au": "y4f0d3b1d8a"}, {"en": "backshift", "es": "retroceso del tiempo verbal", "v": "f", "img": "u:photo-1504197832061-98356e3dcdcf", "au": "y472db1e99f"}, {"en": "the day before", "es": "el día anterior", "v": "m", "img": "u:photo-1543168256-4ae2229821f1", "au": "y4907b646b8"}, {"en": "the next day", "es": "al día siguiente", "v": "f", "img": "u:photo-1543613949-95cd1b38a10e", "au": "y443b6384e0"}, {"en": "that night", "es": "esa noche", "v": "m", "img": "u:photo-1628498188904-036f5e25e93e", "au": "y4e240f5af9"}, {"en": "then", "es": "en ese momento / entonces", "v": "f", "img": "u:photo-1527490087278-9c75be0b8052", "au": "y495c04f395"}, {"en": "to pass on a message", "es": "transmitir un mensaje", "v": "m", "img": "u:photo-1781116926975-dfb4cfbcb6e5", "au": "y4c66a0f1b1"}], "sentences": [{"en": "She said she was studying at her friend's house.", "es": "Ella dijo que estaba estudiando en casa de su amiga.", "v": "f", "img": "u:photo-1460518451285-97b6aa326961", "au": "y48475ed617"}, {"en": "He told me he had lost his keys.", "es": "Él me dijo que había perdido sus llaves.", "v": "m", "img": "u:photo-1755634380267-08c6f2a6d428", "au": "y44e404d5cc"}, {"en": "They said they would call the next day.", "es": "Dijeron que llamarían al día siguiente.", "v": "f", "img": "u:photo-1485712207830-8a665e701494", "au": "y4719346052"}, {"en": "Our teacher told us the test had changed.", "es": "Nuestra profesora nos dijo que el examen había cambiado.", "v": "m", "img": "u:photo-1509062522246-3755977927d7", "au": "y430fbd6fd8"}, {"en": "You said you could fix it!", "es": "¡Dijiste que podías arreglarlo!", "v": "f", "img": "u:photo-1473662711507-13345f9d447c", "au": "y4d4089075f"}, {"en": "She said she'd been to Cartagena the week before.", "es": "Dijo que había estado en Cartagena la semana anterior.", "v": "m", "img": "u:photo-1690571100303-cb86f92b9b01", "au": "y4289fb591e"}]}, "t9p2": {"tip": "<p>En vez de repetir siempre <i>said</i>, el inglés avanzado usa <b>verbos que resumen la intención</b>. Cada uno tiene su <b>patrón</b>:</p>\n<p><b>verbo + -ing:</b> <b>suggest, admit, deny</b> — <i>He <b>denied eating</b> the cookies.</i><br>\n<b>verbo + to + verbo:</b> <b>promise, refuse, offer, agree</b> — <i>She <b>offered to help</b> me.</i><br>\n<b>verbo + persona + to:</b> <b>advise, warn, remind, ask, tell</b> — <i>They <b>warned us not to</b> go.</i><br>\n<b>verbo + preposición + -ing:</b> <b>apologize for, insist on, accuse someone of</b> — <i>He <b>apologized for being</b> late.</i></p>\n<p><b>suggest</b> nunca lleva <i>to</i>: Mal: <i>suggested to go</i> Bien: <i>suggested going</i> / <i>suggested (that) we go</i>.</p>", "vocab": [{"en": "suggest doing", "es": "sugerir hacer", "v": "f", "img": "u:photo-1469406396016-013bfae5d83e", "au": "y4a00d63918"}, {"en": "admit doing", "es": "admitir haber hecho", "v": "m", "img": "u:photo-1548889905-5d52d3f49dfe", "au": "y42d78bb3b8"}, {"en": "deny doing", "es": "negar haber hecho", "v": "f", "img": "u:photo-1725265997424-5eacf64af9ba", "au": "y431b616c52"}, {"en": "promise to do", "es": "prometer hacer", "v": "m", "img": "u:photo-1593526613712-7b4b9a707330", "au": "y4213b01466"}, {"en": "warn someone not to", "es": "advertir a alguien que no", "v": "f", "img": "u:photo-1519971585408-420d17643586", "au": "y4e962e0a67"}, {"en": "advise someone to", "es": "aconsejar a alguien que", "v": "m", "img": "u:photo-1632053002928-1919605ee6f7", "au": "y4098f54a40"}, {"en": "refuse to do", "es": "negarse a hacer", "v": "f", "img": "u:photo-1760267982929-b038bf9b82e0", "au": "y41a95253c8"}, {"en": "offer to do", "es": "ofrecerse a hacer", "v": "m", "img": "u:photo-1489942986787-cded4ecf962e", "au": "y4d1c304e0c"}], "sentences": [{"en": "She suggested taking the earlier bus.", "es": "Sugirió tomar el bus más temprano.", "v": "f", "img": "u:photo-1573086490982-98a5ce8fa45d", "au": "y4e964a2f9f"}, {"en": "He admitted making a mistake.", "es": "Admitió haber cometido un error.", "v": "m", "img": "u:photo-1718754323904-6866d4e9b5d1", "au": "y42a61eaa8d"}, {"en": "My brother denied eating the last cookie.", "es": "Mi hermano negó haberse comido la última galleta.", "v": "f", "img": "u:photo-1713942589752-6c6bb58ca8b6", "au": "y4ea12a07d9"}, {"en": "My doctor advised me to cut down on sugar.", "es": "Mi médico me aconsejó reducir el azúcar.", "v": "m", "img": "u:photo-1632053002928-1919605ee6f7", "au": "y447b94cc9d"}, {"en": "The coach warned us not to skip warm-ups.", "es": "El entrenador nos advirtió que no nos saltáramos el calentamiento.", "v": "f", "img": "u:photo-1502086223501-7ea6ecd79368", "au": "y4f4523d14c"}, {"en": "She promised to send me the notes today.", "es": "Prometió enviarme los apuntes hoy.", "v": "m", "img": "u:photo-1689799514696-b16af9b53753", "au": "y443c4cd951"}]}, "t10p1": {"tip": "<p>Las <b>preguntas indirectas</b> suenan más <b>educadas y amables</b>. Empiezan con una frase introductoria: <b>Could you tell me…? · Do you know…? · I was wondering…</b></p>\n<p><b>Lo más importante:</b> después de la introducción, el orden es de <b>afirmación</b> (sujeto + verbo), <b>sin do/does/did</b>:<br>\n<i>Where <b>is</b> the library?</i> → Bien: <i>Could you tell me where <b>the library is</b>?</i><br>\n<i>What time <b>does</b> it open?</i> → Bien: <i>Do you know what time <b>it opens</b>?</i></p>\n<p>Si la pregunta es de <b>sí/no</b>, usa <b>if</b> o <b>whether</b>: <i>Is the pool open?</i> → <i>Do you know <b>if</b> the pool is open?</i></p>\n<p>El signo de interrogación depende de la frase inicial: <i>Do you know…<b>?</b></i> pero <i>I was wondering if you could help me<b>.</b></i></p>", "vocab": [{"en": "Could you tell me…?", "es": "¿Podría decirme…?", "v": "f", "img": "u:photo-1492627223639-6e980361988c", "au": "y4ee67c7a6c"}, {"en": "Do you know…?", "es": "¿Sabe usted…?", "v": "m", "img": "u:photo-1583468982228-19f19164aee2", "au": "y4a3e2e3059"}, {"en": "I was wondering if…", "es": "Me preguntaba si…", "v": "f", "img": "u:photo-1758876022649-ab858801c6dc", "au": "y451be463a1"}, {"en": "Would you mind telling me…?", "es": "¿Le importaría decirme…?", "v": "m", "img": "u:photo-1636202339022-7d67f7447e3a", "au": "y42541a27c2"}, {"en": "Do you happen to know…?", "es": "¿Por casualidad sabe…?", "v": "f", "img": "u:photo-1527490272553-ba05e1f11ee9", "au": "y4863a84f17"}, {"en": "Can you remind me…?", "es": "¿Me puedes recordar…?", "v": "m", "img": "u:photo-1485546246426-74dc88dec4d9", "au": "y46628cacbc"}, {"en": "Any idea…?", "es": "¿Tienes idea de…? (informal)", "v": "f", "img": "u:photo-1543269865-cbf427effbad", "au": "y4de9675b27"}, {"en": "word order", "es": "orden de las palabras", "v": "m", "img": "u:photo-1785780224428-7b690d3d58bd", "au": "y4ba888b5b1"}], "sentences": [{"en": "Could you tell me where the restroom is?", "es": "¿Podría decirme dónde está el baño?", "v": "f", "img": "u:photo-1780253460360-d85b2db8c078", "au": "y41589d90d0"}, {"en": "Do you know what time the museum opens?", "es": "¿Sabe a qué hora abre el museo?", "v": "m", "img": "u:photo-1608453828734-40f2e78f0d9a", "au": "y418396f824"}, {"en": "I was wondering if you could help me.", "es": "Me preguntaba si podría ayudarme.", "v": "f", "img": "u:photo-1551847677-dc82d764e1eb", "au": "y4982a80376"}, {"en": "Can you tell me how much this ice cream costs?", "es": "¿Me puede decir cuánto cuesta este helado?", "v": "m", "img": "u:photo-1567206563064-6f60f40a2b57", "au": "y48230faca9"}, {"en": "Do you happen to know where the library is?", "es": "¿Por casualidad sabe dónde queda la biblioteca?", "v": "f", "img": "u:photo-1758885698366-47d44c6ec6ba", "au": "y42ed9c1031"}, {"en": "Would you mind telling me your name again?", "es": "¿Le importaría decirme su nombre otra vez?", "v": "m", "img": "u:photo-1607453998774-d533f65dac99", "au": "y48275cda1f"}]}, "t10p2": {"tip": "<p>Para <b>reportar una pregunta</b> usa <b>asked / wanted to know / wondered</b> + orden de <b>afirmación</b> + <b>backshift</b>:</p>\n<p><i>\"Where <b>do you live</b>?\"</i> → <i>She asked me where <b>I lived</b>.</i><br>\n<i>\"<b>Can you</b> come on Saturday?\"</i> → <i>He asked <b>if/whether I could</b> come on Saturday.</i></p>\n<p><b>if</b> y <b>whether</b> significan <i>si</i> (condicional de duda). Pero solo <b>whether</b> se usa:<br>\n• antes de <b>to + verbo</b>: <i>I don't know <b>whether to</b> join the club.</i><br>\n• después de <b>preposición</b>: <i>It depends <b>on whether</b> it rains.</i><br>\n• con <b>or not</b> justo después: <i><b>whether or not</b> you agree</i>.</p>\n<p>Las preguntas reportadas <b>no llevan signo de interrogación</b> ni <i>do/does/did</i>.</p>", "vocab": [{"en": "She asked me if…", "es": "Me preguntó si…", "v": "f", "img": "u:photo-1626387753307-5a329fa44578", "au": "y4e0e2b7f10"}, {"en": "He wanted to know…", "es": "Quería saber…", "v": "m", "img": "u:photo-1789472785955-2d5d820fc4ac", "au": "y404bf02479"}, {"en": "whether or not", "es": "si… o no", "v": "f", "img": "u:photo-1529218164294-0d21b06ea831", "au": "y4627f98ec1"}, {"en": "whether to join", "es": "si unirse o no", "v": "m", "img": "u:photo-1644568500511-f8e1e1ff74f9", "au": "y4f9b8cb99b"}, {"en": "a tryout", "es": "una prueba (para un equipo)", "v": "f", "img": "u:photo-1748111405983-d1b10316eb83", "au": "y4a6aa22f2a"}, {"en": "a survey", "es": "una encuesta", "v": "m", "img": "u:photo-1665979738279-bd2441290e02", "au": "y442cba2b01"}, {"en": "to inquire about", "es": "informarse sobre", "v": "f", "img": "u:photo-1685541088069-66baf0b2d753", "au": "y482663430c"}, {"en": "a follow-up message", "es": "un mensaje de seguimiento", "v": "m", "img": "u:photo-1758611973525-b5a86f468b5e", "au": "y4e82e7717c"}], "sentences": [{"en": "She asked me if I could come on Saturday.", "es": "Me preguntó si podía venir el sábado.", "v": "f", "img": "u:photo-1781938891114-a4782a49d988", "au": "y4e249fea6e"}, {"en": "They wanted to know why I had left early.", "es": "Querían saber por qué me había ido temprano.", "v": "m", "img": "u:photo-1764380748978-c7330ec6cd69", "au": "y4f0bb0415d"}, {"en": "He asked whether I was ready for the tryout.", "es": "Preguntó si estaba listo para la prueba.", "v": "f", "img": "u:photo-1622659097509-4d56de14539e", "au": "y46fde0da9b"}, {"en": "I'm not sure whether to join the chess club.", "es": "No estoy seguro de si unirme al club de ajedrez.", "v": "m", "img": "u:photo-1725818660598-43b9012a8168", "au": "y4b549cb047"}, {"en": "The coach asked what position I played.", "es": "El entrenador preguntó en qué posición jugaba.", "v": "f", "img": "u:photo-1526232761682-d26e03ac148e", "au": "y4b72d68b65"}, {"en": "It depends on whether it rains tomorrow.", "es": "Depende de si llueve mañana.", "v": "m", "img": "u:photo-1509635022432-0220ac12960b", "au": "y4a2bbaa63e"}]}, "t11p1": {"tip": "<p>La <b>voz pasiva</b> pone el foco en la <b>acción o el resultado</b>, no en quién la hace. Fórmula: <b>be</b> (en el tiempo que necesites) + <b>participio pasado</b>.</p>\n<p><b>Presente:</b> is/are <b>made</b> · <b>Pres. continuo:</b> is/are <b>being</b> made · <b>Pasado:</b> was/were made · <b>Pas. continuo:</b> was/were being made<br>\n<b>Present perfect:</b> has/have <b>been</b> made · <b>Past perfect:</b> had been made · <b>Futuro:</b> will <b>be</b> made · <b>Modales:</b> can/must/should <b>be</b> made</p>\n<p>Usa <b>by + agente</b> solo si es <b>importante o nuevo</b>: <i>This poster was designed <b>by my little sister</b>.</i> Omite el agente si es obvio o desconocido: <i>The school was painted last summer</i> (<i>by some people</i>).</p>\n<p>En español a menudo usamos <b>\"se\"</b>: <i>Se habla inglés</i> → <i>English <b>is spoken</b></i>.</p>", "vocab": [{"en": "is made", "es": "es fabricado / se fabrica", "v": "f", "img": "u:photo-1783650604373-54d22a7f3c5e", "au": "y460c1607b0"}, {"en": "was built", "es": "fue construido", "v": "m", "img": "u:photo-1776004480790-72f731bc9435", "au": "y4de316048e"}, {"en": "is being repaired", "es": "está siendo reparado", "v": "f", "img": "u:photo-1675798227643-da319f8ee8f7", "au": "y490da3c768"}, {"en": "has been canceled", "es": "ha sido cancelado", "v": "m", "img": "u:photo-1701277050203-eabfa03e64eb", "au": "y43b4c9d061"}, {"en": "had been eaten", "es": "había sido comido", "v": "f", "img": "u:photo-1630466913899-31fb06c6110e", "au": "y44bf552f6c"}, {"en": "will be announced", "es": "será anunciado", "v": "m", "img": "u:photo-1786455285226-4d7a3054976d", "au": "y42adea6041"}, {"en": "can be downloaded", "es": "se puede descargar", "v": "f", "img": "u:photo-1656275544060-1c0515d192b6", "au": "y4b334ba643"}, {"en": "must be turned in", "es": "debe ser entregado", "v": "m", "img": "u:photo-1601397922721-4326ae07bbc5", "au": "y4374c133e6"}], "sentences": [{"en": "The school library was built in 1990.", "es": "La biblioteca del colegio fue construida en 1990.", "v": "f", "img": "u:photo-1790918332339-378136269513", "au": "y469ff1c10f"}, {"en": "The soccer field is being repaired this week.", "es": "La cancha de fútbol está siendo reparada esta semana.", "v": "m", "img": "u:photo-1704633785114-52104ce3d626", "au": "y41d8253599"}, {"en": "The field trip has been canceled because of the rain.", "es": "La salida pedagógica ha sido cancelada por la lluvia.", "v": "f", "img": "u:photo-1726242839974-36cee4ad0a7e", "au": "y43981ecee5"}, {"en": "The winners will be announced tomorrow.", "es": "Los ganadores serán anunciados mañana.", "v": "m", "img": "u:photo-1540688030071-628c72ab0b08", "au": "y41d5ea6944"}, {"en": "This permission slip must be signed by a parent.", "es": "Este permiso debe ser firmado por uno de tus padres.", "v": "f", "img": "u:photo-1562564055-71e051d33c19", "au": "y4b1ce0c482"}, {"en": "All the pizza had been eaten before we arrived.", "es": "Ya se habían comido toda la pizza cuando llegamos.", "v": "m", "img": "u:photo-1687068368211-227d76adf27d", "au": "y459c9d11f1"}]}, "t11p2": {"tip": "<p>La <b>pasiva impersonal</b> es típica de noticias y textos formales. Hay dos estructuras:</p>\n<p>1. <b>It + is said / believed / thought / reported / expected + that…</b><br>\n<i><b>It is believed that</b> the old house is haunted.</i></p>\n<p>2. <b>Sujeto + is said / believed… + to + infinitivo</b><br>\n• Presente: <i>The old house <b>is believed to be</b> haunted.</i><br>\n• En progreso: <i>The lost cat <b>is thought to be hiding</b> in the garden.</i><br>\n• Pasado: <i>The cat <b>is said to have escaped</b> through the window.</i> (<b>to have + participio</b>)</p>\n<p>Para <b>describir procesos</b> se usa el presente pasivo con conectores: <b>First, … Then, … After that, … Finally, …</b> — <i>First, the cocoa beans <b>are roasted</b>.</i></p>\n<p>Los <b>titulares</b> omiten el verbo <i>be</i>: <i>\"School <b>Closed</b> by Snow\"</i> = <i>The school was closed by snow.</i></p>", "vocab": [{"en": "It is said that…", "es": "Se dice que…", "v": "f", "img": "u:photo-1674420888913-b18896123aae", "au": "y4c356790b9"}, {"en": "The cat is believed to be…", "es": "Se cree que el gato está…", "v": "m", "img": "u:photo-1789826605860-6e04fa958a05", "au": "y4f58cceb49"}, {"en": "She is thought to have…", "es": "Se piensa que ella ha…", "v": "f", "img": "u:photo-1582079768266-e65af1ad8d3a", "au": "y4273c4c644"}, {"en": "It is reported that…", "es": "Se informa que…", "v": "m", "img": "u:photo-1485699759268-2b1bea261b3e", "au": "y46ecae4398"}, {"en": "is expected to", "es": "se espera que", "v": "f", "img": "u:photo-1577335029365-35029f68d093", "au": "y45719b6dff"}, {"en": "a headline", "es": "un titular", "v": "m", "img": "u:photo-1777988864563-42ce7fd253e5", "au": "y409950ae3b"}, {"en": "the cocoa beans are roasted", "es": "los granos de cacao se tuestan", "v": "f", "img": "u:photo-1493925410384-84f842e616fb", "au": "y4469aa1121"}, {"en": "the apples are picked", "es": "las manzanas se recogen", "v": "m", "img": "u:photo-1722441297028-1144bcdc231c", "au": "y4cb8b28e1f"}], "sentences": [{"en": "It is said that the old house is haunted.", "es": "Se dice que la casa vieja está embrujada.", "v": "f", "img": "u:photo-1583437624797-0e3348843acd", "au": "y46fcaf7108"}, {"en": "The missing dog is believed to be hiding in the park.", "es": "Se cree que el perro perdido está escondido en el parque.", "v": "m", "img": "u:photo-1763581804396-d227cb985ec2", "au": "y493c63506e"}, {"en": "The singer is said to have written the song in one night.", "es": "Se dice que el cantante escribió la canción en una noche.", "v": "f", "img": "u:photo-1510915361894-db8b60106cb1", "au": "y4a551183b2"}, {"en": "The cocoa beans are roasted at high temperatures.", "es": "Los granos de cacao se tuestan a altas temperaturas.", "v": "m", "img": "u:photo-1607681034540-2c46cc71896d", "au": "y4dcc21fa5d"}, {"en": "Thousands of toys are produced here every day.", "es": "Aquí se producen miles de juguetes cada día.", "v": "f", "img": "u:photo-1777464375799-768774f30542", "au": "y4f71c8da9a"}, {"en": "The new stadium is expected to open in May.", "es": "Se espera que el nuevo estadio abra en mayo.", "v": "m", "img": "u:photo-1679391029864-d46f366a456b", "au": "y435762354a"}]}, "t12p1": {"tip": "<p>Usamos <b>have + objeto + participio</b> cuando <b>otra persona</b> (un profesional) hace algo <b>por nosotros</b>, normalmente porque le pagamos.</p>\n<p><i>I cut my hair.</i> = me lo corté yo mismo <br>\n<i>I <b>had my hair cut</b>.</i> = fui a la peluquería y me lo cortaron.</p>\n<p>⏰ El verbo <b>have</b> cambia de tiempo; el participio no cambia:<br>\n<i>I'm <b>having</b> my bike repaired.</i> · <i>She <b>had</b> her nails painted.</i> · <i>We've <b>had</b> the house painted.</i> · <i>I'll <b>have</b> it fixed.</i> · <i>You should <b>have</b> your eyes tested.</i></p>\n<p>En preguntas y negativas usa <b>do/does/did</b>: <i>Where <b>do</b> you <b>have</b> your hair cut?</i> · <i>I <b>didn't have</b> it repaired.</i></p>\n<p>En español decimos <i>\"me corté el pelo\"</i> aunque lo haya hecho otra persona. ¡En inglés hay que decir <b>had</b>!</p>", "vocab": [{"en": "have my hair cut", "es": "cortarme el pelo (en la peluquería)", "v": "f", "img": "u:photo-1704072650662-76df3af134a7", "au": "y4f35d5bb4a"}, {"en": "have my bike repaired", "es": "mandar a arreglar mi bicicleta", "v": "m", "img": "u:photo-1607109181641-74f8e7f4eb11", "au": "y4b1a3d999f"}, {"en": "have my eyes tested", "es": "hacerme examinar la vista", "v": "f", "img": "u:photo-1542647879-d84f68115c67", "au": "y43d658d085"}, {"en": "have my nails painted", "es": "hacerme pintar las uñas", "v": "m", "img": "u:photo-1522337660859-02fbefca4702", "au": "y4620865043"}, {"en": "have my teeth checked", "es": "hacerme revisar los dientes", "v": "f", "img": "u:photo-1631051103633-24959376b92d", "au": "y43bf2caacc"}, {"en": "have my photo taken", "es": "que me tomen una foto", "v": "m", "img": "u:photo-1726303828014-e515d5a737fb", "au": "y49743d123f"}, {"en": "have pizza delivered", "es": "pedir pizza a domicilio", "v": "f", "img": "u:photo-1642744412525-3e036566d416", "au": "y47edf932da"}, {"en": "have my room painted", "es": "mandar a pintar mi cuarto", "v": "m", "img": "u:photo-1618221118493-9cfa1a1c00da", "au": "y46997a9a4d"}], "sentences": [{"en": "I'm having my hair cut on Saturday.", "es": "Me voy a cortar el pelo el sábado.", "v": "f", "img": "u:photo-1759408174071-f2971472dc73", "au": "y468f8e8a75"}, {"en": "She had her bike repaired last week.", "es": "Mandó a arreglar su bicicleta la semana pasada.", "v": "m", "img": "u:photo-1676531443468-0e2b5a57e48f", "au": "y4b1969c16b"}, {"en": "We need to have the roof repaired.", "es": "Necesitamos mandar a arreglar el techo.", "v": "f", "img": "u:photo-1726589004565-bedfba94d3a2", "au": "y497b6fdd08"}, {"en": "Did you have your teeth checked this year?", "es": "¿Fuiste a que te revisaran los dientes este año?", "v": "m", "img": "u:photo-1606811971618-4486d14f3f99", "au": "y4e66fe04d9"}, {"en": "We've just had our living room painted.", "es": "Acabamos de mandar a pintar la sala.", "v": "f", "img": "u:photo-1656122381069-9ec666d95cf1", "au": "y4735a09650"}, {"en": "You should have your eyes tested.", "es": "Deberías hacerte examinar la vista.", "v": "m", "img": "u:photo-1705357311681-17449eb278d1", "au": "y4de39f915a"}]}, "t12p2": {"tip": "<p><b>get + objeto + participio</b> = igual que <i>have something done</i>, pero más <b>informal</b> y común al hablar: <i>I need to <b>get my phone fixed</b>.</i></p>\n<p>La misma estructura sirve para <b>malas experiencias</b> que <b>nos pasaron</b> (nadie lo pidió): <i>I <b>had my phone taken away</b>.</i> = me quitaron el teléfono. · <i>She <b>got her account hacked</b>.</i> = le hackearon la cuenta.</p>\n<p>Para decir <b>quién</b> lo hace:<br>\n• <b>have + persona + verbo base</b>: <i>I <b>had the technician check</b> my laptop.</i><br>\n• <b>get + persona + to + verbo</b>: <i>I <b>got my brother to help</b> me.</i> (lo convencí)</p>\n<p>No confundas: <i>I had cut</i> (yo había cortado ) ≠ <i>I <b>had my hair cut</b></i> (me cortaron el pelo).</p>", "vocab": [{"en": "get my phone fixed", "es": "mandar a arreglar mi teléfono", "v": "f", "img": "u:photo-1746006084492-24a8fd02710a", "au": "y4c1ee5982f"}, {"en": "get my passport renewed", "es": "renovar mi pasaporte (trámite)", "v": "m", "img": "u:photo-1454496406107-dc34337da8d6", "au": "y4da77df379"}, {"en": "have my phone taken away", "es": "que me quiten el teléfono", "v": "f", "img": "u:photo-1685186113811-a641a6505f16", "au": "y4fb926bde1"}, {"en": "have my flight canceled", "es": "que me cancelen el vuelo", "v": "m", "img": "u:photo-1549897411-b06572cdf806", "au": "y49d6a5037e"}, {"en": "get my account hacked", "es": "que me hackeen la cuenta", "v": "f", "img": "u:photo-1762340275855-ae8f4c2c144e", "au": "y4e9eb2bfe3"}, {"en": "have my bag searched", "es": "que me revisen el bolso", "v": "m", "img": "u:photo-1545595271-908483fa6e50", "au": "y4cf64c5258"}, {"en": "have the technician check it", "es": "hacer que el técnico lo revise", "v": "f", "img": "u:photo-1676636810289-2ac22579d988", "au": "y44f117154a"}, {"en": "get someone to help", "es": "conseguir que alguien ayude", "v": "m", "img": "u:photo-1559225306-3f60aa7b39a3", "au": "y42cd71687d"}], "sentences": [{"en": "I had my phone taken away in class.", "es": "Me quitaron el teléfono en clase.", "v": "f", "img": "u:photo-1758685848142-06e158cf64bc", "au": "y4a0090ab5e"}, {"en": "She got her game account hacked last month.", "es": "Le hackearon la cuenta del juego el mes pasado.", "v": "m", "img": "u:photo-1623076189461-f7706b741c04", "au": "y4e41cef4df"}, {"en": "We had our flight canceled twice.", "es": "Nos cancelaron el vuelo dos veces.", "v": "f", "img": "u:photo-1763618769707-3e318c25325f", "au": "y4d5eba5f32"}, {"en": "I'll get my phone fixed tomorrow.", "es": "Mañana mando a arreglar mi teléfono.", "v": "m", "img": "u:photo-1761207850745-d41a776ef897", "au": "y4dee62ee23"}, {"en": "I had my dad check my bike brakes.", "es": "Hice que mi papá revisara los frenos de mi bicicleta.", "v": "f", "img": "u:photo-1602271134461-236678358fd1", "au": "y4812c194b6"}, {"en": "I got my sister to help me with my project.", "es": "Conseguí que mi hermana me ayudara con mi proyecto.", "v": "m", "img": "u:photo-1692269725911-87697c558be1", "au": "y4c9b5d6adb"}]}, "t13p1": {"tip": "<p>El <b>futuro continuo</b> describe una acción que estará <b>en progreso</b> en un momento concreto del futuro. Fórmula: <b>will be + verbo-ing</b>.</p>\n<p><i><b>This time tomorrow</b>, I'<b>ll be flying</b> to Orlando.</i> (en ese momento estaré en pleno vuelo )<br>\n<i>Don't call at 9. I'<b>ll be sleeping</b>.</i></p>\n<p>También se usa para planes que ocurrirán <b>como parte de la rutina</b>: <i>I'll be seeing Ana at school anyway.</i></p>\n<p><b>Will you be + -ing…?</b> es una forma <b>muy cortés</b> de preguntar por los planes de alguien sin presionar: <i><b>Will you be using</b> the laptop tonight?</i> (suena más amable que <i>Will you use…?</i>)</p>\n<p>Negativo: <i>I <b>won't be studying</b> on Friday.</i></p>", "vocab": [{"en": "will be flying", "es": "estaré volando", "v": "f", "img": "u:photo-1569629743817-70d8db6c323b", "au": "y4cb843b0c0"}, {"en": "will be studying", "es": "estaré estudiando", "v": "m", "img": "u:photo-1758525861793-f278aacf6bb5", "au": "y41f6da6925"}, {"en": "will be lying on a beach", "es": "estaré tumbado en una playa", "v": "f", "img": "u:photo-1588575716903-d85c71322e9b", "au": "y4084cae32b"}, {"en": "this time tomorrow", "es": "mañana a esta hora", "v": "m", "img": "u:photo-1541480601022-2308c0f02487", "au": "y45e22a24a5"}, {"en": "at 8 p.m. tonight", "es": "a las 8 p.m. esta noche", "v": "f", "img": "u:photo-1513061379709-ef0cd1695189", "au": "y4b26b3759a"}, {"en": "in a few hours", "es": "en unas horas", "v": "m", "img": "u:photo-1518281361980-b26bfd556770", "au": "y497e6ca970"}, {"en": "Will you be using…?", "es": "¿Vas a usar…? (pregunta cortés)", "v": "f", "img": "u:photo-1541807084-5c52b6b3adef", "au": "y4109e332b2"}, {"en": "to be on the road", "es": "estar en la carretera", "v": "m", "img": "u:photo-1772466669620-310c35f9deb2", "au": "y436d7f8c5e"}], "sentences": [{"en": "This time tomorrow, I'll be flying to Orlando.", "es": "Mañana a esta hora estaré volando a Orlando.", "v": "f", "img": "u:photo-1579017976122-1109f15cf276", "au": "y44d8e89a85"}, {"en": "Don't call at nine; I'll be sleeping.", "es": "No llames a las nueve; estaré durmiendo.", "v": "m", "img": "u:photo-1672928499632-1d040212e3f4", "au": "y44b3873a5e"}, {"en": "Will you be using the laptop tonight?", "es": "¿Vas a usar el portátil esta noche?", "v": "f", "img": "u:photo-1678436749318-8f698f54e865", "au": "y4860eea466"}, {"en": "She'll be playing in the tournament all morning.", "es": "Estará jugando en el torneo toda la mañana.", "v": "m", "img": "u:photo-1547347298-4074fc3086f0", "au": "y48f155b3e5"}, {"en": "In ten years, we'll be living abroad.", "es": "En diez años estaremos viviendo en el exterior.", "v": "f", "img": "u:photo-1524661135-423995f22d0b", "au": "y4904c15d14"}, {"en": "At 8 p.m. tonight, we'll be watching the game.", "es": "A las 8 p.m. esta noche estaremos viendo el partido.", "v": "m", "img": "u:photo-1758612897496-e4db98c26ad3", "au": "y46202fd69e"}]}, "t13p2": {"tip": "<p>El <b>futuro perfecto</b> describe una acción que estará <b>terminada antes de</b> un momento del futuro. Fórmula: <b>will have + participio</b>.</p>\n<p>Casi siempre va con <b>by</b> (<i>a más tardar / para</i>): <b>by Friday, by 2030, by then, by the time you arrive</b>.<br>\n<i><b>By Friday</b>, we'<b>ll have finished</b> the project.</i></p>\n<p>Es perfecto para <b>fechas de entrega</b> y <b>predicciones sobre tu futuro</b>: <i>By 2035, she'<b>ll have finished</b> university.</i></p>\n<p><b>Comparación:</b><br>\n• <b>will be doing</b> → en progreso en ese momento: <i>At 3 p.m. I'll be writing the essay.</i> <br>\n• <b>will have done</b> → ya terminado antes: <i>By 3 p.m. I'll have written the essay.</i> </p>\n<p>Después de <b>by the time / when</b> usa <b>presente</b>: <i>By the time you <b>arrive</b> (will arrive)…</i></p>", "vocab": [{"en": "will have finished", "es": "habrá terminado", "v": "f", "img": "u:photo-1633828763399-e29f1cd3f4c1", "au": "y4b73739f6e"}, {"en": "by Friday", "es": "para el viernes (a más tardar)", "v": "m", "img": "u:photo-1642943392730-ae57c9b77522", "au": "y4e1c25704a"}, {"en": "by the end of the year", "es": "para fin de año", "v": "f", "img": "u:photo-1762901989329-1e7d0d811dc7", "au": "y4a76a9c81b"}, {"en": "by then", "es": "para entonces", "v": "m", "img": "u:photo-1624969862293-b749659ccc4e", "au": "y43d88ffaf0"}, {"en": "a due date", "es": "una fecha de entrega", "v": "f", "img": "u:photo-1435527173128-983b87201f4d", "au": "y457a4308ac"}, {"en": "to hand in on time", "es": "entregar a tiempo", "v": "m", "img": "u:photo-1601397922721-4326ae07bbc5", "au": "y45f53f3645"}, {"en": "to hand in late", "es": "entregar tarde", "v": "f", "img": "u:photo-1616198814651-e71f960c3180", "au": "y449adb4568"}, {"en": "will have been chosen", "es": "habrá sido elegido", "v": "m", "img": "u:photo-1787027270029-db358ff63157", "au": "y407a463b07"}], "sentences": [{"en": "By Friday, we'll have finished the science project.", "es": "Para el viernes habremos terminado el proyecto de ciencias.", "v": "f", "img": "u:photo-1633828763399-e29f1cd3f4c1", "au": "y41e4746129"}, {"en": "By 2030, she'll have graduated from high school.", "es": "Para 2030 se habrá graduado del colegio.", "v": "m", "img": "u:photo-1639765766830-d829d2fe4219", "au": "y4dd08f8ef3"}, {"en": "Will you have read the book by tomorrow?", "es": "¿Habrás leído el libro para mañana?", "v": "f", "img": "u:photo-1553729784-e91953dec042", "au": "y46d6cae8ba"}, {"en": "He won't have arrived by then.", "es": "No habrá llegado para entonces.", "v": "m", "img": "u:photo-1583028828338-309b4b600d60", "au": "y48e59f487d"}, {"en": "By eighteen, I'll have learned three languages.", "es": "A los dieciocho habré aprendido tres idiomas.", "v": "f", "img": "u:photo-1673515334717-da4d85aaf38b", "au": "y4cb85cca57"}, {"en": "By the end of the year, she'll have been chosen for the team.", "es": "Para fin de año habrá sido elegida para el equipo.", "v": "m", "img": "u:photo-1629977007371-0ba395424741", "au": "y495c315a7e"}]}, "t14p1": {"tip": "<p>⏳ El <b>futuro perfecto continuo</b> mide <b>cuánto tiempo</b> habrá durado una actividad cuando llegue un momento futuro. Fórmula: <b>will have been + verbo-ing</b> + <b>for</b> (duración).</p>\n<p><i><b>By June</b>, I'<b>ll have been studying</b> here <b>for three years</b>.</i> (empecé en el pasado, sigo, y en junio cumpliré 3 años)</p>\n<p>También explica <b>causas</b> de un estado futuro: <i>She'll be exhausted — she'<b>ll have been playing</b> soccer all day.</i></p>\n<p>Pregunta: <i><b>How long will</b> you <b>have been</b> living here <b>by</b> December?</i></p>\n<p>En español solemos decir <b>\"llevaré…\"</b>: <i>En junio <b>llevaré</b> tres años estudiando aquí.</i> ¡Esa es la pista para usar este tiempo!</p>", "vocab": [{"en": "will have been playing", "es": "habrá estado jugando", "v": "f", "img": "u:photo-1777489689168-497290f235d5", "au": "y494fe81a36"}, {"en": "for ten years", "es": "durante diez años", "v": "m", "img": "u:photo-1610670444950-0b29430891b4", "au": "y4589b2d7e2"}, {"en": "by next June", "es": "para junio del próximo año", "v": "f", "img": "u:photo-1560420025-9453f02b4751", "au": "y489cbe5a7c"}, {"en": "will have been living", "es": "habrá estado viviendo", "v": "m", "img": "u:photo-1709386263925-a4c7c8dc6f52", "au": "y40abaea9dc"}, {"en": "will have been studying", "es": "habrá estado estudiando", "v": "f", "img": "u:photo-1513475382585-d06e58bcb0e0", "au": "y4b55a35835"}, {"en": "will have been waiting", "es": "habrá estado esperando", "v": "m", "img": "u:photo-1644952176515-35f100da4fe3", "au": "y42eb8d7a10"}, {"en": "will have been running", "es": "habrá estado corriendo", "v": "f", "img": "u:photo-1451481454041-104482d8e284", "au": "y4d44590133"}, {"en": "an anniversary", "es": "un aniversario", "v": "m", "img": "u:photo-1530103862676-de8c9debad1d", "au": "y4e805ae648"}], "sentences": [{"en": "By June, I'll have been studying here for three years.", "es": "En junio llevaré tres años estudiando aquí.", "v": "f", "img": "u:photo-1791477515808-20301fe8e7dc", "au": "y412541bf87"}, {"en": "She'll have been practicing piano for two hours by dinner.", "es": "Para la cena llevará dos horas practicando piano.", "v": "m", "img": "u:photo-1552422530-9b41dc72286b", "au": "y489e2823d1"}, {"en": "We'll have been living in Austin for a year.", "es": "Llevaremos un año viviendo en Austin.", "v": "f", "img": "u:photo-1709787627975-9cb37bbeca60", "au": "y493b2315a6"}, {"en": "They'll have been running for three hours.", "es": "Llevarán tres horas corriendo.", "v": "m", "img": "u:photo-1762169786069-be5b81cd42b9", "au": "y422607410a"}, {"en": "How long will you have been waiting?", "es": "¿Cuánto tiempo llevarás esperando?", "v": "f", "img": "u:photo-1554378739-200b04da4e8b", "au": "y436d2fcdfc"}, {"en": "He'll be exhausted; he'll have been playing all day.", "es": "Estará agotado; habrá estado jugando todo el día.", "v": "m", "img": "u:photo-1619873736181-5bdf8fe0ea26", "au": "y48a9caa968"}]}, "t14p2": {"tip": "<p>¿<b>Futuro perfecto</b> o <b>futuro perfecto continuo</b>? Pregúntate qué quieres destacar:</p>\n<p><b>Resultado / cantidad</b> (¿cuánto? ¿cuántos?) → <b>will have + participio</b><br>\n<i>By Friday, she'<b>ll have answered 200 messages</b>.</i></p>\n<p>⏳ <b>Duración / proceso</b> (¿cuánto tiempo?) → <b>will have been + -ing</b><br>\n<i>By Friday, she'<b>ll have been answering</b> messages <b>for five hours straight</b>.</i></p>\n<p><b>Verbos de estado</b> (<b>know, be, own, believe, love</b>) <b>no</b> van en continuo: <i>Next month I'<b>ll have known</b> my best friend for ten years.</i> (<i>will have been knowing</i>)</p>\n<p>Pistas: números y cantidades → perfecto · <b>for / since / all day / non-stop</b> → continuo.</p>", "vocab": [{"en": "will have written three chapters", "es": "habrá escrito tres capítulos", "v": "f", "img": "u:photo-1553419096-efeafe17bbb7", "au": "y439376c614"}, {"en": "will have been writing for months", "es": "llevará meses escribiendo", "v": "m", "img": "u:photo-1579017308347-e53e0d2fc5e9", "au": "y4b2bdd2c23"}, {"en": "will have saved $100", "es": "habrá ahorrado 100 dólares", "v": "f", "img": "u:photo-1656049471454-ff3c59812741", "au": "y4ffcfb1125"}, {"en": "will have been saving for months", "es": "llevará meses ahorrando", "v": "m", "img": "u:photo-1585143790814-b40d4b829e4a", "au": "y4d3475898a"}, {"en": "will have run 10 miles", "es": "habrá corrido 10 millas", "v": "f", "img": "u:photo-1502904550040-7534597429ae", "au": "y484690606d"}, {"en": "will have been training since May", "es": "llevará entrenando desde mayo", "v": "m", "img": "u:photo-1544333323-ec9ed3218dd1", "au": "y433bde2bbf"}, {"en": "a completed result", "es": "un resultado terminado", "v": "f", "img": "u:photo-1588591795084-1770cb3be374", "au": "y403c31bc0e"}, {"en": "an ongoing activity", "es": "una actividad en curso", "v": "m", "img": "u:photo-1631032024590-140cc8dd4b32", "au": "y46a0efea8e"}], "sentences": [{"en": "By December, I'll have saved two hundred dollars.", "es": "Para diciembre habré ahorrado doscientos dólares.", "v": "f", "img": "u:photo-1622219999459-ab5b14e5f45a", "au": "y426cedc3e2"}, {"en": "By then, I'll have been saving for a year.", "es": "Para entonces llevaré un año ahorrando.", "v": "m", "img": "u:photo-1574607383476-f517f260d30b", "au": "y4dc9f22c23"}, {"en": "She'll have written three stories by the end of the year.", "es": "Habrá escrito tres cuentos para fin de año.", "v": "f", "img": "u:photo-1579017308347-e53e0d2fc5e9", "au": "y46813f12a0"}, {"en": "By noon, he'll have been training for four hours.", "es": "Al mediodía llevará cuatro horas entrenando.", "v": "m", "img": "u:photo-1560088971-123158b94b34", "au": "y46cd84a244"}, {"en": "We'll have collected five hundred books by Friday.", "es": "Para el viernes habremos recolectado quinientos libros.", "v": "f", "img": "u:photo-1634608341072-27cd7beae1b1", "au": "y46ca170cca"}, {"en": "By May, I'll have known my best friend for ten years.", "es": "En mayo llevaré diez años de conocer a mi mejor amigo.", "v": "m", "img": "u:photo-1530047139082-5435ca3c4614", "au": "y46659b5fa2"}]}, "t15p1": {"tip": "<p>En un debate de nivel <b>C1</b> no basta con decir <i>I think</i>. Usa estructuras que muestren que <b>piensas con matices</b>:</p>\n<p><b>Presentar una postura</b>: <i>It could be argued that…</i> (se podría argumentar que…) · <i>There is a strong case for…</i> (hay buenos argumentos a favor de…) · <i>I would argue that…</i></p>\n<p><b>Conceder</b> (reconocer el punto del otro): <b>While it is true that</b> AI helps with homework, <b>it</b> also… · <b>Admittedly,</b> … · <b>Granted,</b> …</p>\n<p><b>Contrastar</b>: <b>Nevertheless,</b> … · <b>Even so,</b> … · <b>That said,</b> … (van al inicio de la oración + coma).</p>\n<p><b>Concluir</b>: <b>On balance,</b> the benefits <b>outweigh</b> the risks. · <b>All things considered,</b> …</p>\n<p><b>Despite</b> va con sustantivo o -ing (<i>despite the risks</i>), nunca con sujeto + verbo. Para eso usa <b>although</b>.</p>", "vocab": [{"en": "artificial intelligence (AI)", "es": "inteligencia artificial (IA)", "v": "f", "img": "u:photo-1507146153580-69a1fe6d8aa1", "au": "y42a5ef7b04"}, {"en": "an AI homework helper", "es": "un asistente de tareas con IA", "v": "m", "img": "u:photo-1661595676644-6d03dff497c2", "au": "y4eb728480d"}, {"en": "to think for yourself", "es": "pensar por ti mismo", "v": "f", "img": "u:photo-1758876202610-bae5608f5051", "au": "y47da75ed51"}, {"en": "to save time", "es": "ahorrar tiempo", "v": "m", "img": "u:photo-1550534791-2677533605ab", "au": "y4367511bea"}, {"en": "to cheat on a test", "es": "hacer trampa en un examen", "v": "f", "img": "u:photo-1561089489-f13d5e730d72", "au": "y44646c7772"}, {"en": "a learning tool", "es": "una herramienta de aprendizaje", "v": "m", "img": "u:photo-1771765856781-3adbac14d75b", "au": "y4163f92b34"}, {"en": "the benefits outweigh the risks", "es": "los beneficios superan los riesgos", "v": "f", "img": "u:photo-1587740896339-96a76170508d", "au": "y4d99c58e29"}, {"en": "despite the risks", "es": "a pesar de los riesgos", "v": "m", "img": "u:photo-1759646827278-27c5733e0cee", "au": "y4dc2381529"}], "sentences": [{"en": "It could be argued that AI helps students learn faster.", "es": "Se podría argumentar que la IA ayuda a los estudiantes a aprender más rápido.", "v": "f", "img": "u:photo-1719159381981-1327b22aff9b", "au": "y4161e550cb"}, {"en": "While it is true that AI saves time, it can also make us lazy.", "es": "Si bien es cierto que la IA ahorra tiempo, también puede volvernos perezosos.", "v": "m", "img": "u:photo-1768767335345-5ea2dac1abfa", "au": "y4bf5d43964"}, {"en": "Admittedly, some students use AI homework helpers to cheat.", "es": "Hay que admitir que algunos estudiantes usan asistentes de tareas con IA para hacer trampa.", "v": "f", "img": "u:photo-1560785496-3c9d27877182", "au": "y4dd26cbad2"}, {"en": "Nevertheless, AI can be a great learning tool in the classroom.", "es": "Aun así, la IA puede ser una gran herramienta de aprendizaje en el salón.", "v": "m", "img": "u:photo-1724911549332-0087a61d768b", "au": "y43cd5cdf86"}, {"en": "Despite the risks, I would argue that AI belongs in schools.", "es": "A pesar de los riesgos, yo diría que la IA tiene un lugar en los colegios.", "v": "f", "img": "u:photo-1509062522246-3755977927d7", "au": "y449c9c8d72"}, {"en": "On balance, the benefits of AI outweigh the risks for students.", "es": "Sopesándolo todo, los beneficios de la IA superan los riesgos para los estudiantes.", "v": "m", "img": "u:photo-1758270705290-62b6294dd044", "au": "y43d747c566"}]}, "t16p1": {"tip": "<p>En un debate C1 debes <b>presentar las posturas de otros</b> antes de dar la tuya:</p>\n<p><b>Proponents argue that…</b> / <b>Supporters maintain that…</b> (los defensores sostienen que…)<br><b>Critics contend that…</b> / <b>Opponents claim that…</b> (los críticos sostienen que…)</p>\n<p><b>Rebatir</b> (refutar) con elegancia: <i>That argument <b>overlooks</b>…</i> (pasa por alto…) · <i><b>This is not to say that</b> uniforms are bad, but…</i> · <i><b>However compelling</b> the idea may be, …</i> (por muy convincente que sea…)</p>\n<p><b>Añadir</b> un argumento paralelo: <b>By the same token,</b> … (del mismo modo) · <b>Furthermore,</b> …</p>\n<p>Un buen contraargumento responde <b>directamente</b> a lo que dijo el otro. Atacar a la persona o cambiar de tema <b>no</b> es rebatir.</p>", "vocab": [{"en": "a school uniform", "es": "un uniforme escolar", "v": "f", "img": "u:photo-1753175843003-a7492d611bf9", "au": "y4b79a8939e"}, {"en": "a dress code", "es": "un código de vestimenta", "v": "m", "img": "u:photo-1683638520783-b7f228f41b14", "au": "y4e6c8bb091"}, {"en": "to express yourself", "es": "expresarte", "v": "f", "img": "u:photo-1713357831333-8b93263edadd", "au": "y4100d827a0"}, {"en": "peer pressure", "es": "presión de grupo", "v": "m", "img": "u:photo-1648250537652-a648421c588c", "au": "y467d2d32dc"}, {"en": "a sense of unity", "es": "un sentido de unidad", "v": "f", "img": "u:photo-1779903595032-4565c2e61cb3", "au": "y402226c703"}, {"en": "individuality", "es": "individualidad", "v": "m", "img": "u:photo-1607453998774-d533f65dac99", "au": "y4933f528df"}, {"en": "designer clothes", "es": "ropa de marca (de diseñador)", "v": "f", "img": "u:photo-1540221652346-e5dd6b50f3e7", "au": "y420114e8a1"}, {"en": "to stand out", "es": "destacarse", "v": "m", "img": "u:photo-1656402744389-67c2a1a4f378", "au": "y492040a3fa"}], "sentences": [{"en": "Proponents argue that uniforms create a sense of unity at school.", "es": "Los defensores sostienen que los uniformes crean un sentido de unidad en el colegio.", "v": "f", "img": "u:photo-1642140027867-e5983a32119c", "au": "y4b838b071c"}, {"en": "Critics contend that uniforms stop students from expressing themselves.", "es": "Los críticos sostienen que los uniformes impiden que los estudiantes se expresen.", "v": "m", "img": "u:photo-1503521010279-dbf437e68b79", "au": "y4d429e9fd5"}, {"en": "That argument overlooks the problem of peer pressure about clothes.", "es": "Ese argumento pasa por alto el problema de la presión de grupo por la ropa.", "v": "f", "img": "u:photo-1679389858333-685a155c3f40", "au": "y45af0e3e3c"}, {"en": "This is not to say that individuality is unimportant.", "es": "Esto no quiere decir que la individualidad no sea importante.", "v": "m", "img": "u:photo-1761244698434-9510e77b88c2", "au": "y4cd04f8f31"}, {"en": "However compelling the idea may be, uniforms can be uncomfortable.", "es": "Por muy convincente que sea la idea, los uniformes pueden ser incómodos.", "v": "f", "img": "u:photo-1697542636692-0d7577a242f1", "au": "y46ac56d500"}, {"en": "By the same token, a dress code can save time in the morning.", "es": "Del mismo modo, un código de vestimenta puede ahorrar tiempo por la mañana.", "v": "m", "img": "u:photo-1758687126704-900d61790795", "au": "y45b166c8aa"}]}, "t17p1": {"tip": "<p>Cuando hablamos de <b>salud y ciencia</b>, un hablante C1 es <b>prudente</b>: no exagera la evidencia.</p>\n<p><b>Citar evidencia con cautela</b>: <i>Many studies suggest that…</i> · <i>There is growing evidence that…</i> · <i>Research <b>indicates</b> a link between…</i></p>\n<p><b>Verbos suaves</b>: <i>may <b>contribute to</b></i>, <i>can <b>exacerbate</b></i>, <i><b>tend to</b> + verbo</i>, <i>is <b>associated with</b></i> — en lugar de <i>causes</i>.</p>\n<p><b>Evitar simplificar</b>: <i><b>It would be simplistic to claim that</b> video games alone cause bad grades.</i> · <i>A <b>correlation</b> does not necessarily imply <b>causation</b>.</i></p>\n<p><b>Equilibrar</b>: <i>On the one hand…, on the other hand…</i></p>\n<p>Tema sensible: habla con respeto y sin juzgar. Si alguien está pasando un mal momento, lo mejor es hablar con una persona de confianza o un profesional.</p>", "vocab": [{"en": "well-being", "es": "bienestar", "v": "f", "img": "u:photo-1637878257903-7f08eab9a7f2", "au": "y47025342a7"}, {"en": "screen time", "es": "tiempo frente a la pantalla", "v": "m", "img": "u:photo-1495654794940-1c0cd2aeedc1", "au": "y479f1061d7"}, {"en": "a good night's sleep", "es": "una buena noche de sueño", "v": "f", "img": "u:photo-1672928499660-58693df7af84", "au": "y451af3d806"}, {"en": "to compare yourself to others", "es": "compararte con los demás", "v": "m", "img": "u:photo-1758611973525-b5a86f468b5e", "au": "y47b2cc607a"}, {"en": "fear of missing out (FOMO)", "es": "miedo a perderse algo (FOMO)", "v": "f", "img": "u:photo-1630993094890-f7d47e9dcf56", "au": "y4d1923643b"}, {"en": "a sense of belonging", "es": "un sentido de pertenencia", "v": "m", "img": "u:photo-1491438590914-bc09fcaaf77a", "au": "y410aa6acec"}, {"en": "cyberbullying", "es": "ciberacoso", "v": "f", "img": "u:photo-1477773265277-18890e138cfe", "au": "y4a8c0e87cc"}, {"en": "a healthy habit", "es": "un hábito saludable", "v": "m", "img": "u:photo-1543095834-7445b8af8c2b", "au": "y40a4245e17"}], "sentences": [{"en": "Many studies suggest a link between screen time and poor sleep.", "es": "Muchos estudios sugieren una relación entre el tiempo frente a la pantalla y dormir mal.", "v": "f", "img": "u:photo-1587926814183-abdb5c478818", "au": "y435e9a1dca"}, {"en": "It would be simplistic to claim that video games alone cause bad grades.", "es": "Sería simplista afirmar que los videojuegos por sí solos causan malas notas.", "v": "m", "img": "u:photo-1554410637-1a8267402b57", "au": "y46caff13ab"}, {"en": "For some kids, online games provide a sense of belonging.", "es": "Para algunos niños, los juegos en línea brindan un sentido de pertenencia.", "v": "f", "img": "u:photo-1493711662062-fa541adb3fc8", "au": "y444bc61878"}, {"en": "Using a phone late at night can exacerbate stress and disrupt sleep.", "es": "Usar el celular tarde en la noche puede agravar el estrés y alterar el sueño.", "v": "m", "img": "u:photo-1552858725-2758b5fb1286", "au": "y403bd1e3a3"}, {"en": "Teens tend to compare themselves to others on social media.", "es": "Los adolescentes tienden a compararse con los demás en las redes sociales.", "v": "f", "img": "u:photo-1758611973525-b5a86f468b5e", "au": "y43a24122dd"}, {"en": "A correlation does not necessarily imply causation.", "es": "Una correlación no implica necesariamente causalidad.", "v": "m", "img": "u:photo-1543286386-713bdd548da4", "au": "y4cb4ea2c26"}]}, "t18p1": {"tip": "<p>En temas delicados como la justicia, el hablante C1 <b>matiza</b> (<i>hedging</i>): evita los absolutos y respeta otras posturas.</p>\n<p><b>Cambia los absolutos</b>: <i>all → many / most</i> · <i>always → often / tend to</i> · <i>never → rarely / seldom</i> · <i>is → can be / may be</i></p>\n<p><b>Matizadores</b>: <b>To a certain extent</b> (hasta cierto punto) · <b>To some degree</b> · <b>Arguably</b> (podría decirse que) · <b>In many cases</b> · <b>Broadly speaking</b></p>\n<p><b>Definir antes de opinar</b>: <i><b>It depends on how we define</b> fairness: equal treatment or equal results?</i></p>\n<p><b>Discrepar con respeto</b>: <i>That is not entirely accurate.</i> · <i>I'm not entirely convinced.</i> · <i>I see it slightly differently.</i></p>\n<p>Ojo: se dice <b>to a certain ext<u>ent</u></b> (no <i>extend</i>) y <b>tend to</b> + verbo (<i>tend to receive</i>).</p>", "vocab": [{"en": "equal treatment", "es": "trato igual", "v": "f", "img": "u:photo-1758270704925-fa59d93119c1", "au": "y40c5b216cf"}, {"en": "a fair rule", "es": "una regla justa", "v": "m", "img": "u:photo-1786667395565-ce2a4e415fa9", "au": "y4489ba6940"}, {"en": "to take turns", "es": "turnarse", "v": "f", "img": "u:photo-1631512700403-ee66a05fd497", "au": "y4eaccbeda2"}, {"en": "a level playing field", "es": "igualdad de condiciones", "v": "m", "img": "u:photo-1603291697926-7e5822ed1ac5", "au": "y451444cd26"}, {"en": "to reward effort", "es": "recompensar el esfuerzo", "v": "f", "img": "u:photo-1769867627165-0e758f44a0a2", "au": "y4c0c6a3ac9"}, {"en": "extra help", "es": "ayuda adicional", "v": "m", "img": "u:photo-1583468982228-19f19164aee2", "au": "y4b4561922c"}, {"en": "a team captain", "es": "un capitán de equipo", "v": "f", "img": "u:photo-1610736342165-4eeb4aef66ca", "au": "y4967ad5586"}, {"en": "equal results", "es": "resultados iguales", "v": "m", "img": "u:photo-1517164850305-99a3e65bb47e", "au": "y439a2dcbe0"}], "sentences": [{"en": "To a certain extent, our school rewards effort and talent.", "es": "Hasta cierto punto, nuestro colegio recompensa el esfuerzo y el talento.", "v": "f", "img": "u:photo-1773828948581-5b50c6ee17a2", "au": "y4b8a4647a2"}, {"en": "Team captains tend to choose their best friends first.", "es": "Los capitanes de equipo tienden a escoger primero a sus mejores amigos.", "v": "m", "img": "u:photo-1526232761682-d26e03ac148e", "au": "y46aebb084e"}, {"en": "Arguably, students who need extra help should get more time.", "es": "Podría decirse que los estudiantes que necesitan ayuda adicional deberían tener más tiempo.", "v": "f", "img": "u:photo-1534644107580-3a4dbd494a95", "au": "y453bb304ed"}, {"en": "Broadly speaking, most class rules are fair.", "es": "En términos generales, la mayoría de las reglas del salón son justas.", "v": "m", "img": "u:photo-1694757283921-aefccec06443", "au": "y48f91f48cd"}, {"en": "It depends on how we define fairness: equal treatment or equal results?", "es": "Depende de cómo definamos la justicia: ¿trato igual o resultados iguales?", "v": "f", "img": "u:photo-1587740896339-96a76170508d", "au": "y486fcb8151"}, {"en": "I see it slightly differently: taking turns can be fairer.", "es": "Yo lo veo un poco diferente: turnarse puede ser más justo.", "v": "m", "img": "u:photo-1594608661623-aa0bd3a69d98", "au": "y48e5bb615e"}]}, "t19p1": {"tip": "<p>Para <b>comparar y contrastar</b> dos modelos como un hablante C1:</p>\n<p><b>Whereas / While</b> + cláusula: <i><b>Whereas</b> classrooms offer structure, online courses offer flexibility.</i></p>\n<p><b>Conversely,</b> / <b>In contrast,</b> / <b>On the other hand,</b> + oración completa (al inicio, con coma).</p>\n<p><b>Unlike</b> + sustantivo: <i><b>Unlike</b> traditional classes, online courses…</i> (¡nunca <i>unlike to</i>!).</p>\n<p><b>Comparativos avanzados</b>: <i>far more flexible than</i> · <i>not nearly as expensive as</i> · <i><b>The more</b> you participate, <b>the more</b> you learn.</i></p>\n<p>En un texto argumentativo, cada oración debe <b>apoyar la idea principal</b> del párrafo (coherencia) y los conectores deben tener <b>lógica</b>: <i>therefore</i> = consecuencia, <i>however</i> = contraste.</p>", "vocab": [{"en": "face-to-face classes", "es": "clases presenciales", "v": "f", "img": "u:photo-1577896851231-70ef18881754", "au": "y47a572e5c4"}, {"en": "online lessons", "es": "clases en línea", "v": "m", "img": "u:photo-1597933471507-1ca5765185d8", "au": "y440e50f9fd"}, {"en": "self-discipline", "es": "autodisciplina", "v": "f", "img": "u:photo-1598981457915-aea220950616", "au": "y4a29081dd8"}, {"en": "a reliable internet connection", "es": "una conexión a internet confiable", "v": "m", "img": "u:photo-1745847768408-b7b83796cae6", "au": "y45d3cadb22"}, {"en": "classmates", "es": "compañeros de clase", "v": "f", "img": "u:photo-1543269865-cbf427effbad", "au": "y4a86fd3f56"}, {"en": "blended learning", "es": "aprendizaje mixto (semipresencial)", "v": "m", "img": "u:photo-1581726707445-75cbe4efc586", "au": "y4a138138ee"}, {"en": "to learn at your own pace", "es": "aprender a tu propio ritmo", "v": "f", "img": "u:photo-1543269664-76bc3997d9ea", "au": "y4a35f94ebd"}, {"en": "a printed textbook", "es": "un libro de texto impreso", "v": "m", "img": "u:photo-1760840415387-fc8ff3f11dff", "au": "y4f59db8018"}], "sentences": [{"en": "Whereas classrooms offer structure, online lessons offer flexibility.", "es": "Mientras que los salones ofrecen estructura, las clases en línea ofrecen flexibilidad.", "v": "f", "img": "u:photo-1758270705518-b61b40527e76", "au": "y424ba7e86a"}, {"en": "Unlike face-to-face classes, online lessons let you learn at your own pace.", "es": "A diferencia de las clases presenciales, las clases en línea te permiten aprender a tu propio ritmo.", "v": "m", "img": "u:photo-1581091595283-04de15a05a01", "au": "y4d6948c0bf"}, {"en": "Online learning requires far more self-discipline than many kids expect.", "es": "Aprender en línea requiere mucha más autodisciplina de lo que muchos niños esperan.", "v": "f", "img": "u:photo-1758612898304-1a6bb546ac44", "au": "y4053525347"}, {"en": "Conversely, face-to-face classes make it easier to talk with classmates.", "es": "Por el contrario, las clases presenciales facilitan hablar con los compañeros.", "v": "m", "img": "u:photo-1758270704787-615782711641", "au": "y43d547d1db"}, {"en": "An e-book is not nearly as heavy as a printed textbook.", "es": "Un libro electrónico no es ni de cerca tan pesado como un libro de texto impreso.", "v": "f", "img": "u:photo-1650500426868-27a68714a4a4", "au": "y451114686e"}, {"en": "The more you participate, the more you learn.", "es": "Cuanto más participas, más aprendes.", "v": "m", "img": "u:photo-1758270704417-26c1244cfaf3", "au": "y43444a7aad"}]}, "t20p1": {"tip": "<p>En un <b>student council</b> (consejo estudiantil) o mesa redonda, el lenguaje del <b>moderador</b> y de la <b>concesión</b> es clave:</p>\n<p><b>Conceder</b> antes de discrepar: <b>Granted,</b> a class vote is fast… <b>but</b> … · <b>I take your point, but</b> … · <b>Fair enough, however</b> …</p>\n<p><b>Moderar</b>: <i>Could you <b>elaborate on</b> that?</i> (¿podría ampliar?) · <i>Let's <b>get back to</b> the question.</i> · <i>Please let her <b>finish</b>.</i> · <i>We <b>haven't heard from</b> you yet.</i> · <i>Let's focus on <b>the argument, not the person</b>.</i> · <i>Do you have a <b>source</b> for that?</i></p>\n<p><b>Hipótesis</b> sobre el futuro: <i><b>If</b> students <b>were</b> better informed, the vote <b>might</b> be fairer.</i></p>\n<p>Tema de debate: en esta lección <b>no hay bando correcto</b>. Practica presentar ideas de forma <b>neutral</b>, con datos y respeto.</p>", "vocab": [{"en": "the student council", "es": "el consejo estudiantil", "v": "f", "img": "u:photo-1776178320206-f42b9a9cf996", "au": "y40e5ae43d7"}, {"en": "a class vote", "es": "una votación en clase", "v": "m", "img": "u:photo-1684145344919-4dd45da4eef1", "au": "y4896cfde7a"}, {"en": "a class representative", "es": "un representante de curso", "v": "f", "img": "u:photo-1509062522246-3755977927d7", "au": "y4f836b8fe2"}, {"en": "fake news", "es": "noticias falsas", "v": "m", "img": "u:photo-1758612897668-ce0c153745e4", "au": "y40863d98ab"}, {"en": "a reliable source", "es": "una fuente confiable", "v": "f", "img": "u:photo-1603058817990-2b9a9abbce86", "au": "y43d293fff4"}, {"en": "to take turns speaking", "es": "turnarse para hablar", "v": "m", "img": "u:photo-1598012341530-36f4b00dd2ad", "au": "y42916b5086"}, {"en": "to listen to every voice", "es": "escuchar todas las voces", "v": "f", "img": "u:photo-1509062522246-3755977927d7", "au": "y499d55308f"}, {"en": "to keep promises", "es": "cumplir las promesas", "v": "m", "img": "u:photo-1593526613712-7b4b9a707330", "au": "y4a808459f7"}], "sentences": [{"en": "Granted, a class vote is fast, but not everyone gets to speak.", "es": "Es cierto que una votación en clase es rápida, pero no todos pueden hablar.", "v": "f", "img": "u:photo-1540910419892-4a36d2c3266c", "au": "y4d18693529"}, {"en": "Could you elaborate on that idea for the student council?", "es": "¿Podrías ampliar esa idea para el consejo estudiantil?", "v": "m", "img": "u:photo-1581726690015-c9861fa5057f", "au": "y42c0b29eab"}, {"en": "Please let her finish; we can take turns speaking.", "es": "Por favor, déjala terminar; podemos turnarnos para hablar.", "v": "f", "img": "u:photo-1581726690015-c9861fa5057f", "au": "y4e37cf2758"}, {"en": "We haven't heard from you yet. What do you think?", "es": "Todavía no te hemos escuchado. ¿Qué opinas?", "v": "m", "img": "u:photo-1773243906471-909ac5d3496e", "au": "y4216aafe0d"}, {"en": "Do you have a reliable source for that? It might be fake news.", "es": "¿Tienes una fuente confiable para eso? Podría ser una noticia falsa.", "v": "f", "img": "u:photo-1610484826967-09c5720778c7", "au": "y478b0c2eca"}, {"en": "If everyone listened to every voice, our debates might be calmer.", "es": "Si todos escucharan todas las voces, nuestros debates podrían ser más tranquilos.", "v": "m", "img": "u:photo-1509062522246-3755977927d7", "au": "y40463dcd2c"}]}, "t21p1": {"tip": "<p>Para <b>formular hipótesis</b> con estilo C1 usamos la <b>inversión</b> en las condicionales (más formal, típica de debates y ensayos):</p>\n<p><b>Had</b> + sujeto + participio = <i>If… had…</i> → <i><b>Had we not explored</b> space, we wouldn't have GPS.</i> (Si no hubiéramos explorado…)</p>\n<p><b>Were</b> + sujeto + <b>to</b> + verbo = <i>If… were to…</i> → <i><b>Were we to live</b> on Mars, we would need to grow our own food.</i> (Si llegáramos a…)</p>\n<p><b>Should</b> + sujeto + verbo = <i>If… ever…</i> → <i><b>Should humanity need</b> a second home, …</i> (Si alguna vez…)</p>\n<p><b>Condicional mixta</b> (pasado → presente): <i>If we <b>hadn't explored</b> space, we <b>wouldn't have</b> satellite TV <b>today</b>.</i></p>\n<p>En la inversión <b>no</b> se usa <i>if</i>: Incorrecto: <i>If had we…</i> · Correcto: <i>Had we…</i></p>", "vocab": [{"en": "space exploration", "es": "exploración espacial", "v": "f", "img": "u:photo-1454789548928-9efd52dc4031", "au": "y41bedfeddc"}, {"en": "a crewed mission", "es": "una misión tripulada", "v": "m", "img": "u:photo-1759327769172-b6a041f5ed03", "au": "y4738f6f031"}, {"en": "satellite technology", "es": "tecnología satelital", "v": "f", "img": "u:photo-1446776811953-b23d57bd21aa", "au": "y4f0109a757"}, {"en": "a space station", "es": "una estación espacial", "v": "m", "img": "u:photo-1446776877081-d282a0f896e2", "au": "y49bc7fd87a"}, {"en": "a rocket launch", "es": "un lanzamiento de cohete", "v": "f", "img": "u:photo-1517976487492-5750f3195933", "au": "y4740f8cbfc"}, {"en": "problems on Earth", "es": "problemas en la Tierra", "v": "m", "img": "u:photo-1526951521990-620dc14c214b", "au": "y4235b312ec"}, {"en": "to live on Mars", "es": "vivir en Marte", "v": "f", "img": "u:photo-1635349429385-201ee3a51b88", "au": "y482729977d"}, {"en": "a scientific discovery", "es": "un descubrimiento científico", "v": "m", "img": "u:photo-1570349611593-7c001c354148", "au": "y480d3c575c"}], "sentences": [{"en": "Had we not explored space, we wouldn't have GPS or good weather forecasts.", "es": "Si no hubiéramos explorado el espacio, no tendríamos GPS ni buenos pronósticos del tiempo.", "v": "f", "img": "u:photo-1587400873582-230980eb46eb", "au": "y418a1d783c"}, {"en": "Were we to live on Mars, we would need to grow our own food.", "es": "Si llegáramos a vivir en Marte, tendríamos que cultivar nuestra propia comida.", "v": "m", "img": "u:photo-1637987327476-5c77df3cb16d", "au": "y4f0df0dd22"}, {"en": "Should you ever visit a space station, you would float like a feather.", "es": "Si alguna vez visitaras una estación espacial, flotarías como una pluma.", "v": "f", "img": "u:photo-1454789548928-9efd52dc4031", "au": "y4b8d829093"}, {"en": "Had scientists not built satellites, we couldn't watch soccer matches from other countries.", "es": "Si los científicos no hubieran construido satélites, no podríamos ver partidos de fútbol de otros países.", "v": "m", "img": "u:photo-1730933900185-6bf7eeefe23f", "au": "y4fe22ee32a"}, {"en": "If astronauts hadn't visited the Moon, we would know less about it today.", "es": "Si los astronautas no hubieran visitado la Luna, hoy sabríamos menos sobre ella.", "v": "f", "img": "u:photo-1614315517650-3771cf72d18a", "au": "y4a3885bb9c"}, {"en": "Some people argue the money should help solve problems on Earth.", "es": "Algunas personas sostienen que el dinero debería ayudar a resolver problemas en la Tierra.", "v": "m", "img": "u:photo-1554171595-4547fca1d379", "au": "y4d57e35e0e"}]}}, "kids": {"t1p1": {"reading": {"title": "The zoo trip", "text": "Tomorrow our class is going to the zoo. This morning Ms. Rivera told us the rules. \"If you get lost, stay where you are. Unless you hold your buddy's hand, you can't cross the street.\" My best friend Sam is always running late, so I told him, \"If you miss the bus, you'll miss the zoo!\" He promised to set two alarms. The weather app says it might rain. If it rains, we'll visit the reptile house first. As soon as we arrive, I'll look for the pandas. The odds are they'll be asleep, but I don't mind!", "au": "y4841f9ee90", "img": "u:photo-1714466614031-b128463b8767", "q": [{"s": "The class is going to the zoo tomorrow.", "a": "yes"}, {"s": "Sam is never late.", "a": "no"}, {"s": "If it rains, they'll visit the reptile house first.", "a": "yes"}, {"s": "The narrator will look for the lions first.", "a": "no"}]}, "keyq": [{"q": "Will you play outside if it's sunny this weekend?", "es": "¿Jugarás afuera si hace sol este fin de semana?", "a": "Yes, I will. If it's sunny, I'll ride my bike.", "qau": "y450c38d81a", "aau": "y4ce10fc4b0"}, {"q": "Will you call a friend as soon as you finish your homework today?", "es": "¿Llamarás a un amigo tan pronto como termines tu tarea hoy?", "a": "Yes, I will. I'll call Ana as soon as I finish.", "qau": "y43297ae77f", "aau": "y410cb48b64"}, {"q": "Will you go to the park tomorrow unless it rains?", "es": "¿Irás al parque mañana a menos que llueva?", "a": "Yes, I will. Unless it rains, I'll play soccer there.", "qau": "y483d9be33e", "aau": "y40d3dff8a5"}]}, "t1p2": {"reading": {"title": "The puppy deal", "text": "Lucy wants a puppy, but her parents aren't sure. So she made a plan to negotiate. \"I'll walk the dog every day,\" she said. \"You can have a puppy as long as you feed it, too,\" Dad answered. Mom made a counteroffer: \"Provided that your grades stay good, we'll visit the shelter on Saturday.\" Lucy agreed. Then her little brother Max said, \"I'll help only if I can choose the name!\" Everyone laughed. They met halfway: Lucy will pick the first name, and Max will pick the middle name. Mom packed some treats in case they found the perfect puppy.", "au": "y484441ec53", "img": "u:photo-1613924457768-4c1f46f43d11", "q": [{"s": "Lucy wants a kitten.", "a": "no"}, {"s": "Mom says they'll visit the shelter if Lucy's grades stay good.", "a": "yes"}, {"s": "Max will pick the middle name.", "a": "yes"}, {"s": "Mom packed toys in case they found a puppy.", "a": "no"}]}, "keyq": [{"q": "Can you play video games as long as you finish your homework?", "es": "¿Puedes jugar videojuegos siempre y cuando termines tu tarea?", "a": "Yes, I can. I can play as long as I finish first.", "qau": "y410b8af496", "aau": "y402a66b8c2"}, {"q": "Do you take an umbrella to school in case it rains?", "es": "¿Llevas un paraguas al colegio por si llueve?", "a": "Yes, I do. I take one in case it rains.", "qau": "y4673af105c", "aau": "y4956644ff8"}, {"q": "Will you share your snack only if your friend shares too?", "es": "¿Compartirás tu merienda solo si tu amigo también comparte?", "a": "No, I won't. I'll share it as long as he's hungry.", "qau": "y46f475fb8e", "aau": "y4edfee6073"}]}, "t2p1": {"reading": {"title": "If I had superpowers", "text": "Our teacher asked us a fun question: \"What would you do if you had superpowers?\" Everyone had a different answer. Mateo said, \"If I could fly, I'd get to school in two minutes.\" Sofia wanted to be invisible. \"If I were invisible, I'd sneak into the kitchen and eat all the cookies!\" she laughed. Ben said he would talk to animals, so he could ask his cat why she sleeps all day. My answer was different. If I had superpowers, I'd clean the ocean and save the whales. My teacher smiled and said, \"That would be a dream come true.\"", "au": "y4fd60fbe2c", "img": "u:photo-1750370220313-9a50220d6ab1", "q": [{"s": "Mateo would fly to school.", "a": "yes"}, {"s": "Sofia wanted to talk to animals.", "a": "no"}, {"s": "Ben has a dog.", "a": "no"}, {"s": "The narrator would clean the ocean.", "a": "yes"}]}, "keyq": [{"q": "Would you fly if you had wings?", "es": "¿Volarías si tuvieras alas?", "a": "Yes, I would. If I had wings, I'd fly to my grandma's house.", "qau": "y431b935e3e", "aau": "y48832536cb"}, {"q": "Would you live on a farm if you could?", "es": "¿Vivirías en una granja si pudieras?", "a": "Yes, I would. If I lived on a farm, I'd have horses.", "qau": "y463e9c9df4", "aau": "y4c824c6fdb"}, {"q": "Would you eat pizza every day if your parents let you?", "es": "¿Comerías pizza todos los días si tus papás te dejaran?", "a": "No, I wouldn't. If I ate pizza every day, I'd get bored.", "qau": "y468c2acefc", "aau": "y45bb505445"}]}, "t2p2": {"reading": {"title": "Dear Dana: should I tell the truth?", "text": "Dear Dana, I'm ten. Yesterday I broke my sister's favorite toy by accident, and she doesn't know. What would you do if you were me? — Worried Will. Dear Will, this is a tough call, but I have some advice. If I were in your shoes, I'd tell her the truth today. If you hid the toy, she would find it later and feel worse. You could offer to fix it or share one of your toys. I wouldn't buy her a new one unless you couldn't fix it. Would she be angry? Maybe a little. But she would trust you more. — Dana", "au": "y466d410907", "img": "u:photo-1467103789230-f91a5ff8048a", "q": [{"s": "Will broke the toy on purpose.", "a": "no"}, {"s": "Dana would tell the truth today.", "a": "yes"}, {"s": "Dana thinks Will should hide the toy.", "a": "no"}, {"s": "Dana says the sister would trust Will more.", "a": "yes"}]}, "keyq": [{"q": "Would you return a wallet if you found one?", "es": "¿Devolverías una billetera si encontraras una?", "a": "Yes, I would. I'd give it to a teacher.", "qau": "y4493440224", "aau": "y4a24d08626"}, {"q": "Would you share your lunch if a friend forgot his?", "es": "¿Compartirías tu almuerzo si un amigo olvidara el suyo?", "a": "Yes, I would. If I were him, I'd want help too.", "qau": "y4c6699c380", "aau": "y4b42edff9c"}, {"q": "Would you speak up if someone was mean to a classmate?", "es": "¿Hablarías si alguien fuera grosero con un compañero?", "a": "Yes, I would. I'd tell them to stop.", "qau": "y408e2f826d", "aau": "y45d79e9feb"}]}, "t3p1": {"reading": {"title": "The party I almost missed", "text": "Last year my cousin Emma had her birthday party at the water park. The night before, I stayed up late playing video games, and I forgot to set my alarm. If I hadn't played so late, I wouldn't have overslept. Then Dad took the wrong exit, and we got lost. If only we had left earlier! We arrived just as Emma was cutting the cake. It was a close call. In hindsight, it was funny. Emma saved me the last slice, and it was the biggest one. If we had arrived on time, I wouldn't have gotten it!", "au": "y4efc493e50", "img": "u:photo-1790699591318-3e51966ea13c", "q": [{"s": "The party was at the water park.", "a": "yes"}, {"s": "The narrator set an alarm.", "a": "no"}, {"s": "Dad took the wrong exit.", "a": "yes"}, {"s": "They arrived after the cake was gone.", "a": "no"}]}, "keyq": [{"q": "Would you have gone to the park yesterday if it had been sunny?", "es": "¿Habrías ido al parque ayer si hubiera hecho sol?", "a": "Yes, I would have. I would have played soccer there.", "qau": "y4ed38342f1", "aau": "y482ab04af2"}, {"q": "Would you have finished your homework faster if you hadn't watched TV?", "es": "¿Habrías terminado tu tarea más rápido si no hubieras visto televisión?", "a": "Yes, I would have. I would have finished it in an hour.", "qau": "y480b0845dd", "aau": "y4ef1fa6eab"}, {"q": "Would your teacher have been happy if you had forgotten your homework?", "es": "¿Tu profesora habría estado contenta si hubieras olvidado tu tarea?", "a": "No, she wouldn't have. She would have been upset.", "qau": "y42febb3bfe", "aau": "y4d92e724b0"}]}, "t3p2": {"reading": {"title": "The volcano that didn't erupt", "text": "Last month my friend Tom and I made a volcano for the science fair. We should have started early, but we waited until the night before. We blew it. The volcano didn't erupt! \"We shouldn't have used so much glue,\" Tom said. Our teacher, Mr. Lee, told us, \"If you had tested it at home, you would know what went wrong now.\" He was right. It was a wake-up call. This month we started our new project three weeks early. If we hadn't failed last time, we wouldn't be so organized today. Sometimes you learn the hard way!", "au": "y45192994e5", "img": "u:photo-1582721478779-0ae163c05a60", "q": [{"s": "Tom and the narrator made a volcano.", "a": "yes"}, {"s": "They started the project early.", "a": "no"}, {"s": "The volcano erupted perfectly.", "a": "no"}, {"s": "They started the new project three weeks early.", "a": "yes"}]}, "keyq": [{"q": "Should you have gone to bed earlier last night?", "es": "¿Debiste haberte acostado más temprano anoche?", "a": "Yes, I should have. I shouldn't have watched TV so late.", "qau": "y4d504d2437", "aau": "y413f7d6d96"}, {"q": "Would you be a better swimmer now if you had taken lessons last year?", "es": "¿Nadarías mejor ahora si hubieras tomado clases el año pasado?", "a": "Yes, I would. If I had taken lessons, I'd swim faster now.", "qau": "y42ecdd1809", "aau": "y41689a8af7"}, {"q": "Did you say something yesterday that you shouldn't have said?", "es": "¿Dijiste algo ayer que no debiste haber dicho?", "a": "Yes, I did. I shouldn't have called my brother lazy.", "qau": "y4dc2ab4070", "aau": "y46c721a12a"}]}, "t4p1": {"reading": {"title": "Why I decided to learn to swim", "text": "Last summer I couldn't swim, and I hated waiting on the beach while my cousins played in the water. So I decided to take lessons. At first, I refused to put my face in the water. My coach, Ms. Ruiz, kept saying, \"Keep trying!\" She suggested practicing for ten minutes every day. After a month, I managed to swim across the pool. Now I really enjoy swimming, and I'm looking forward to going to the beach again. I can't stand sitting on the sand anymore! My little brother wants to learn too, and I've agreed to help him.", "au": "y47d94fbf5a", "img": "u:photo-1651614158095-b98b6c1da74b", "q": [{"s": "The narrator could swim last summer.", "a": "no"}, {"s": "Ms. Ruiz suggested practicing every day.", "a": "yes"}, {"s": "After a week, the narrator swam across the pool.", "a": "no"}, {"s": "The narrator agreed to help a little brother.", "a": "yes"}]}, "keyq": [{"q": "Do you enjoy playing video games?", "es": "¿Disfrutas jugar videojuegos?", "a": "Yes, I do. I enjoy playing with my cousins.", "qau": "y4302f2b892", "aau": "y4d957704f5"}, {"q": "Do you avoid eating vegetables?", "es": "¿Evitas comer verduras?", "a": "No, I don't. I actually enjoy eating carrots.", "qau": "y46648f0e56", "aau": "y4327e946f2"}, {"q": "Are you looking forward to going on vacation?", "es": "¿Tienes muchas ganas de irte de vacaciones?", "a": "Yes, I am. I'm looking forward to swimming in the ocean.", "qau": "y4ecfb400a3", "aau": "y410d7ee441"}]}, "t4p2": {"reading": {"title": "The camping trip", "text": "Last summer my family went camping by a lake. Before we left, Mom said, \"Remember to pack the flashlight!\" Of course, I forgot to do it. That night it was very dark. I tried to stay calm, but I could hear strange noises. Dad tried using his phone light, but the battery was low. Then we stopped to listen. It was just a family of raccoons! I remember laughing so hard that I cried. I'll never forget seeing them steal our marshmallows. Do I regret forgetting the flashlight? A little. Next time, I'll remember to pack it.", "au": "y411472c026", "img": "u:photo-1674230316788-d9c8b92f0d63", "q": [{"s": "The family went camping by a lake.", "a": "yes"}, {"s": "The narrator packed the flashlight.", "a": "no"}, {"s": "The noises came from bears.", "a": "no"}, {"s": "Raccoons took the marshmallows.", "a": "yes"}]}, "keyq": [{"q": "Do you remember starting first grade?", "es": "¿Recuerdas haber empezado primer grado?", "a": "Yes, I do. I remember crying on the first day.", "qau": "y45c5009b1a", "aau": "y41bc1b5c60"}, {"q": "Did you remember to brush your teeth this morning?", "es": "¿Te acordaste de cepillarte los dientes esta mañana?", "a": "Yes, I did. I always remember to brush them.", "qau": "y4ad78844fd", "aau": "y4bd13ee7ab"}, {"q": "Do you try restarting your tablet when it freezes?", "es": "¿Pruebas reiniciar tu tableta cuando se congela?", "a": "Yes, I do. If that doesn't help, I ask my dad.", "qau": "y417aa47b15", "aau": "y477328cd60"}]}, "t5p1": {"reading": {"title": "My new friend at camp", "text": "On the first day of camp, I met a girl named Mia. \"I love horses,\" she said. \"So do I!\" I answered. Then she said, \"I can't swim very well.\" \"Neither can I,\" I said, and we both laughed. We had so much in common! But we didn't agree on everything. \"I don't like chocolate,\" Mia said. \"Really? I do!\" I told her. \"I've never been on a boat,\" she said. \"Oh, I have. It's fun!\" By the end of the day, we were best friends. It's nice to have things in common, but it's fun to be different, too.", "au": "y46694c6ccb", "img": "u:photo-1596754779593-fdd862cbe791", "q": [{"s": "Mia loves horses.", "a": "yes"}, {"s": "The narrator can swim very well.", "a": "no"}, {"s": "Mia likes chocolate.", "a": "no"}, {"s": "The narrator has been on a boat.", "a": "yes"}]}, "keyq": [{"q": "Do you like rainy days?", "es": "¿Te gustan los días lluviosos?", "a": "No, I don't. Neither does my sister.", "qau": "y4cd19308b6", "aau": "y451f674a88"}, {"q": "Can you ride a bike?", "es": "¿Sabes montar en bicicleta?", "a": "Yes, I can. So can my little brother.", "qau": "y49201a3502", "aau": "y4ca749cc49"}, {"q": "Have you ever seen a whale?", "es": "¿Alguna vez has visto una ballena?", "a": "No, I haven't. Neither have my friends.", "qau": "y4b5558a17c", "aau": "y49a22ae60b"}]}, "t5p2": {"reading": {"title": "The great pet debate", "text": "My parents said we could get either a cat or a dog, but not both. My sister and I thought the decision would be easy. It wasn't! Both cats and dogs are cute, and both need a lot of care. My sister didn't want a pet that barks all night, and I didn't either. But neither of us wanted a pet that scratches the sofa. Neither Mom nor Dad helped. \"We'll be happy either way,\" they said. Finally, we visited the shelter and met a calm old dog named Pepper. \"Pepper never barks,\" the man said. \"He doesn't?\" I asked. We took him home that day.", "au": "y4a9c5e29d9", "img": "u:photo-1732001804525-dc03d449e333", "q": [{"s": "They could get both a cat and a dog.", "a": "no"}, {"s": "The narrator didn't want a pet that barks all night.", "a": "yes"}, {"s": "Mom and Dad helped them choose.", "a": "no"}, {"s": "Pepper is a calm old dog.", "a": "yes"}]}, "keyq": [{"q": "Do you like both cats and dogs?", "es": "¿Te gustan tanto los gatos como los perros?", "a": "Yes, I do. Both cats and dogs are cute.", "qau": "y4feb08eeac", "aau": "y43f9c8a0a8"}, {"q": "Can you speak either French or German?", "es": "¿Sabes hablar francés o alemán?", "a": "No, I can't. I speak neither French nor German.", "qau": "y41a85d4b47", "aau": "y4aab19931f"}, {"q": "Do you like broccoli?", "es": "¿Te gusta el brócoli?", "a": "No, I don't. My brother doesn't either.", "qau": "y406a08195a", "aau": "y48d7df2669"}]}, "t6p1": {"reading": {"title": "The messy kitchen", "text": "When Mom came home on Saturday, the kitchen was a disaster. There was flour on the floor, and Lucas and his sister Ana were covered in it. \"What have you been doing?\" Mom asked. \"We've been baking a cake for Grandpa's birthday,\" Lucas said. \"We've been making it since ten o'clock.\" Ana was out of breath. \"I've been mixing the chocolate for twenty minutes!\" she said. Mom laughed. \"And how many eggs have you broken?\" \"We've broken six,\" Lucas said. The cake wasn't perfect, but Grandpa loved it. Since then, the kids have been asking Mom for more baking lessons.", "au": "y4beefd45da", "img": "u:photo-1605433246995-23f532d1e001", "q": [{"s": "Lucas and Ana have been baking a cake.", "a": "yes"}, {"s": "They started baking at noon.", "a": "no"}, {"s": "Ana has been mixing the chocolate for twenty minutes.", "a": "yes"}, {"s": "Grandpa didn't like the cake.", "a": "no"}]}, "keyq": [{"q": "Have you been learning English for a long time?", "es": "¿Llevas mucho tiempo aprendiendo inglés?", "a": "Yes, I have. I've been learning it for three years.", "qau": "y4ddc91ec2b", "aau": "y4ae20acbd7"}, {"q": "Have you been playing any sports lately?", "es": "¿Has estado practicando algún deporte últimamente?", "a": "Yes, I have. I've been playing basketball after school.", "qau": "y4f11d34a2f", "aau": "y483c9a1a5c"}, {"q": "Has it been raining a lot where you live?", "es": "¿Ha estado lloviendo mucho donde vives?", "a": "No, it hasn't. It's been really sunny this week.", "qau": "y40876c3aca", "aau": "y4538848dde"}]}, "t6p2": {"reading": {"title": "The new bike", "text": "Last Saturday, Emma finally bought a red bike. She had been saving up her allowance for eight months. Her old bike had belonged to her cousin, and it was too small for her. \"I had been dreaming about this bike since my birthday,\" she says. On the first day, Emma rode to the park with her dad. They had been riding for twenty minutes when it started to rain. They were wet and exhausted when they got home, but Emma was very happy. \"I believed I would never have enough money,\" she says. \"Now I own my first bike, and I know that saving really helps.\"", "au": "y4bd64cd3b0", "img": "u:photo-1667316467861-b325d5332b30", "q": [{"s": "Emma had been saving up for eight months.", "a": "yes"}, {"s": "Her old bike had belonged to her brother.", "a": "no"}, {"s": "It started to rain after twenty minutes.", "a": "yes"}, {"s": "Emma rode to the park with her mom.", "a": "no"}]}, "keyq": [{"q": "Had you been playing outside before dinner yesterday?", "es": "¿Habías estado jugando afuera antes de la cena ayer?", "a": "Yes, I had. I had been playing tag with my friends.", "qau": "y4699fa6766", "aau": "y46cbb336e5"}, {"q": "Have you known your best friend for a long time?", "es": "¿Conoces a tu mejor amigo desde hace mucho tiempo?", "a": "Yes, I have. I've known him since kindergarten.", "qau": "y4873968165", "aau": "y496d335211"}, {"q": "Were you tired after school yesterday?", "es": "¿Estabas cansado después del colegio ayer?", "a": "Yes, I was. I had been running in gym class all morning.", "qau": "y4146701d64", "aau": "y495fc891b2"}]}, "t7p1": {"reading": {"title": "The best neighbor", "text": "Tomás lives in a neighborhood where there are lots of trees and a big park. His favorite neighbor is Rosa, an old woman who lives next door. She has a garden which is full of tomatoes and sunflowers. Rosa is the neighbor whose cat, Bigotes, always sleeps on Tomás's bike. Tomás remembers the day when he met her. His ball was stuck in a tall tree, and he was very sad. Rosa brought a ladder that was really long and helped him get it. \"That's the reason why we're friends,\" Tomás says. \"Rosa is someone who always helps.\"", "au": "y4c646bb678", "img": "u:photo-1764451651977-b92ffc1773f9", "q": [{"s": "Rosa has a garden which is full of sunflowers.", "a": "yes"}, {"s": "Bigotes is a dog that sleeps on the bike.", "a": "no"}, {"s": "Tomás met Rosa on the day when his ball got stuck.", "a": "yes"}, {"s": "Tomás lives in a neighborhood where there are no trees.", "a": "no"}]}, "keyq": [{"q": "Do you have a friend who loves animals?", "es": "¿Tienes un amigo que ame los animales?", "a": "Yes, I do. My friend Sara is a girl who has three cats.", "qau": "y4913715546", "aau": "y49de36f713"}, {"q": "Is there a park where you like to play?", "es": "¿Hay un parque donde te guste jugar?", "a": "Yes, there is. It's the park where I ride my bike.", "qau": "y48b561005a", "aau": "y41714ade12"}, {"q": "Do you remember the day when you lost your first tooth?", "es": "¿Recuerdas el día en que se te cayó tu primer diente?", "a": "Yes, I do. It was the day when we went to the beach.", "qau": "y49690c9f34", "aau": "y47e1bb42ea"}]}, "t7p2": {"reading": {"title": "Our class trip to the zoo", "text": "Last Friday, our class went to the city zoo, which is the biggest in the country. Our teacher, Mrs. López, who loves animals, planned the whole trip. First, we saw twenty monkeys, most of whom were eating bananas. Then it started to rain, which made the penguins very happy! The guide, whose name was Pedro, showed us the place in which the baby elephants sleep. My best friend, who is afraid of snakes, closed his eyes in the reptile house. The friends I went with all agreed: it was the best day of the year.", "au": "y4e33c3493f", "img": "u:photo-1503918756811-975bd3397178", "q": [{"s": "Most of the monkeys were eating bananas.", "a": "yes"}, {"s": "The guide's name was Pablo.", "a": "no"}, {"s": "It started to rain at the zoo.", "a": "yes"}, {"s": "Mrs. López is afraid of snakes.", "a": "no"}]}, "keyq": [{"q": "Are the friends you play with in your class?", "es": "¿Los amigos con los que juegas están en tu clase?", "a": "Yes, they are. The friends I play with sit near me.", "qau": "y40af42ddb0", "aau": "y452ed57bc3"}, {"q": "Is the city in which you live big?", "es": "¿Es grande la ciudad en la que vives?", "a": "Yes, it is. My city, which has a big river, is very busy.", "qau": "y4410056778", "aau": "y47d04e4999"}, {"q": "Do you have an older brother or sister?", "es": "¿Tienes un hermano o una hermana mayor?", "a": "Yes, I do. My sister, who is fourteen, loves dancing.", "qau": "y4962e1c528", "aau": "y4b26459eb8"}]}, "t8p1": {"reading": {"title": "Little questions at camp", "text": "On the first day of summer camp, Mia didn't know anyone. She was quiet until a girl named Zoe sat next to her. \"It's really hot today, isn't it?\" Zoe said. Mia smiled. \"Yes, it is! You're in the blue group, aren't you?\" \"I am! You like swimming, don't you?\" Zoe asked. The two girls talked all afternoon. At dinner, a boy said, \"We can't go to the lake tomorrow, can we?\" \"Yes, we can,\" said the counselor. \"But you'll wear your life jackets, won't you?\" By the end of the week, Mia and Zoe were best friends. Little questions like these help people start great conversations.", "au": "y4db9ab5984", "img": "u:photo-1533222481259-ce20eda1e20b", "q": [{"s": "Mia knew many kids on the first day.", "a": "no"}, {"s": "Zoe is in the blue group.", "a": "yes"}, {"s": "The kids can go to the lake the next day.", "a": "yes"}, {"s": "Mia and Zoe argued all afternoon.", "a": "no"}]}, "keyq": [{"q": "Are you cold? It's freezing today, isn't it?", "es": "¿Tienes frío? Hace un frío terrible hoy, ¿verdad?", "a": "Yes, it is. I'm wearing two sweaters!", "qau": "y415343d473", "aau": "y4ddffbf7dd"}, {"q": "Do you have a pet? You like animals, don't you?", "es": "¿Tienes una mascota? Te gustan los animales, ¿no?", "a": "Yes, I do. I have a dog named Max.", "qau": "y4178ececc7", "aau": "y4f431bae98"}, {"q": "Did you watch the game? Your team didn't win, did it?", "es": "¿Viste el partido? Tu equipo no ganó, ¿verdad?", "a": "No, it didn't. We lost two to one.", "qau": "y44524c6d20", "aau": "y4354c94c04"}]}, "t8p2": {"reading": {"title": "Up or down?", "text": "Our English teacher, Mr. Ríos, played a fun game with us. \"Listen to my voice, will you?\" he said. Then he said, \"You did your homework, didn't you?\" with his voice going down. \"Going down means I'm sure,\" he explained. Next, he said it with his voice going up. \"Going up means I really don't know.\" Everyone laughed. Then he taught us some special tags: \"I'm the teacher, aren't I?\" \"Let's play a game, shall we?\" \"Nobody is tired, are they?\" At the end, Lucía said, \"Nothing was difficult, was it?\" Mr. Ríos smiled. \"You're learning fast, aren't you?\"", "au": "y41aeeaa6d7", "img": "u:photo-1761208662734-fb46f1398551", "q": [{"s": "A voice going down means the teacher is sure.", "a": "yes"}, {"s": "Mr. Ríos is a math teacher.", "a": "no"}, {"s": "Lucía said, 'Nothing was difficult, was it?'", "a": "yes"}, {"s": "Nobody laughed during the game.", "a": "no"}]}, "keyq": [{"q": "Are we playing outside? Let's take the ball, shall we?", "es": "¿Vamos a jugar afuera? Llevemos el balón, ¿sí?", "a": "Yes, we are. Pass me the ball, will you?", "qau": "y4fe6c652c8", "aau": "y4439159faa"}, {"q": "Do you have a pet? You've never had a snake, have you?", "es": "¿Tienes una mascota? Nunca has tenido una serpiente, ¿verdad?", "a": "No, I haven't. I have a cat and a fish.", "qau": "y43919e43d3", "aau": "y4fc8d1da0a"}, {"q": "Is everyone ready? Nobody forgot their lunch, did they?", "es": "¿Están todos listos? Nadie olvidó su almuerzo, ¿verdad?", "a": "No, they didn't. Everyone has their lunch.", "qau": "y4e69475f9c", "aau": "y46a2b4baca"}]}, "t9p1": {"reading": {"title": "The lost message", "text": "On Monday, our teacher, Mrs. Díaz, told Leo, \"We're going to the museum on Thursday. Bring a snack.\" Leo told his friend Sam that the class was going to the museum, but he said it was \"next Thursday.\" Sam told everyone in the group. On Thursday morning, nobody had a snack! Mrs. Díaz was surprised. She said she had told Leo about the trip on Monday. Leo said he was very sorry. He told her he would listen more carefully the next time. That afternoon, Mrs. Díaz told the class that messages had to be passed on word for word. Now Leo writes everything down.", "au": "y473a213b9c", "img": "u:photo-1706059923464-ea7a202e2643", "q": [{"s": "Mrs. Díaz told Leo about the trip on Monday.", "a": "yes"}, {"s": "Sam told Leo about the museum first.", "a": "no"}, {"s": "Everyone brought a snack on Thursday.", "a": "no"}, {"s": "Leo said he would listen more carefully.", "a": "yes"}]}, "keyq": [{"q": "Did your teacher say the test would be easy?", "es": "¿Tu profesora dijo que el examen sería fácil?", "a": "Yes, she did. She said it would be short and easy.", "qau": "y4ea2ef9f2e", "aau": "y47b20638bd"}, {"q": "Did your friend tell you a secret yesterday?", "es": "¿Tu amigo te contó un secreto ayer?", "a": "Yes, he did. He told me he was getting a puppy.", "qau": "y448c723dcf", "aau": "y4bc54c22cd"}, {"q": "Did your mom say you could play video games today?", "es": "¿Tu mamá dijo que podías jugar videojuegos hoy?", "a": "No, she didn't. She said I had to finish my homework first.", "qau": "y49c7aa857d", "aau": "y48bcd6dc9f"}]}, "t9p2": {"reading": {"title": "Who broke the vase?", "text": "Last Sunday, Grandma's blue vase fell off the table and broke. Mom asked who did it. My little brother Pablo denied touching it. Our dog Rocky just looked at us. Then my sister Ana admitted playing with a ball in the living room. She apologized for breaking the vase and promised to be more careful. Mom refused to stay angry for long. She advised us to play outside next time and warned us not to throw balls inside the house. Dad offered to glue the vase. In the end, Ana suggested making Grandma a new one in art class. Grandma loved it!", "au": "y44921f4c16", "img": "u:photo-1621846323386-a60faf26f962", "q": [{"s": "Pablo denied touching the vase.", "a": "yes"}, {"s": "Ana refused to apologize.", "a": "no"}, {"s": "Dad offered to glue the vase.", "a": "yes"}, {"s": "Mom suggested making a new vase.", "a": "no"}]}, "keyq": [{"q": "Has your mom ever advised you to eat more vegetables?", "es": "¿Tu mamá alguna vez te ha aconsejado comer más verduras?", "a": "Yes, she has. She advised me to eat a salad every day.", "qau": "y4605665786", "aau": "y4fff083290"}, {"q": "Did you promise to clean your room this week?", "es": "¿Prometiste ordenar tu cuarto esta semana?", "a": "Yes, I did. I promised to clean it on Saturday.", "qau": "y499d7032f1", "aau": "y4796130b88"}, {"q": "Have you ever offered to help a classmate?", "es": "¿Alguna vez te has ofrecido a ayudar a un compañero?", "a": "Yes, I have. I offered to help my friend with math.", "qau": "y465adbc5a1", "aau": "y41ca708403"}]}, "t10p1": {"reading": {"title": "Polite questions at the aquarium", "text": "Last weekend, Sofía visited the aquarium with her family. She had a lot of questions,. At the entrance, Sofía asked a guide, \"Could you tell me where the sharks are?\" The guide smiled and showed her the way. Then she asked, \"Do you know what time the dolphin show starts?\" It started at eleven. Later, Sofía was hungry. \"I was wondering if there was a place to eat here,\" she said. The guide said there was a restaurant upstairs. At the gift shop, she asked, \"Do you happen to know how much this penguin toy costs?\" Polite questions get friendly answers!", "au": "y465bbb81e8", "img": "u:photo-1663579170421-d6481b9afa89", "q": [{"s": "Sofía asked where the sharks were.", "a": "yes"}, {"s": "The dolphin show started at ten.", "a": "no"}, {"s": "The restaurant was downstairs.", "a": "no"}, {"s": "Sofía asked about the price of a penguin toy.", "a": "yes"}]}, "keyq": [{"q": "Do you know what time your school starts?", "es": "¿Sabes a qué hora empieza tu colegio?", "a": "Yes, I do. It starts at seven o'clock.", "qau": "y4756092441", "aau": "y4dfc99f93b"}, {"q": "Could you tell me what your favorite animal is?", "es": "¿Podrías decirme cuál es tu animal favorito?", "a": "Yes, I can. My favorite animal is the panda.", "qau": "y465ebf8f73", "aau": "y49bd4fcacd"}, {"q": "Do you happen to know where the nearest park is?", "es": "¿Por casualidad sabes dónde queda el parque más cercano?", "a": "Yes, I do. It's two blocks from my house.", "qau": "y44248af51a", "aau": "y4bc1ad5924"}]}, "t10p2": {"reading": {"title": "The art club", "text": "Yesterday, Luna went to her first art club class. At the door, the teacher asked her what her name was and how old she was. Then she wanted to know if Luna had any brushes. Luna said she didn't. The teacher asked whether she liked painting animals or flowers. \"Animals!\" Luna said. Later, a boy asked her where she lived and if she wanted to paint with him. At home, her mom asked her what she had learned. Luna said she had painted a big orange tiger. Now she isn't sure whether to join the dance club too.", "au": "y489feef5a8", "img": "u:photo-1698340311456-77454d0abdc7", "q": [{"s": "The teacher asked Luna how old she was.", "a": "yes"}, {"s": "Luna had her own brushes.", "a": "no"}, {"s": "A boy asked her if she wanted to paint with him.", "a": "yes"}, {"s": "Luna painted a flower.", "a": "no"}]}, "keyq": [{"q": "Did your teacher ask you if you had finished your homework?", "es": "¿Tu profesora te preguntó si habías terminado tu tarea?", "a": "Yes, she did. She asked me if I needed help too.", "qau": "y42b69adc34", "aau": "y4fef3dacd6"}, {"q": "Did your friend ask you whether you wanted to play?", "es": "¿Tu amigo te preguntó si querías jugar?", "a": "Yes, he did. He asked me if I could play after school.", "qau": "y4e150faa2a", "aau": "y4c0009834f"}, {"q": "Do you know whether to join a sports club or an art club?", "es": "¿Sabes si unirte a un club de deportes o a uno de arte?", "a": "No, I don't. I'm not sure whether to choose soccer or painting.", "qau": "y4207ff73db", "aau": "y4a5c03d9f6"}]}, "t11p1": {"reading": {"title": "A new playground", "text": "Our school playground is very special. It was built fifty years ago, and last year it was used by more than five hundred kids. This month, it is being repaired. The old swings have been removed, and new ones will be installed next week. A big slide was designed by the art students, and their drawings were sent to a builder. Before the repairs started, the trees had been checked by a park expert. When the playground is finished, it will be opened with a party. Balloons will be given to every student. Food can be brought from home, but it must be eaten at the tables.", "au": "y482932a47b", "img": "u:photo-1766104959444-f23e3a2f3f9c", "q": [{"s": "The playground was built fifty years ago.", "a": "yes"}, {"s": "The big slide was designed by the teachers.", "a": "no"}, {"s": "New swings will be installed next week.", "a": "yes"}, {"s": "Food can be eaten anywhere on the playground.", "a": "no"}]}, "keyq": [{"q": "Was your school built a long time ago?", "es": "¿Tu colegio fue construido hace mucho tiempo?", "a": "Yes, it was. It was built about forty years ago.", "qau": "y4e65da6ebc", "aau": "y4f080c9c06"}, {"q": "Is English spoken at your house?", "es": "¿Se habla inglés en tu casa?", "a": "No, it isn't. Spanish is spoken at my house.", "qau": "y4afe0cb94f", "aau": "y4a9d0a2e6a"}, {"q": "Has your classroom ever been painted?", "es": "¿Alguna vez han pintado tu salón de clase?", "a": "Yes, it has. It was painted last year.", "qau": "y45f42428a2", "aau": "y4b6de974fb"}]}, "t11p2": {"reading": {"title": "From the tree to your chocolate", "text": "Chocolate is said to be one of the most popular sweets in the world. But how is it made? First, the cocoa pods are picked from tall trees. Then, the pods are opened and the beans are taken out. After that, the beans are dried in the sun for about a week. Next, they are sent to a factory, where they are roasted. Finally, sugar and milk are added, and the chocolate is poured into molds. It is believed that the first chocolate drink was made more than three thousand years ago. Today, millions of chocolates are eaten every day!", "au": "y4714eac24f", "img": "u:photo-1743252878695-367d69dc87a8", "q": [{"s": "The cocoa pods are picked from trees.", "a": "yes"}, {"s": "The beans are dried in a factory.", "a": "no"}, {"s": "Sugar and milk are added at the end.", "a": "yes"}, {"s": "Chocolate is believed to be a new invention.", "a": "no"}]}, "keyq": [{"q": "Is it said that your town has a haunted house?", "es": "¿Se dice que en tu pueblo hay una casa embrujada?", "a": "Yes, it is. It is said that an old house near the park is haunted.", "qau": "y48a3cfb53e", "aau": "y4f2a4c519e"}, {"q": "Are apples grown in your country?", "es": "¿Se cultivan manzanas en tu país?", "a": "Yes, they are. They are grown in the mountains.", "qau": "y4e98ce87b4", "aau": "y417248d6aa"}, {"q": "Is it expected to rain this weekend?", "es": "¿Se espera que llueva este fin de semana?", "a": "No, it isn't. It is expected to be sunny.", "qau": "y4215544200", "aau": "y41bb78a8a4"}]}, "t12p1": {"reading": {"title": "Sofia's errand day", "text": "Last Saturday was a busy day for Sofia's family. In the morning, Sofia had her hair cut at a small salon near the park. Her brother Leo had his bike repaired because the chain was broken. Then the whole family went to the dentist and had their teeth checked. At home, Dad wanted to paint the fence himself, but he was too tired, so they will have it painted next week. In the evening, nobody wanted to cook, so they had pizza delivered. \"Having things done is easy,\" said Leo, \"but next time I want to fix my bike myself!\"", "au": "y4c8818bbbc", "img": "u:photo-1606066889831-35faf6fa6ff6", "q": [{"s": "Sofia had her hair cut in the morning.", "a": "yes"}, {"s": "Leo repaired his bike himself.", "a": "no"}, {"s": "The family had their teeth checked.", "a": "yes"}, {"s": "Dad painted the fence on Saturday.", "a": "no"}]}, "keyq": [{"q": "Do you have your hair cut at a salon?", "es": "¿Te cortan el pelo en una peluquería?", "a": "Yes, I do. I have it cut near my house.", "qau": "y4289f29aee", "aau": "y4d826b4874"}, {"q": "Did you have your teeth checked this year?", "es": "¿Te revisaron los dientes este año?", "a": "Yes, I did. I had them checked in March.", "qau": "y4478ffe1e9", "aau": "y4cb2580a0f"}, {"q": "Have you ever had your face painted?", "es": "¿Alguna vez te han pintado la cara?", "a": "Yes, I have. I had it painted at a birthday party.", "qau": "y4dea1805bc", "aau": "y440425da82"}]}, "t12p2": {"reading": {"title": "The best bad day", "text": "Last Friday, Tomás went on a school trip to the zoo, but nothing went right. First, he had his backpack searched at the entrance because it was too big. Then, a monkey grabbed his cap, so he had his cap taken by a monkey! At lunch, he had his sandwich eaten by a goat. When he got home, he found a crack in his glasses, so he needs to get them fixed this week. But Tomás got his best friend to share his snacks, and he had his teacher take a funny photo of him with the goat. \"It was the best bad day ever,\" he said.", "au": "y45752dabe1", "img": "u:photo-1507184915978-447ac6ab3ecb", "q": [{"s": "Tomás had his backpack searched.", "a": "yes"}, {"s": "A monkey ate his sandwich.", "a": "no"}, {"s": "He needs to get his glasses fixed.", "a": "yes"}, {"s": "His teacher shared her snacks with him.", "a": "no"}]}, "keyq": [{"q": "Have you ever had a toy taken away by a teacher?", "es": "¿Alguna vez una profesora te ha quitado un juguete?", "a": "Yes, I have. I had a yo-yo taken away in class.", "qau": "y4f548f49d5", "aau": "y43469492e6"}, {"q": "Do you need to get anything fixed this week?", "es": "¿Necesitas mandar a arreglar algo esta semana?", "a": "Yes, I do. I need to get my bike fixed.", "qau": "y44788c0649", "aau": "y473083bee4"}, {"q": "Do you get your brother or sister to help you with homework?", "es": "¿Consigues que tu hermano o hermana te ayude con la tarea?", "a": "Yes, I do. I get my sister to help me with math.", "qau": "y47b98121c6", "aau": "y4fe3436726"}]}, "t13p1": {"reading": {"title": "Tomorrow at summer camp", "text": "Tomorrow will be Lucas's first day at summer camp. At seven in the morning, he will be eating breakfast with his new friends. At nine, he will be swimming in the lake, and at eleven, he will be building a small boat with the camp leaders. In the afternoon, he won't be playing video games, because there are no screens at camp! Instead, he will be climbing trees and looking for frogs. At eight in the evening, everyone will be singing songs around the campfire. And at ten, Lucas will be sleeping in a tent under the stars.", "au": "y4e5c2260d2", "img": "u:photo-1606092195730-5d7b9af1efc5", "q": [{"s": "Lucas will be swimming at nine.", "a": "yes"}, {"s": "He will be playing video games in the afternoon.", "a": "no"}, {"s": "Everyone will be singing at eight in the evening.", "a": "yes"}, {"s": "Lucas will be sleeping in a cabin.", "a": "no"}]}, "keyq": [{"q": "Will you be sleeping at ten tonight?", "es": "¿Estarás durmiendo a las diez esta noche?", "a": "Yes, I will. I'll be sleeping in my bed.", "qau": "y48a368ce33", "aau": "y484a73c9b2"}, {"q": "Will you be playing outside this time tomorrow?", "es": "¿Estarás jugando afuera mañana a esta hora?", "a": "No, I won't. I'll be doing my homework.", "qau": "y4b4036cc54", "aau": "y460b4adbfe"}, {"q": "Will you be visiting your grandparents this weekend?", "es": "¿Vas a visitar a tus abuelos este fin de semana?", "a": "Yes, I will. I'll be having lunch with them on Sunday.", "qau": "y4ad0dad941", "aau": "y4792536173"}]}, "t13p2": {"reading": {"title": "The big science fair", "text": "The school science fair is on Friday, and Mia has a plan. By Monday night, she will have collected all the leaves for her project. By Tuesday, she will have glued the photos on her poster. By Wednesday, her dad will have helped her build a small model of a tree. By Thursday, she will have practiced her speech three times. Her teacher says the due date is Friday at eight. \"By the time the fair starts, I'll have finished everything,\" Mia says. Her little brother isn't so sure. \"By then, you'll have lost the glue!\" he laughs.", "au": "y45151cab34", "img": "u:photo-1758685734030-a31d96462eec", "q": [{"s": "Mia will have collected the leaves by Monday night.", "a": "yes"}, {"s": "Her mom will help her build a model.", "a": "no"}, {"s": "The due date is Friday at eight.", "a": "yes"}, {"s": "Mia will have practiced her speech five times.", "a": "no"}]}, "keyq": [{"q": "Will you have finished your homework by dinner time?", "es": "¿Habrás terminado tu tarea para la hora de la cena?", "a": "Yes, I will. I'll have finished it by six.", "qau": "y45cc6ee070", "aau": "y42cc12f012"}, {"q": "Will you have learned to swim by next summer?", "es": "¿Habrás aprendido a nadar para el próximo verano?", "a": "No, I won't. But I'll have taken some lessons.", "qau": "y449e4ff708", "aau": "y4bd8f4d338"}, {"q": "Will you have read a whole book by the end of the month?", "es": "¿Habrás leído un libro completo para fin de mes?", "a": "Yes, I will. I'll have read two books by then.", "qau": "y48e04eece3", "aau": "y4dd97f8207"}]}, "t14p1": {"reading": {"title": "A party for Max", "text": "Next Saturday, Max the dog will have been living with the Gómez family for five years. The children want to give him a party. By Saturday, they will have been planning it for two weeks. Sara, who is ten, is going to make a special cake for dogs. By the day of the party, she will have been practicing the recipe for days. Her brother Pablo will have been teaching Max a new trick for a month. \"At the end of the party, Max will be very tired,\" says Pablo. \"He will have been running and playing all afternoon!\"", "au": "y401ce05034", "img": "u:photo-1616095818012-c386cf5a4c0e", "q": [{"s": "By Saturday, Max will have been living with the family for five years.", "a": "yes"}, {"s": "The children will have been planning the party for a month.", "a": "no"}, {"s": "Pablo will have been teaching Max a trick for a month.", "a": "yes"}, {"s": "Max will be full of energy at the end of the party.", "a": "no"}]}, "keyq": [{"q": "Will you have been studying English for a year by December?", "es": "¿Llevarás un año estudiando inglés en diciembre?", "a": "Yes, I will. I'll have been studying it for a year and a half.", "qau": "y48f5317bc0", "aau": "y48a91163ef"}, {"q": "Will you have been living in your house for five years by next year?", "es": "¿Llevarás cinco años viviendo en tu casa el próximo año?", "a": "No, I won't. I'll have been living there for two years.", "qau": "y48ca5d1a03", "aau": "y49479fbded"}, {"q": "Will you be tired tonight because you'll have been playing all day?", "es": "¿Estarás cansado esta noche porque habrás estado jugando todo el día?", "a": "Yes, I will. I'll have been running at the park all afternoon.", "qau": "y4ccedeb832", "aau": "y42bd9f6ad8"}]}, "t14p2": {"reading": {"title": "Two ways to count", "text": "Emma is in a reading challenge at her school library. By the end of the school year, she will have read thirty books! That is a number you can count, so we say \"will have read.\" But Emma started in September, so by June she will have been reading every night for nine months. That is a long time, so we say \"will have been reading.\" Her friend Leo is collecting bottle caps for a school art project. By Friday, he will have collected one thousand caps, and he will have been collecting them for six weeks.", "au": "y470956defa", "img": "u:photo-1516042438821-0abd7a73c4b3", "q": [{"s": "Emma will have read thirty books.", "a": "yes"}, {"s": "Emma started the challenge in January.", "a": "no"}, {"s": "Leo will have collected five hundred caps.", "a": "no"}, {"s": "Leo will have been collecting caps for six weeks.", "a": "yes"}]}, "keyq": [{"q": "Will you have read ten books by the end of the year?", "es": "¿Habrás leído diez libros para fin de año?", "a": "Yes, I will. I'll have read about twelve books.", "qau": "y451facbd9e", "aau": "y4530747a4d"}, {"q": "Will you have been playing a sport for three years by next year?", "es": "¿Llevarás tres años practicando un deporte el próximo año?", "a": "Yes, I will. I'll have been playing soccer for four years.", "qau": "y45909aefaa", "aau": "y47e29499c1"}, {"q": "Will you have known your best friend for five years by next year?", "es": "¿Llevarás cinco años de conocer a tu mejor amigo el próximo año?", "a": "No, I won't. I'll have known her for three years.", "qau": "y4ea2d1985c", "aau": "y4d954c715c"}]}, "t15p1": {"reading": {"title": "Robot Helpers in Class", "text": "Mia's class had a debate about AI homework helpers. Leo said, \"There is a strong case for AI. It explains math in a fun way.\" Mia did not agree. \"While it is true that AI saves time, it can also do our thinking for us,\" she said. Admittedly, Leo's point was good. Even so, many kids said they wanted to think for themselves. Their teacher, Mrs. Diaz, asked everyone to conclude. On balance, the class decided that AI is a good learning tool, but only with a teacher's help. Despite the risks, they want to try it next month.", "au": "y47733a4a0e", "img": "u:photo-1577896851231-70ef18881754", "q": [{"s": "Leo thinks AI explains math in a fun way.", "a": "yes"}, {"s": "Mia agreed with Leo at first.", "a": "no"}, {"s": "The class decided that AI should replace the teacher.", "a": "no"}, {"s": "The class wants to try AI next month.", "a": "yes"}]}, "keyq": [{"q": "Is AI a good learning tool for kids?", "es": "¿La IA es una buena herramienta de aprendizaje para niños?", "a": "Yes, it is. While it is true that it helps, we still need our teacher.", "qau": "y41d0972391", "aau": "y4877d7d7cb"}, {"q": "Would you use an AI homework helper?", "es": "¿Usarías un asistente de tareas con IA?", "a": "No, I wouldn't. Admittedly, it saves time, but I like to think for myself.", "qau": "y4e0bf7adc7", "aau": "y40b957d3c1"}, {"q": "Do the benefits of tablets in class outweigh the risks?", "es": "¿Los beneficios de las tabletas en clase superan los riesgos?", "a": "Yes, they do. On balance, tablets make learning more fun.", "qau": "y4445f46a86", "aau": "y4521bac5a3"}]}, "t16p1": {"reading": {"title": "The Great Uniform Debate", "text": "At Pine Hill School, the fifth graders held a debate about uniforms. Supporters maintain that uniforms are easy. \"You don't have to choose clothes every morning,\" said Tom. Furthermore, everyone looks like one team. Opponents claim that uniforms are boring. \"I want to express myself with colors!\" said Ana. Tom answered, \"That argument overlooks something. You can still wear fun socks and backpacks.\" Ana smiled. \"This is not to say that uniforms are bad, but we need one free-dress day,\" she said. In the end, the principal liked Ana's idea. Now every Friday is free-dress day.", "au": "y45a72635e6", "img": "u:photo-1698993081947-8a3654303904", "q": [{"s": "Tom likes not choosing clothes every morning.", "a": "yes"}, {"s": "Ana wants to wear only gray clothes.", "a": "no"}, {"s": "Tom said you can still wear fun socks.", "a": "yes"}, {"s": "Free-dress day is on Monday.", "a": "no"}]}, "keyq": [{"q": "Do you wear a school uniform?", "es": "¿Usas uniforme escolar?", "a": "Yes, I do. Supporters maintain that it saves time, and I agree.", "qau": "y47ea2c5de8", "aau": "y4ce07eb3cb"}, {"q": "Should kids have a free-dress day every week?", "es": "¿Los niños deberían tener un día sin uniforme cada semana?", "a": "Yes, they should. Furthermore, it lets us express ourselves.", "qau": "y4ec611f832", "aau": "y419a015bbd"}, {"q": "Is a uniform more comfortable than your own clothes?", "es": "¿El uniforme es más cómodo que tu propia ropa?", "a": "No, it isn't. This is not to say that it's bad, but it's less comfortable.", "qau": "y4747284970", "aau": "y4556ce6c5c"}]}, "t17p1": {"reading": {"title": "Too Much Screen Time?", "text": "Sofia loves cartoons and video games, but lately she feels tired at school. Her teacher, Mrs. Lopez, explained that many studies suggest a link between screen time and poor sleep. Bright screens at night may contribute to tiredness. \"Do video games make kids sad?\" asked Sofia. \"It would be simplistic to say that,\" said Mrs. Lopez. \"Games can be fun, and playing with friends can give you a sense of belonging.\" On the one hand, screens are fun. On the other hand, kids tend to sleep better without them at night. Now Sofia turns off her tablet one hour before bed.", "au": "y4a80a99e84", "img": "u:photo-1752652012573-ff1e48dbac88", "q": [{"s": "Sofia feels tired at school lately.", "a": "yes"}, {"s": "Mrs. Lopez said video games definitely make kids sad.", "a": "no"}, {"s": "Playing with friends can give a sense of belonging.", "a": "yes"}, {"s": "Sofia now plays on her tablet until she falls asleep.", "a": "no"}]}, "keyq": [{"q": "Do you sleep better without screens at night?", "es": "¿Duermes mejor sin pantallas por la noche?", "a": "Yes, I do. Screens at night tend to keep me awake.", "qau": "y450dc5150a", "aau": "y4475da7556"}, {"q": "Can video games give kids a sense of belonging?", "es": "¿Los videojuegos pueden dar a los niños un sentido de pertenencia?", "a": "Yes, they can. Playing with friends may help us feel part of a team.", "qau": "y4ec0ef603a", "aau": "y4e44fb7a7a"}, {"q": "Is it simplistic to say that all cartoons are bad for kids?", "es": "¿Es simplista decir que todos los dibujos animados son malos para los niños?", "a": "Yes, it is. Many cartoons can actually help us learn.", "qau": "y4a4c76bbd9", "aau": "y4a6bce4db6"}]}, "t18p1": {"reading": {"title": "Who Picks the Teams?", "text": "In gym class, Mr. Gomez usually chose two team captains. The captains tended to pick the fastest kids first, and some children felt sad. One day, Luna said, \"This is not entirely fair.\" Mr. Gomez asked the class, \"What does fair mean?\" Max said, \"It depends on how we define fairness. Is it equal treatment or equal results?\" To a certain extent, everyone agreed with Luna. Now the class takes turns being captain, and the teacher makes the teams on Fridays. Broadly speaking, most kids are happier, and fewer children feel left out.", "au": "y4bb0e35803", "img": "u:photo-1549995546-87cb41aa98a4", "q": [{"s": "The captains tended to pick the fastest kids first.", "a": "yes"}, {"s": "Luna thought the old system was completely fair.", "a": "no"}, {"s": "Now the class takes turns being captain.", "a": "yes"}, {"s": "Mr. Gomez makes the teams every day.", "a": "no"}]}, "keyq": [{"q": "Is your school fair to everyone?", "es": "¿Tu colegio es justo con todos?", "a": "Yes, it is, to a certain extent. Most teachers treat everyone the same.", "qau": "y420bc45db3", "aau": "y4f539cc8c1"}, {"q": "Should kids take turns being team captain?", "es": "¿Los niños deberían turnarse para ser capitán del equipo?", "a": "Yes, they should. Arguably, it is the fairest way to choose teams.", "qau": "y4466ba6c81", "aau": "y4a71858b21"}, {"q": "Do team captains always pick their friends first?", "es": "¿Los capitanes de equipo siempre escogen primero a sus amigos?", "a": "No, they don't. But they tend to pick their friends quite often.", "qau": "y4b61f4070d", "aau": "y4161936225"}]}, "t19p1": {"reading": {"title": "School at Home or School at School?", "text": "Last year, Pablo had online lessons for two months because his school was being repaired. Whereas his classroom was noisy and fun, his bedroom was quiet. Unlike his teacher at school, the computer couldn't see when he was confused. Pablo learned at his own pace, but he missed his classmates. Conversely, his sister Eva loved online lessons. She is far more organized than Pablo! Now they are both back at school. Their school uses blended learning: they read printed books in class and play learning games on tablets at home. Pablo says, \"The more I talk with my friends, the more I learn.\"", "au": "y4b78404549", "img": "u:photo-1758612898312-708f2ffdcd53", "q": [{"s": "Pablo's bedroom was quiet.", "a": "yes"}, {"s": "Pablo did not miss his classmates.", "a": "no"}, {"s": "Eva loved online lessons.", "a": "yes"}, {"s": "Their school uses only printed books now.", "a": "no"}]}, "keyq": [{"q": "Do you prefer face-to-face classes to online lessons?", "es": "¿Prefieres las clases presenciales a las clases en línea?", "a": "Yes, I do. Unlike online lessons, real classes let me play with my classmates.", "qau": "y424f40cd30", "aau": "y42fba7be81"}, {"q": "Is an e-book as heavy as a printed textbook?", "es": "¿Un libro electrónico es tan pesado como un libro de texto impreso?", "a": "No, it isn't. An e-book is not nearly as heavy as a printed book.", "qau": "y4b68a253db", "aau": "y4297eab368"}, {"q": "Do you learn more when you participate in class?", "es": "¿Aprendes más cuando participas en clase?", "a": "Yes, I do. The more I participate, the more I learn.", "qau": "y490372023f", "aau": "y431eb8519e"}]}, "t20p1": {"reading": {"title": "Our First Class Vote", "text": "Our class had to choose a new class pet: a fish or a hamster. Mrs. Rivera was the moderator. Tomás talked a lot, and Julia tried to speak. \"Please let her finish,\" said Mrs. Rivera. Julia said, \"Fish are easier to take care of.\" Tomás answered, \"I take your point, but hamsters are more fun.\" Then Mrs. Rivera looked at Sam. \"We haven't heard from you yet.\" Sam said, \"If we had a hamster, we might argue about who takes it home.\" Fair enough! In the end, the class voted for a fish named Bubbles.", "au": "y4532b129fc", "img": "u:photo-1592237163215-c97b487faeb5", "q": [{"s": "Mrs. Rivera was the moderator.", "a": "yes"}, {"s": "Julia said hamsters are easier to take care of.", "a": "no"}, {"s": "Sam spoke first.", "a": "no"}, {"s": "The class voted for a fish.", "a": "yes"}]}, "keyq": [{"q": "Do you let your friends finish when they speak?", "es": "¿Dejas terminar a tus amigos cuando hablan?", "a": "Yes, I do. If I interrupted them, they might feel sad.", "qau": "y4d6ed0427c", "aau": "y49ebe5f97f"}, {"q": "Would you like to be a class representative?", "es": "¿Te gustaría ser representante de curso?", "a": "Yes, I would. If I were a representative, I would listen to every voice.", "qau": "y4cf841d40d", "aau": "y4163d924f4"}, {"q": "Can a class vote be unfair?", "es": "¿Una votación en clase puede ser injusta?", "a": "Yes, it can. Granted, it's fast, but some kids don't get to speak.", "qau": "y44fb400f43", "aau": "y43ce3816e7"}]}, "t21p1": {"reading": {"title": "A Trip to Mars?", "text": "Emma loves planets. At the science fair, she made a poster about space exploration. \"Had astronauts not traveled to the Moon, we would know much less about it,\" she explained. Her friend Ben asked, \"Would you like to live on Mars?\" Emma thought about it. \"Were we to live on Mars, we would need special houses and oxygen. And should I ever go there, I would miss my dog!\" Ben laughed. Their teacher, Mr. Park, said that satellite technology also helps us every day. If scientists hadn't built satellites, we wouldn't have good weather forecasts today.", "au": "y43a0639c1e", "img": "u:photo-1529271247619-1f9736e6e8ee", "q": [{"s": "Emma made a poster about space exploration.", "a": "yes"}, {"s": "Emma said Mars has lots of oxygen.", "a": "no"}, {"s": "Emma said she would miss her cat.", "a": "no"}, {"s": "Mr. Park said satellites help us every day.", "a": "yes"}]}, "keyq": [{"q": "Would you like to visit a space station?", "es": "¿Te gustaría visitar una estación espacial?", "a": "Yes, I would. Should I ever go, I'd take lots of photos.", "qau": "y43a262a772", "aau": "y491f718ccc"}, {"q": "Would you live on Mars?", "es": "¿Vivirías en Marte?", "a": "No, I wouldn't. Were I to live there, I'd miss my family.", "qau": "y4a4d8572f4", "aau": "y4a0bfe2d27"}, {"q": "Have you ever seen a rocket launch?", "es": "¿Alguna vez has visto un lanzamiento de cohete?", "a": "No, I haven't. Had I lived near a launch site, I'd have seen one.", "qau": "y437d45f86b", "aau": "y4d70a4a569"}]}}, "teens": {"t1p1": {"reading": {"title": "The concert plan", "text": "My friends and I have tickets for a concert on Saturday, but the plan is complicated. The show starts at eight, and the odds are the subway will be packed. \"Unless we leave by six, we'll be late,\" Maya wrote in our group chat. Leo is always running late, so we made a rule: if he isn't at the station by six, we'll leave without him. My dad offered to drive us. \"If you get stuck in traffic, don't panic,\" he said. \"Text me as soon as you arrive.\" There's one more problem: the weather. If it storms, they might call the concert off.", "au": "y4528c4ea9b", "img": "u:photo-1565035010268-a3816f98589a", "q": [{"s": "The concert starts at eight.", "a": "yes"}, {"s": "Maya's dad will drive them.", "a": "no"}, {"s": "If Leo isn't at the station by six, they'll leave without him.", "a": "yes"}, {"s": "The concert is on Sunday.", "a": "no"}]}, "keyq": [{"q": "Will you study tonight if you have a test tomorrow?", "es": "¿Estudiarás esta noche si tienes un examen mañana?", "a": "Yes, I will. If I have a test, I'll review my notes.", "qau": "y4c61d4a370", "aau": "y4ec3ada958"}, {"q": "Will you text your friends as soon as you get your test results?", "es": "¿Les escribirás a tus amigos tan pronto como recibas tus resultados?", "a": "Yes, I will. I'll text them as soon as I see my grade.", "qau": "y4a0219e108", "aau": "y4004c3203e"}, {"q": "Will you lose your streak unless you practice every day?", "es": "¿Perderás tu racha a menos que practiques todos los días?", "a": "Yes, I will. Unless I practice daily, I'll lose it.", "qau": "y456327010d", "aau": "y4250bfa6c6"}]}, "t1p2": {"reading": {"title": "Negotiating a night out", "text": "Last week I asked my parents if I could go to a concert in the city. At first they said no, but I didn't give up. I made a counteroffer: \"I'll come home by eleven, as long as I can take the late train.\" My mom said the late train was a deal-breaker. \"You can go provided that Dad picks you up at ten thirty,\" she answered. It wasn't perfect, but we met halfway. I promised to charge my phone in case they needed to call me. My dad agreed on one condition: I have to clean the garage on Sunday. Honestly, it was a fair deal.", "au": "y4c64a338af", "img": "u:photo-1770564512631-7dda81ac68a7", "q": [{"s": "The narrator wanted to go to a concert.", "a": "yes"}, {"s": "Mom accepted the late train idea.", "a": "no"}, {"s": "Dad will pick the narrator up at ten thirty.", "a": "yes"}, {"s": "The narrator has to wash the car on Sunday.", "a": "no"}]}, "keyq": [{"q": "Do your parents let you go out as long as you text them?", "es": "¿Tus papás te dejan salir siempre y cuando les escribas?", "a": "Yes, they do. I can go out as long as I text them.", "qau": "y4b075a6e34", "aau": "y4e49669441"}, {"q": "Do you carry a charger in case your phone dies?", "es": "¿Llevas un cargador por si se te descarga el teléfono?", "a": "Yes, I do. I carry one in case my battery runs out.", "qau": "y4c7e735f9e", "aau": "y4cf780b77c"}, {"q": "Will you lend a friend your headphones provided that he returns them tomorrow?", "es": "¿Le prestarás tus audífonos a un amigo siempre que te los devuelva mañana?", "a": "Yes, I will, provided that he takes care of them.", "qau": "y433a56a8f1", "aau": "y4adcc7e5f5"}]}, "t2p1": {"reading": {"title": "If you had a year off", "text": "Our school podcast recently asked students one simple question: \"What would you do if you had a whole year off?\" Hundreds of students answered, and the results were surprising. Very few said they would play video games all day. Most said they would travel the world or learn something new. Ana, a ninth grader, wrote, \"If I had a free year, I'd learn to make music and record an album.\" Diego said he would volunteer at an animal shelter. \"If I were the principal, I'd start school at ten,\" another student joked. If your answer were very different from your life now, it might be time for some small changes.", "au": "y4d93e4b54f", "img": "u:photo-1559523161-0fc0d8b38a7a", "q": [{"s": "Most students would play video games all day.", "a": "no"}, {"s": "Ana would like to make music.", "a": "yes"}, {"s": "Diego would volunteer at an animal shelter.", "a": "yes"}, {"s": "The principal answered the question.", "a": "no"}]}, "keyq": [{"q": "Would you move abroad if you had the chance?", "es": "¿Te mudarías al extranjero si tuvieras la oportunidad?", "a": "Yes, I would. If I moved abroad, I'd live in Japan.", "qau": "y4a03a64975", "aau": "y4c380cde87"}, {"q": "Would you give up your phone for a month if your parents asked you?", "es": "¿Dejarías tu teléfono por un mes si tus papás te lo pidieran?", "a": "Yes, I would. If I didn't have my phone, I'd read more.", "qau": "y44a22f674a", "aau": "y4cd7f88895"}, {"q": "Would you change the school schedule if you were the principal?", "es": "¿Cambiarías el horario escolar si fueras el rector?", "a": "Yes, I would. If I were the principal, school would start later.", "qau": "y4fbf519e79", "aau": "y4991dd2880"}]}, "t2p2": {"reading": {"title": "Dear Dana: should I change teams?", "text": "Dear Dana, I'm 15 and I've played on my school's soccer team for three years. Last week a club in another city invited me to join their team. The problem is that I'd have to train four nights a week, and my best friends are on my school team. What would you do if you were me? — Torn in Texas. Dear Torn, this is a tough call. If I were in your shoes, I wouldn't decide alone. Talk to your parents and weigh the pros and cons together. Would you still want to go if your friends joined too? If the answer is yes, it's about growth, and that's a good sign. If it's no, I'd think twice. — Dana", "au": "y473dc118ef", "img": "u:photo-1610736342165-4eeb4aef66ca", "q": [{"s": "Torn has played soccer for three years.", "a": "yes"}, {"s": "The club is in the same city.", "a": "no"}, {"s": "Dana thinks Torn should decide alone.", "a": "no"}, {"s": "Dana suggests talking to his parents.", "a": "yes"}]}, "keyq": [{"q": "Would you tell your best friend the truth about a bad haircut?", "es": "¿Le dirías la verdad a tu mejor amigo sobre un mal corte de pelo?", "a": "Yes, I would, but I'd say it kindly.", "qau": "y41439c8bc9", "aau": "y451abf368d"}, {"q": "Would you lie to protect a friend?", "es": "¿Mentirías para proteger a un amigo?", "a": "No, I wouldn't. If I were him, I'd tell the truth.", "qau": "y4b260bba20", "aau": "y497768ea51"}, {"q": "Would you join a new club if none of your friends were in it?", "es": "¿Te unirías a un club nuevo si ninguno de tus amigos estuviera en él?", "a": "Yes, I would. I'd make new friends there.", "qau": "y4cd8f36d92", "aau": "y4fe9daed27"}]}, "t3p1": {"reading": {"title": "The trip I almost missed", "text": "Last spring my class went on a trip to Washington, D.C. The night before, I stayed up late finishing a history project, and I forgot to set my alarm. If I hadn't stayed up so late, I wouldn't have overslept. I woke up at 6:15, and the bus left at 6:30. My mom drove me to school, but the bus was gone. If only I had packed my bag the night before! Luckily, my teacher called. \"We'll wait for you at the gas station,\" she said. It was a close call. In hindsight, it's a funny story. If I had arrived on time, nobody would have remembered me.", "au": "y45bc9bfcd9", "img": "u:photo-1764083029045-4c45c365b710", "q": [{"s": "The trip was to Washington, D.C.", "a": "yes"}, {"s": "The bus left at 6:15.", "a": "no"}, {"s": "The narrator's dad drove to the school.", "a": "no"}, {"s": "The teacher waited at a gas station.", "a": "yes"}]}, "keyq": [{"q": "Would you have passed your last test if you had studied more?", "es": "¿Habrías aprobado tu último examen si hubieras estudiado más?", "a": "Yes, I would have. I would have gotten an A.", "qau": "y445c228f74", "aau": "y44c88d0289"}, {"q": "Would you have chosen a different school if you had had the choice?", "es": "¿Habrías escogido otro colegio si hubieras podido elegir?", "a": "No, I wouldn't have. I would have stayed with my friends.", "qau": "y41a8b1b392", "aau": "y43a50ae9a2"}, {"q": "Would you have joined a club last year if you had known about it?", "es": "¿Te habrías unido a un club el año pasado si lo hubieras conocido?", "a": "Yes, I would have. I would have joined the robotics club.", "qau": "y4edfeeba57", "aau": "y42a81c9c4b"}]}, "t3p2": {"reading": {"title": "What our failed channel taught us", "text": "Last year my friends and I started a gaming channel. We thought we'd be popular in a month. We were wrong. We should have planned our videos, but we just recorded whatever we wanted. We also shouldn't have posted at random times. After three months, we had only twelve subscribers. \"If we had studied what people like, we would have more viewers now,\" my friend Kai said. Honestly, it was a wake-up call. We also learned the hard way that we shouldn't have copied other creators. If we weren't so stubborn, we would have asked for advice sooner. Now we plan every video. If we hadn't failed, we wouldn't be this organized today.", "au": "y466a3a7914", "img": "u:photo-1612130536441-95ece5dcbb86", "q": [{"s": "The friends planned their videos at first.", "a": "no"}, {"s": "They had twelve subscribers after three months.", "a": "yes"}, {"s": "Kai thinks studying what people like would have helped.", "a": "yes"}, {"s": "They still post at random times.", "a": "no"}]}, "keyq": [{"q": "Should you have studied more for your last exam?", "es": "¿Debiste haber estudiado más para tu último examen?", "a": "Yes, I should have. If I had studied, I'd feel better now.", "qau": "y4aecb6b013", "aau": "y4c5c0d9f96"}, {"q": "Would you speak English better now if you had started as a kid?", "es": "¿Hablarías mejor inglés ahora si hubieras empezado de niño?", "a": "Yes, I would. If I had started earlier, I'd be fluent now.", "qau": "y4f29b7368c", "aau": "y4cd49d2237"}, {"q": "Have you ever posted something you shouldn't have posted?", "es": "¿Alguna vez has publicado algo que no debiste haber publicado?", "a": "Yes, I have. I shouldn't have posted that embarrassing photo.", "qau": "y4a5339015f", "aau": "y4676ad8278"}]}, "t4p1": {"reading": {"title": "My month without social media", "text": "Last year I was spending almost four hours a day on my phone. I couldn't stand feeling tired all the time, so I decided to try an experiment: no social media for a month. My friends refused to believe I could do it. The first week was hard. I kept checking my phone out of habit, and I missed chatting with my friends online. But I managed to finish two books, and I started running in the mornings. I also agreed to help my dad build a treehouse for my sister. Now I avoid using my phone after nine. My advice? If you're considering trying it, tell your friends first.", "au": "y448f9410d2", "img": "u:photo-1553729784-e91953dec042", "q": [{"s": "The narrator spent four hours a day on the phone.", "a": "yes"}, {"s": "The friends believed it would be easy.", "a": "no"}, {"s": "The narrator finished two books.", "a": "yes"}, {"s": "The narrator now uses the phone until midnight.", "a": "no"}]}, "keyq": [{"q": "Do you enjoy listening to music while you study?", "es": "¿Disfrutas escuchar música mientras estudias?", "a": "Yes, I do. I enjoy listening to calm music.", "qau": "y42801e3a73", "aau": "y4b74abe28f"}, {"q": "Are you planning to travel next summer?", "es": "¿Estás planeando viajar el próximo verano?", "a": "Yes, I am. I'm planning to visit my cousins in Mexico.", "qau": "y4de9ff8d1b", "aau": "y43e2d1d83a"}, {"q": "Have you ever refused to lend something to a friend?", "es": "¿Alguna vez te has negado a prestarle algo a un amigo?", "a": "Yes, I have. I refused to lend my new headphones.", "qau": "y48b9eb1501", "aau": "y40d61ac4c4"}]}, "t4p2": {"reading": {"title": "The road trip that taught us patience", "text": "Last summer my family drove from Los Angeles to the Grand Canyon. Before we left, my mom told my brother, \"Remember to check the tires!\" He forgot to do it. Three hours later, in the middle of the desert, we got a flat tire. My dad tried to change it, but the spare was flat too. We tried calling for help, but there was no signal. So we stopped to think. I remember looking at the empty road and feeling lost. Finally, a kind truck driver stopped to help us. We arrived a day late, but I'll never forget seeing the sunset from the South Rim. My brother regrets not checking the tires.", "au": "y4741c3ea38", "img": "u:photo-1562705841-c4934bb2b31b", "q": [{"s": "The family drove to the Grand Canyon.", "a": "yes"}, {"s": "The brother checked the tires.", "a": "no"}, {"s": "They called for help easily.", "a": "no"}, {"s": "A truck driver stopped to help them.", "a": "yes"}]}, "keyq": [{"q": "Do you remember starting high school?", "es": "¿Recuerdas haber empezado la secundaria?", "a": "Yes, I do. I remember feeling really nervous.", "qau": "y4cd22298e5", "aau": "y413e3c972e"}, {"q": "Have you ever stopped doing something unhealthy?", "es": "¿Alguna vez has dejado de hacer algo poco saludable?", "a": "Yes, I have. I stopped drinking soda last year.", "qau": "y484b7cda87", "aau": "y406069627e"}, {"q": "Do you regret not joining a club last year?", "es": "¿Te arrepientes de no haberte unido a un club el año pasado?", "a": "Yes, I do. I regret not joining the drama club.", "qau": "y4015088b1f", "aau": "y4172d8ee8b"}]}, "t5p1": {"reading": {"title": "Why we like people who agree with us", "text": "Have you ever met someone and felt an instant connection? Psychologists call it the \"similarity effect\": we tend to like people who share our opinions. When a new classmate says, \"I can't stand horror movies,\" and we answer, \"Neither can I!\" we relax and smile. Small agreements like \"So do I\" or \"Me too\" make conversations last longer. But agreeing with everything can be a problem. If you always say \"So do I\" just to be polite, people may notice. Saying \"Oh, really? I don't. Why do you like it?\" shows interest. So agree when you really agree, and disagree kindly when you don't.", "au": "y499140308a", "img": "u:photo-1543269865-cbf427effbad", "q": [{"s": "The similarity effect means we like people who share our opinions.", "a": "yes"}, {"s": "Small agreements make conversations shorter.", "a": "no"}, {"s": "Agreeing with everything is always a good idea.", "a": "no"}, {"s": "Asking 'Why do you like it?' shows interest.", "a": "yes"}]}, "keyq": [{"q": "Do you like horror movies?", "es": "¿Te gustan las películas de terror?", "a": "No, I don't. Neither do my friends.", "qau": "y4a93d97d3f", "aau": "y443d615e47"}, {"q": "Have you ever been to a concert?", "es": "¿Alguna vez has ido a un concierto?", "a": "Yes, I have. So has my best friend.", "qau": "y4db9169c14", "aau": "y487d362f16"}, {"q": "Did you watch the game last night?", "es": "¿Viste el partido anoche?", "a": "Yes, I did. So did my whole family.", "qau": "y49b0dc9cf7", "aau": "y41a7425b19"}]}, "t5p2": {"reading": {"title": "Two schools, one decision", "text": "When my parents told me I could go either to the art school or to the science school next year, I thought it would be easy. It wasn't. Both schools have great teachers, and both are far from home. I didn't want to leave my friends, and my best friend Lucas didn't either. Neither school was perfect. The art school had a music studio, and the science school had a robotics lab. Finally, we visited both. A student there told me, \"I switched from art to science, and I love it.\" \"You did?\" I asked. \"Why?\" \"Both are fun, but robots are my thing,\" she answered. I chose science.", "au": "y4cbcb59eea", "img": "u:photo-1743677077216-00a458eff9e0", "q": [{"s": "Both schools are close to home.", "a": "no"}, {"s": "Lucas didn't want to leave his friends either.", "a": "yes"}, {"s": "The art school had a robotics lab.", "a": "no"}, {"s": "The narrator chose the science school.", "a": "yes"}]}, "keyq": [{"q": "Do you speak German?", "es": "¿Hablas alemán?", "a": "No, I don't. My parents don't either.", "qau": "y4cc448cd02", "aau": "y49d2fc61d3"}, {"q": "Do you enjoy both music and sports?", "es": "¿Disfrutas tanto la música como los deportes?", "a": "Yes, I do. I enjoy both playing guitar and swimming.", "qau": "y4b9c76f11c", "aau": "y43cb24e9ca"}, {"q": "Did your parents or your teachers help with your last project?", "es": "¿Tus papás o tus profesores te ayudaron con tu último proyecto?", "a": "No, they didn't. Neither my parents nor my teachers helped.", "qau": "y4c42ea96ce", "aau": "y48aff9579e"}]}, "t6p1": {"reading": {"title": "Too much screen time?", "text": "Sofia is fifteen, and lately she's been feeling tired all the time. Her eyes are often red and puffy. \"Have you been sleeping badly?\" her mom asked last week. The truth is that Sofia has been binge-watching a series every night since the summer. She's been going to bed after midnight, and she's been falling asleep in math class. Her best friend Mateo noticed it first. \"You've been yawning all morning,\" he said. So Sofia made a plan. For the last two weeks, she's been leaving her phone in the kitchen at ten. She's read two novels instead, and she's been feeling much better.", "au": "y4927a9159d", "img": "u:photo-1553729784-e91953dec042", "q": [{"s": "Sofia has been going to bed after midnight.", "a": "yes"}, {"s": "Her teacher noticed the problem first.", "a": "no"}, {"s": "Sofia has read two novels.", "a": "yes"}, {"s": "She has been keeping her phone in her bedroom at night.", "a": "no"}]}, "keyq": [{"q": "Have you been studying a lot for your exams lately?", "es": "¿Has estado estudiando mucho para tus exámenes últimamente?", "a": "Yes, I have. I've been studying every night since Monday.", "qau": "y47c5384cc9", "aau": "y45c3cdc890"}, {"q": "Have you been binge-watching any series lately?", "es": "¿Has estado viendo alguna serie en maratón últimamente?", "a": "No, I haven't. I've been reading a fantasy novel instead.", "qau": "y4d5c979b78", "aau": "y439f035c12"}, {"q": "Have you been living in the same house since you were little?", "es": "¿Has vivido en la misma casa desde que eras pequeño?", "a": "Yes, I have. I've been living here for twelve years.", "qau": "y43c90333e8", "aau": "y4c65b0f330"}]}, "t6p2": {"reading": {"title": "Making the team", "text": "When Diego saw his name on the school basketball team list, he couldn't believe it. He had been practicing every afternoon since January. The year before, he had tried out and failed. \"I had been playing only on weekends, and I wasn't ready,\" he remembers. He had been training for three months when the coach noticed him. The tryout was hard. Diego had been running for an hour, and his legs were exhausted. \"I believed I couldn't finish,\" he says. Then he saw his older sister in the stands. \"I've known my sister all my life, and I've never seen her so excited.\" Now Diego owns his first team jersey.", "au": "y4a02582aec", "img": "u:photo-1612768875331-0447b960fa40", "q": [{"s": "Diego had been practicing since January.", "a": "yes"}, {"s": "He made the team the year before.", "a": "no"}, {"s": "His legs were exhausted during the tryout.", "a": "yes"}, {"s": "His older brother was in the stands.", "a": "no"}]}, "keyq": [{"q": "Had you been studying for long before your last exam?", "es": "¿Llevabas mucho tiempo estudiando antes de tu último examen?", "a": "Yes, I had. I had been studying for two weeks.", "qau": "y42d0fd46d2", "aau": "y4c0ce02873"}, {"q": "Has your phone ever run out of battery during a trip?", "es": "¿Alguna vez se te ha quedado sin batería el celular durante un viaje?", "a": "Yes, it has. I had been taking photos all day.", "qau": "y45b0a41ec5", "aau": "y4ab7fee715"}, {"q": "Does your family own something very old?", "es": "¿Tu familia es dueña de algo muy viejo?", "a": "Yes, it does. We've owned the same piano for forty years.", "qau": "y405504d4a3", "aau": "y4553ad483f"}]}, "t7p1": {"reading": {"title": "A new school, a new friend", "text": "When Valentina moved to a new city, she was nervous about finding friends who shared her interests. On her first day, her teacher introduced her to Julia, a girl whose passion was music, just like hers. Julia showed her the music room where the school band practiced every Friday. \"Is there an instrument which you play?\" Julia asked. Valentina played the drums, and the band needed someone who could play them! Valentina will never forget the day when she played her first concert at school. \"The reason why I love this school is the people,\" she says. \"A good friend is someone who makes you feel at home.\"", "au": "y4296a4c384", "img": "u:photo-1649731581999-ae46d94c7518", "q": [{"s": "Julia is a girl whose passion is music.", "a": "yes"}, {"s": "The band practiced in the gym every Friday.", "a": "no"}, {"s": "Valentina plays the drums.", "a": "yes"}, {"s": "Valentina felt relaxed about finding new friends.", "a": "no"}]}, "keyq": [{"q": "Is there an app that you use every day?", "es": "¿Hay una app que uses todos los días?", "a": "Yes, there is. It's an app that helps me practice English.", "qau": "y461fd04875", "aau": "y4a306229eb"}, {"q": "Do you know someone whose family lives in another country?", "es": "¿Conoces a alguien cuya familia viva en otro país?", "a": "Yes, I do. Leo is a classmate whose cousins live in Spain.", "qau": "y42c90ad46a", "aau": "y47af7c6aa1"}, {"q": "Is there a city where you'd love to live?", "es": "¿Hay alguna ciudad donde te encantaría vivir?", "a": "Yes, there is. I'd love to live in a city where I can surf.", "qau": "y4b910bae02", "aau": "y4285e60760"}]}, "t7p2": {"reading": {"title": "Cartagena, a city full of stories", "text": "Last summer, our school trip took us to Cartagena, which is on the Caribbean coast of Colombia. The old city, which is surrounded by stone walls, is more than 400 years old. Our guide, who grew up there, told us about the pirates who attacked the city long ago, which is why the Spanish built the walls. We visited a fortress from which soldiers once watched the sea. There were twenty students on the trip, most of whom had never seen the ocean. The friends I traveled with still talk about the sunsets. Cartagena is definitely the city in which I'd love to spend more time.", "au": "y4d3d408142", "img": "u:photo-1534943441045-1009d7cb0bb9", "q": [{"s": "Cartagena is on the Caribbean coast.", "a": "yes"}, {"s": "The guide grew up in Bogotá.", "a": "no"}, {"s": "Most of the students had never seen the ocean.", "a": "yes"}, {"s": "The old city is about 100 years old.", "a": "no"}]}, "keyq": [{"q": "Do you have many classmates who play sports?", "es": "¿Tienes muchos compañeros que practican deportes?", "a": "Yes, I do. We're thirty students, most of whom play soccer.", "qau": "y4c51905a38", "aau": "y4fb5d53a12"}, {"q": "Is the city in which you live good for teenagers?", "es": "¿La ciudad en la que vives es buena para los adolescentes?", "a": "Yes, it is. My city, which has many parks, is great for skating.", "qau": "y40b35ce89f", "aau": "y43f9c20fe2"}, {"q": "Has anything surprising happened at school lately?", "es": "¿Ha pasado algo sorprendente en el colegio últimamente?", "a": "Yes, it has. Our team won the final, which surprised everyone.", "qau": "y48f793defa", "aau": "y40127c7735"}]}, "t8p1": {"reading": {"title": "Breaking the ice", "text": "When Andrés moved from Cali to a new school in Miami, his English was good, but conversations with classmates ended quickly. His older cousin gave him some advice: \"Use more tag questions.\" Andrés started listening carefully in the cafeteria. People said things like \"The math test was hard, wasn't it?\" and \"You've seen the new episode, haven't you?\" He realized these questions are invitations to join in. \"You play soccer, don't you?\" he asked a boy in his class. Ten minutes later, they were planning a game. He also learned to be careful with the auxiliary: \"She plays guitar, doesn't she?\" not \"isn't she?\" Now Andrés has lots of friends.", "au": "y49cfa34ac4", "img": "u:photo-1775300175543-96f588eca1fc", "q": [{"s": "Andrés moved from Cali to Miami.", "a": "yes"}, {"s": "His teacher gave him the advice.", "a": "no"}, {"s": "He asked a boy in his class about soccer.", "a": "yes"}, {"s": "The correct tag for 'She plays guitar' is 'isn't she?'", "a": "no"}]}, "keyq": [{"q": "Did you have a good weekend? You went to the concert, didn't you?", "es": "¿Tuviste un buen fin de semana? Fuiste al concierto, ¿no?", "a": "Yes, I did. The band was amazing.", "qau": "y4b5bc78355", "aau": "y4c78e06aa8"}, {"q": "Do you have classes on Saturdays? You don't, do you?", "es": "¿Tienes clases los sábados? No tienes, ¿verdad?", "a": "No, I don't. I only have classes Monday to Friday.", "qau": "y4467fa5269", "aau": "y4f381b3e79"}, {"q": "Is your English teacher nice? She speaks Spanish too, doesn't she?", "es": "¿Tu profesora de inglés es amable? Ella también habla español, ¿no?", "a": "Yes, she does. She lived in Mexico for years.", "qau": "y45e43daeda", "aau": "y4653584c53"}]}, "t8p2": {"reading": {"title": "It's all in the melody", "text": "Linguists say that English speakers often understand a tag question by its melody. Imagine two friends after a test. One says, \"The last question was tricky, wasn't it?\" If her voice goes down, she is almost sure and just wants agreement. If it goes up, she really doesn't know. Learners also struggle with special cases. \"I'm right, aren't I?\" sounds strange at first. Suggestions with \"let's\" take \"shall we?\": \"Let's study together, shall we?\" Commands sound softer with \"will you?\": \"Send me the notes, will you?\" Negative words such as never and nobody need a positive tag: \"Nobody texted, did they?\" Practice with short dialogues, and you'll sound natural.", "au": "y44b8c70cf7", "img": "u:photo-1758582388197-cd8449914603", "q": [{"s": "A rising voice means you really don't know.", "a": "yes"}, {"s": "Suggestions with 'let's' take the tag 'will you?'", "a": "no"}, {"s": "Negative words need a positive tag.", "a": "yes"}, {"s": "The two friends are talking after a soccer game.", "a": "no"}]}, "keyq": [{"q": "Are you going to the party? I'm invited too, aren't I?", "es": "¿Vas a ir a la fiesta? Yo también estoy invitado, ¿no?", "a": "Yes, you are. Everyone in our class is invited.", "qau": "y419a14b39c", "aau": "y4ccf7554b6"}, {"q": "Do you eat breakfast? You hardly ever eat in the morning, do you?", "es": "¿Desayunas? Casi nunca comes por la mañana, ¿verdad?", "a": "No, I don't. I'm never hungry before school.", "qau": "y4bf68c3c10", "aau": "y4485662320"}, {"q": "Are you free tonight? Let's watch a movie, shall we?", "es": "¿Estás libre esta noche? Veamos una película, ¿sí?", "a": "Yes, I am. Let's watch a comedy, shall we?", "qau": "y4b9231cf7c", "aau": "y48c064b599"}]}, "t9p1": {"reading": {"title": "The message that got lost", "text": "Last month, our school band almost missed a big concert because of a message that was passed on badly. On Monday, the music teacher told Camila, \"The concert is on Saturday. We'll meet at the theater at four.\" Camila texted the group, but she wrote that the concert was \"next Saturday.\" Everyone relaxed. On Friday, the teacher said he was really excited about the next day. The band panicked! They told him they hadn't practiced enough. They rehearsed until nine that night, and the concert was a success. Afterwards, Camila told everyone she would never write \"next Saturday\" again. Now the band always uses exact dates.", "au": "y40b7e836ee", "img": "u:photo-1617052241384-b24d3ebce241", "q": [{"s": "The teacher told Camila the concert was on Saturday.", "a": "yes"}, {"s": "Camila wrote the correct date in her text.", "a": "no"}, {"s": "The band rehearsed until nine on Friday night.", "a": "yes"}, {"s": "The concert was a disaster.", "a": "no"}]}, "keyq": [{"q": "Did your teacher tell you the exam had changed?", "es": "¿Tu profesor te dijo que el examen había cambiado?", "a": "Yes, he did. He told us it would be on Monday.", "qau": "y49a80b8ecd", "aau": "y419f98b7f5"}, {"q": "Did your best friend say he was going to the concert?", "es": "¿Tu mejor amigo dijo que iba a ir al concierto?", "a": "Yes, he did. He said he had already bought the tickets.", "qau": "y4f61c2e81a", "aau": "y469345ad38"}, {"q": "Did the doctor say you needed to rest?", "es": "¿El médico dijo que necesitabas descansar?", "a": "Yes, she did. She said I couldn't play soccer for a week.", "qau": "y4b78d974c7", "aau": "y40ac6a4090"}]}, "t9p2": {"reading": {"title": "Planning the class trip", "text": "Last week, our class had a serious talk about the school trip to the coast. First, our teacher reminded us to be respectful. Martín suggested going by train instead of bus, but several students refused to change the plan. Then Sara admitted forgetting to collect the permission forms, and she apologized for causing a delay. She promised to bring them all on Monday. Tomás denied losing the class list, although everyone knew he had it. Our teacher warned us not to bring expensive phones and advised everyone to pack light. Finally, Lucas offered to make a playlist for the bus, and everyone agreed to help.", "au": "y420486be3b", "img": "u:photo-1594608661623-aa0bd3a69d98", "q": [{"s": "Martín suggested going by train.", "a": "yes"}, {"s": "Sara denied forgetting the permission forms.", "a": "no"}, {"s": "The teacher advised everyone to pack light.", "a": "yes"}, {"s": "Lucas refused to make a playlist.", "a": "no"}]}, "keyq": [{"q": "Has anyone ever accused you of something you didn't do?", "es": "¿Alguien te ha acusado alguna vez de algo que no hiciste?", "a": "Yes, my brother has. He accused me of breaking his headphones.", "qau": "y497cbfcaec", "aau": "y48f9398197"}, {"q": "Did your teacher suggest studying in groups?", "es": "¿Tu profesor sugirió estudiar en grupos?", "a": "Yes, he did. He suggested studying at the library after school.", "qau": "y4e9fc42515", "aau": "y4a5c10a028"}, {"q": "Has your coach ever warned you not to skip practice?", "es": "¿Tu entrenador alguna vez te ha advertido que no faltes al entrenamiento?", "a": "Yes, he has. He warned us not to miss any games.", "qau": "y416e236852", "aau": "y467a363c99"}]}, "t10p1": {"reading": {"title": "Lost in New York", "text": "During our school trip to New York, my friend Nico and I got lost near Central Park. Nico stopped a woman and asked, \"Where is the subway?\" She looked surprised. Our English teacher had told us that direct questions can sound rude. So I tried again: \"Excuse me, could you tell me where the nearest subway station is?\" The woman smiled and gave us clear directions. Then I asked, \"Do you happen to know what time the museum closes?\" She said it closed at five. Nico learned fast. At the station, he said, \"I was wondering if you could help us buy tickets.\" Being polite really helps!", "au": "y4d411febff", "img": "u:photo-1610547803282-bb8e68c86954", "q": [{"s": "They got lost near Central Park.", "a": "yes"}, {"s": "Nico's first question was very polite.", "a": "no"}, {"s": "The museum closed at five.", "a": "yes"}, {"s": "The woman refused to help them.", "a": "no"}]}, "keyq": [{"q": "Do you know when your next exam is?", "es": "¿Sabes cuándo es tu próximo examen?", "a": "Yes, I do. It's next Tuesday.", "qau": "y4c436b61de", "aau": "y4086818ac3"}, {"q": "Could you tell me what kind of music you like?", "es": "¿Podrías decirme qué tipo de música te gusta?", "a": "Yes, I can. I really like rock and pop.", "qau": "y4dda29bd89", "aau": "y44513c8402"}, {"q": "Do you happen to know how much a concert ticket costs?", "es": "¿Por casualidad sabes cuánto cuesta una entrada para un concierto?", "a": "No, I don't. I think it's about fifty dollars.", "qau": "y4d6f1a70bb", "aau": "y4d7764bc46"}]}, "t10p2": {"reading": {"title": "After the tryout", "text": "Coaches often recommend a simple habit: write notes right after a tryout. Fifteen-year-old Valeria tried it after her volleyball tryout. In her notes, she wrote that the coach had asked her why she wanted to join the team and how long she had been playing. He also wanted to know whether she could practice on Saturdays and if she had ever played in a tournament. Finally, he asked what position she preferred. Writing these questions helped Valeria. She realized she wasn't sure whether to choose weekend practice or her art classes. She made the team and found a schedule for both. Reported questions use statement word order.", "au": "y4ebb86b8f9", "img": "u:photo-1567781830902-685fb3401f1d", "q": [{"s": "The coach asked Valeria why she wanted to join the team.", "a": "yes"}, {"s": "The coach didn't ask about Saturdays.", "a": "no"}, {"s": "Valeria wasn't sure whether to choose weekend practice or art classes.", "a": "yes"}, {"s": "Valeria didn't make the team.", "a": "no"}]}, "keyq": [{"q": "Did the coach ask you what position you played?", "es": "¿El entrenador te preguntó en qué posición jugabas?", "a": "Yes, he did. He also asked whether I could practice on weekends.", "qau": "y498ac56fe7", "aau": "y4ec20fd304"}, {"q": "Did your parents ask you where you had been last night?", "es": "¿Tus papás te preguntaron dónde habías estado anoche?", "a": "Yes, they did. They wanted to know why I was home late.", "qau": "y40998e882c", "aau": "y46fce7ad73"}, {"q": "Have you decided whether to take extra English classes?", "es": "¿Ya decidiste si tomar clases extra de inglés?", "a": "No, I haven't. It depends on whether I have time.", "qau": "y4dd77a4736", "aau": "y45fa690f82"}]}, "t11p1": {"reading": {"title": "A festival that almost didn't happen", "text": "Every spring, our school music festival is attended by hundreds of students and families. This year, however, it was almost canceled. In February, the main stage was damaged by a storm, and the sound equipment had been stored in the same building. Luckily, money was collected by the student council, and new speakers were bought. Right now, the stage is being rebuilt by volunteers from the community. The posters have already been printed, and the band list will be announced on Friday. Tickets can be bought online, but they must be shown at the entrance. Everyone hopes this festival will be remembered as the best one ever.", "au": "y47b398e20f", "img": "u:photo-1790306830782-63d4cd3ea5b0", "q": [{"s": "The main stage was damaged by a storm.", "a": "yes"}, {"s": "The posters haven't been printed yet.", "a": "no"}, {"s": "The band list will be announced on Friday.", "a": "yes"}, {"s": "Tickets can only be bought at the entrance.", "a": "no"}]}, "keyq": [{"q": "Have your exam results been posted yet?", "es": "¿Ya publicaron los resultados de tus exámenes?", "a": "No, they haven't. They will be posted next week.", "qau": "y4350957b80", "aau": "y476e955009"}, {"q": "Was your phone made in your country?", "es": "¿Tu teléfono fue fabricado en tu país?", "a": "No, it wasn't. It was made in another country.", "qau": "y4fc7ff2ce6", "aau": "y4a1bcf327d"}, {"q": "Will a new club be started at your school this year?", "es": "¿Se creará un club nuevo en tu colegio este año?", "a": "Yes, it will. A robotics club will be started in March.", "qau": "y4e89930608", "aau": "y47cb1983c8"}]}, "t11p2": {"reading": {"title": "School Garden Named Best in State", "text": "\"School Garden Named Best in State.\" That was the headline on our school blog last week. It is reported that more than two hundred schools took part in the contest. Our garden is said to have impressed the judges with its vegetables and its rainwater system. The process is simple. First, the seeds are planted by students in March. Then, the plants are watered every morning. Finally, the vegetables are picked and given to the cafeteria. Now, a TV crew is expected to visit next month. And there is a new rumor: our principal is believed to be planning a second garden on the roof!", "au": "y46c343e4d3", "img": "u:photo-1791318219716-2ce5458c8257", "q": [{"s": "The garden is said to have impressed the judges.", "a": "yes"}, {"s": "The seeds are planted by teachers.", "a": "no"}, {"s": "The vegetables are given to the cafeteria.", "a": "yes"}, {"s": "A TV crew visited the garden last week.", "a": "no"}]}, "keyq": [{"q": "Is your favorite band expected to release a new song soon?", "es": "¿Se espera que tu banda favorita lance una canción nueva pronto?", "a": "Yes, it is. It's expected to release one in December.", "qau": "y457a024f62", "aau": "y41830edcea"}, {"q": "Have you ever read a headline about your town?", "es": "¿Alguna vez has leído un titular sobre tu ciudad?", "a": "Yes, I have. It said \"Local School Wins Science Prize.\"", "qau": "y47a72d7b1b", "aau": "y45b651fac5"}, {"q": "Are bananas grown near where you live?", "es": "¿Se cultivan bananos cerca de donde vives?", "a": "Yes, they are. They are grown on farms near the coast.", "qau": "y4187f91308", "aau": "y4bd359a599"}]}, "t12p1": {"reading": {"title": "Getting ready for graduation", "text": "Valentina is graduating from high school in two weeks, and her to-do list is long. Last month, she had her dress made by a tailor in her neighborhood. On Thursday, she is having her graduation photos taken at a studio. The day before the ceremony, she will have her hair done and her nails painted. Her parents are having the backyard decorated for the party, and they will have the food delivered. Her grandfather laughs at all this. \"When I graduated, my mother cut my hair in the kitchen,\" he says. \"Nobody had anything done!\" Valentina just smiles. \"Times change, Grandpa.\"", "au": "y4aa430b522", "img": "u:photo-1761781342506-30f68c930a16", "q": [{"s": "Valentina had her dress made by a tailor.", "a": "yes"}, {"s": "She is taking her graduation photos herself.", "a": "no"}, {"s": "Her parents will cook all the food.", "a": "no"}, {"s": "Her grandfather's mother cut his hair.", "a": "yes"}]}, "keyq": [{"q": "Do you have your hair cut every month?", "es": "¿Te cortas el pelo cada mes?", "a": "No, I don't. I have it cut every two months.", "qau": "y4b5d781d16", "aau": "y49b2b890d3"}, {"q": "Have you ever had your phone screen replaced?", "es": "¿Alguna vez te han cambiado la pantalla del teléfono?", "a": "Yes, I have. I had it replaced last year.", "qau": "y441b7a2df8", "aau": "y4a0df06bc4"}, {"q": "Should you have your eyes tested this year?", "es": "¿Deberías hacerte examinar la vista este año?", "a": "Yes, I should. I haven't had them tested in a long time.", "qau": "y426ea13317", "aau": "y420520cc66"}]}, "t12p2": {"reading": {"title": "When a class trip goes wrong", "text": "Last spring, Camila went on a class trip to Washington, D.C., and it was full of surprises. First, the group had their flight canceled because of a storm, so they spent the night at the airport. The next day, Camila had her bag searched twice at security because of a water bottle. At the hotel, she discovered a crack in her phone screen, so she had the receptionist recommend a repair shop and got it fixed that afternoon. That night, she got her social media account hacked. Luckily, she got her teacher to help her change the password. \"It was stressful,\" she says, \"but now I always double-check my bag.\"", "au": "y426fa3aff4", "img": "u:photo-1663593863375-891777fdc72f", "q": [{"s": "The group had their flight canceled.", "a": "yes"}, {"s": "Camila fixed her phone screen herself.", "a": "no"}, {"s": "She had her bag searched only once.", "a": "no"}, {"s": "Her teacher helped her change her password.", "a": "yes"}]}, "keyq": [{"q": "Have you ever had your bag searched at an airport?", "es": "¿Alguna vez te han revisado el bolso en un aeropuerto?", "a": "Yes, I have. I had it searched on a trip last year.", "qau": "y4a84903083", "aau": "y42600fd035"}, {"q": "Do you need to get your phone fixed this month?", "es": "¿Necesitas mandar a arreglar tu teléfono este mes?", "a": "No, I don't. But I need to get my headphones fixed.", "qau": "y419e790f6f", "aau": "y4e9d16f237"}, {"q": "Did you get your friends to help you with your last project?", "es": "¿Conseguiste que tus amigos te ayudaran con tu último proyecto?", "a": "Yes, I did. I got two friends to help me with the poster.", "qau": "y4519abe329", "aau": "y4e688a8df6"}]}, "t13p1": {"reading": {"title": "A school day in 2040", "text": "Imagine a high school student, Ana, on a Tuesday in 2040. At seven in the morning, she won't be waiting for the bus, because a self-driving shuttle will be taking her to school. At nine, she will be studying history with virtual reality glasses, walking through ancient Rome. At noon, a robot will be serving lunch in the cafeteria. In the afternoon, her class will be talking with students in Japan, and an app will be translating everything in real time. At eight in the evening, Ana will be playing games online with her friends. Will students really be living like this? Nobody knows, but it's fun to imagine.", "au": "y4713b55b1f", "img": "u:photo-1538388149542-5e24932d11a8", "q": [{"s": "Ana will be waiting for the bus at seven.", "a": "no"}, {"s": "She will be using virtual reality glasses in history class.", "a": "yes"}, {"s": "A teacher will be serving lunch in the cafeteria.", "a": "no"}, {"s": "An app will be translating in real time.", "a": "yes"}]}, "keyq": [{"q": "Will you be studying for exams this time next week?", "es": "¿Estarás estudiando para exámenes la próxima semana a esta hora?", "a": "Yes, I will. I'll be studying for my math exam.", "qau": "y42eacc0ed4", "aau": "y4a619880eb"}, {"q": "Will you be using your laptop tonight?", "es": "¿Vas a usar tu portátil esta noche?", "a": "No, I won't. You can use it.", "qau": "y424e729668", "aau": "y4f668d29ac"}, {"q": "Will you be living in another city in ten years?", "es": "¿Estarás viviendo en otra ciudad en diez años?", "a": "Yes, I will. I think I'll be living in Bogotá.", "qau": "y43082e3c00", "aau": "y45af6f63af"}]}, "t13p2": {"reading": {"title": "Your five-year plan", "text": "\"Where do you see yourself in five years?\" School counselor Mrs. Reyes asks her students this question every year. She recommends concrete goals instead of vague dreams. \"Don't say 'I want to improve,'\" she explains. \"Say 'By the end of this year, I'll have passed all my math exams.'\" Diego, a student, wrote: by next summer, I'll have saved enough to buy a guitar; by sixteen, I'll have played in my first concert; and by graduation, I'll have been accepted into a music school. If you miss a due date, you just adjust the plan. By the time you finish this class, you'll have learned the perfect grammar to write yours.", "au": "y41b37151e3", "img": "u:photo-1547357812-4a336d835928", "q": [{"s": "Mrs. Reyes recommends vague dreams.", "a": "no"}, {"s": "Diego wants to buy a guitar.", "a": "yes"}, {"s": "Diego will have played in a concert by sixteen.", "a": "yes"}, {"s": "If you miss a due date, you should give up.", "a": "no"}]}, "keyq": [{"q": "Will you have finished high school by 2030?", "es": "¿Habrás terminado el colegio para 2030?", "a": "Yes, I will. I'll have graduated by then.", "qau": "y415cb2002f", "aau": "y4f76f07254"}, {"q": "Will you have passed all your exams by June?", "es": "¿Habrás aprobado todos tus exámenes para junio?", "a": "Yes, I will. I'll have taken the last one by June 10.", "qau": "y486c2155b3", "aau": "y4ac13969af"}, {"q": "Will you have visited another country by the end of next year?", "es": "¿Habrás visitado otro país para fines del próximo año?", "a": "No, I won't. But I'll have saved money for a trip.", "qau": "y45cc58e7f9", "aau": "y403f2c4805"}]}, "t14p1": {"reading": {"title": "Six years of music", "text": "Next March, Lucía will have been playing the violin in the school orchestra for six years. She joined at eleven, when she could barely read music. Now she is the first violin. Her friends are organizing a surprise for the spring concert. By the day of the concert, they will have been collecting videos from former members for two months. \"By then, I'll have been sitting next to Lucía for four years,\" says her friend Kevin, \"and she still helps me every week.\" Lucía has also started Japanese classes. \"When I graduate, I will have been studying it for three years,\" she says. \"I'll be tired, but proud.\"", "au": "y4ac2ff5edb", "img": "u:photo-1465847899084-d164df4dedc6", "q": [{"s": "Lucía joined the orchestra at eleven.", "a": "yes"}, {"s": "Her friends will have been collecting videos for six months.", "a": "no"}, {"s": "Kevin will have been sitting next to her for four years.", "a": "yes"}, {"s": "Lucía is studying Chinese.", "a": "no"}]}, "keyq": [{"q": "Will you have been studying English for two years by December?", "es": "¿Llevarás dos años estudiando inglés en diciembre?", "a": "Yes, I will. I'll have been studying it for exactly two years.", "qau": "y40dc2828f3", "aau": "y43df833369"}, {"q": "Will you have been living in your city for ten years by next year?", "es": "¿Llevarás diez años viviendo en tu ciudad el próximo año?", "a": "No, I won't. I'll have been living here for six years.", "qau": "y4330777b26", "aau": "y4363d02fc9"}, {"q": "Will you be tired tonight because you'll have been studying all day?", "es": "¿Estarás cansado esta noche porque habrás estado estudiando todo el día?", "a": "Yes, I will. I'll have been studying for my exams since 7 a.m.", "qau": "y4d838f7545", "aau": "y4b9d44c754"}]}, "t14p2": {"reading": {"title": "Two ways to measure a goal", "text": "Fitness apps measure progress in two ways, and English grammar does the same. Take Camilo, a 16-year-old who is training for his first half marathon in November. The first kind of information is about results: by race day, he will have run more than 300 miles. Those are numbers, so we use the future perfect. The second is about duration: by race day, he will have been training for eight months. That's an ongoing activity, so we use the future perfect continuous. His sister Laura is writing a fantasy novel. By December, she will have written twelve chapters, but she will have been writing for almost two years.", "au": "y4baae3a8a5", "img": "u:photo-1759674861540-afed9f86f94a", "q": [{"s": "Camilo will have run more than 300 miles by race day.", "a": "yes"}, {"s": "He will have been training for two years.", "a": "no"}, {"s": "Laura will have written twelve chapters by December.", "a": "yes"}, {"s": "Laura is writing a science book.", "a": "no"}]}, "keyq": [{"q": "Will you have saved enough money for a trip by December?", "es": "¿Habrás ahorrado suficiente dinero para un viaje en diciembre?", "a": "Yes, I will. I'll have saved about two hundred dollars.", "qau": "y46a186841d", "aau": "y4b727de679"}, {"q": "Will you have been saving for a long time by then?", "es": "¿Llevarás mucho tiempo ahorrando para entonces?", "a": "Yes, I will. I'll have been saving for a year.", "qau": "y447f27d483", "aau": "y42df178f14"}, {"q": "Will you have read ten books by the end of the year?", "es": "¿Habrás leído diez libros para fin de año?", "a": "No, I won't. I'll have read about six books.", "qau": "y451facbd9e", "aau": "y4e787bd47c"}]}, "t15p1": {"reading": {"title": "AI Essays: Help or Shortcut?", "text": "Last week, our school club debated whether students should use AI to write essays. Sara opened with a clear position: \"It could be argued that AI is just a modern dictionary.\" Granted, it can fix grammar and suggest ideas in seconds. That said, Daniel pointed out that teachers want to see our own thinking, not a machine's. Although AI is fast, it cannot learn for us. Some students admitted that they had used it to cheat on homework. All things considered, the club agreed on a middle position: AI should be a learning tool, not a shortcut. On balance, the benefits outweigh the risks if we use it honestly.", "au": "y4877d860c2", "img": "u:photo-1515378960530-7c0da6231fb1", "q": [{"s": "Sara compared AI to a modern dictionary.", "a": "yes"}, {"s": "Daniel said teachers want to see a machine's thinking.", "a": "no"}, {"s": "Nobody admitted using AI to cheat.", "a": "no"}, {"s": "The club agreed that AI should be a learning tool.", "a": "yes"}]}, "keyq": [{"q": "Should students be allowed to use AI for essays?", "es": "¿Se debería permitir a los estudiantes usar IA para sus ensayos?", "a": "Yes, they should. Nevertheless, teachers need clear rules to stop cheating.", "qau": "y4b31afeefe", "aau": "y41a3b1b77b"}, {"q": "Could AI make students lazy?", "es": "¿Podría la IA volver perezosos a los estudiantes?", "a": "Yes, it could. Granted, it saves time, but we might stop thinking for ourselves.", "qau": "y48f9ab10e4", "aau": "y414fc1c9ec"}, {"q": "Do you think the benefits of AI outweigh the risks?", "es": "¿Crees que los beneficios de la IA superan los riesgos?", "a": "Yes, I do. All things considered, AI is a useful learning tool.", "qau": "y48190d9224", "aau": "y4d3d5af2e1"}]}, "t16p1": {"reading": {"title": "Uniforms: Unity or Uniformity?", "text": "Our student newspaper asked a simple question: should our school keep uniforms? Proponents argue that uniforms reduce peer pressure. When everyone dresses the same, nobody is judged for not wearing designer clothes. By the same token, uniforms create a sense of unity on school trips and at sports events. Critics contend that the teenage years are a time to discover your identity, and clothes are part of that. However compelling the unity argument may be, they say, it overlooks individuality. One student wrote, \"This is not to say that rules are useless, but a simple dress code would be fairer.\" Most readers agreed with her.", "au": "y488de49d63", "img": "u:photo-1753175843003-a7492d611bf9", "q": [{"s": "Proponents say that uniforms reduce peer pressure.", "a": "yes"}, {"s": "Critics believe clothes have nothing to do with identity.", "a": "no"}, {"s": "One student suggested a simple dress code.", "a": "yes"}, {"s": "Most readers disagreed with her.", "a": "no"}]}, "keyq": [{"q": "Should schools keep uniforms?", "es": "¿Los colegios deberían mantener los uniformes?", "a": "Yes, they should. Proponents argue that uniforms reduce peer pressure, and I agree.", "qau": "y46ae08271f", "aau": "y48987eb110"}, {"q": "Do uniforms stop teens from expressing themselves?", "es": "¿Los uniformes impiden que los adolescentes se expresen?", "a": "No, they don't. That argument overlooks shoes, hairstyles and accessories.", "qau": "y45e3a0eefa", "aau": "y4f1e4efbae"}, {"q": "Would a simple dress code be fairer than uniforms?", "es": "¿Un código de vestimenta sencillo sería más justo que los uniformes?", "a": "Yes, it would. By the same token, it would give students more freedom.", "qau": "y44fdad08ab", "aau": "y4c6103421b"}]}, "t17p1": {"reading": {"title": "Scrolling and Feeling Worse?", "text": "Our health class looked at research on social media and teens. There is growing evidence that heavy use is associated with anxiety and poor sleep. Many studies suggest that social comparison plays a role: we tend to compare our ordinary days with other people's perfect photos. FOMO may exacerbate the problem. However, it would be simplistic to claim that apps alone cause these feelings. A correlation does not necessarily imply causation. Online groups can also provide support and a sense of belonging. Our teacher's advice was simple: set time limits, mute accounts that make you feel bad, and talk to a trusted adult if you are having a hard time.", "au": "y4a904e395c", "img": "u:photo-1758611973525-b5a86f468b5e", "q": [{"s": "The research links heavy use with poor sleep.", "a": "yes"}, {"s": "The class concluded that apps alone cause anxiety.", "a": "no"}, {"s": "Online groups can provide support.", "a": "yes"}, {"s": "The teacher advised following more accounts.", "a": "no"}]}, "keyq": [{"q": "Do teens tend to compare themselves to others online?", "es": "¿Los adolescentes tienden a compararse con los demás en internet?", "a": "Yes, they do. Many studies suggest that this can affect their well-being.", "qau": "y41ad41b3dd", "aau": "y400b887a24"}, {"q": "Does social media alone cause anxiety?", "es": "¿Las redes sociales por sí solas causan ansiedad?", "a": "No, it doesn't. It would be simplistic to claim that; other factors matter too.", "qau": "y419c68153a", "aau": "y45f9fc3547"}, {"q": "Should teens set limits on their screen time?", "es": "¿Los adolescentes deberían ponerle límites a su tiempo frente a la pantalla?", "a": "Yes, they should. Less screen time is associated with better sleep.", "qau": "y467cbf6e8d", "aau": "y4dcb02d37d"}]}, "t18p1": {"reading": {"title": "Is Our Grading Fair?", "text": "Our class debated a tricky question: is our grading system fair? Some students argued that grades reward effort, so the system is fair. Others were not entirely convinced. Students who have a quiet place to study and extra help at home tend to get better grades. Arguably, not everyone starts on a level playing field. Then Valeria said, \"It depends on how we define fairness. Should everyone get equal treatment or equal results?\" Most of us agreed that, to a certain extent, the system is fair, but that students who struggle should receive more support from the school. Broadly speaking, it was a respectful and useful debate.", "au": "y4fc1c3b126", "img": "u:photo-1561089489-f13d5e730d72", "q": [{"s": "Some students said that grades reward effort.", "a": "yes"}, {"s": "Everyone was completely convinced that the system is fair.", "a": "no"}, {"s": "Valeria asked how to define fairness.", "a": "yes"}, {"s": "Most students thought struggling students need no support.", "a": "no"}]}, "keyq": [{"q": "Is your school's grading system fair?", "es": "¿El sistema de calificaciones de tu colegio es justo?", "a": "Yes, it is, to a certain extent. But some students tend to get more help at home.", "qau": "y46cc22180b", "aau": "y426799c98e"}, {"q": "Should students who need extra help get more time on tests?", "es": "¿Los estudiantes que necesitan ayuda adicional deberían tener más tiempo en los exámenes?", "a": "Yes, they should. Arguably, that creates a more level playing field.", "qau": "y41c2c9ed47", "aau": "y4dd727cbf3"}, {"q": "Is equal treatment always the same as fairness?", "es": "¿El trato igual siempre es lo mismo que la justicia?", "a": "No, it isn't. It depends on how we define fairness.", "qau": "y4c3b7ae57d", "aau": "y4cf218a3c3"}]}, "t19p1": {"reading": {"title": "Classroom or Screen?", "text": "During exam season, Camila tried an online math course. Whereas her school classes follow a fixed timetable, the online course let her study at midnight if she wanted. In contrast, her friend Nico prefers face-to-face classes. \"Unlike videos, a real teacher can answer my questions immediately,\" he says. Online learning also demands far more self-discipline: Camila admits that she sometimes watched series instead of studying. Moreover, not every student has a reliable internet connection. Many teachers now favor blended learning, which combines the best of both. As Camila discovered, the more organized you are, the easier online learning becomes.", "au": "y4a0fa7518b", "img": "u:photo-1655057011043-158c48f3809d", "q": [{"s": "Camila's online course had a fixed timetable.", "a": "no"}, {"s": "Nico prefers face-to-face classes.", "a": "yes"}, {"s": "Camila sometimes watched series instead of studying.", "a": "yes"}, {"s": "Every student has a reliable internet connection.", "a": "no"}]}, "keyq": [{"q": "Is online learning as effective as face-to-face classes for you?", "es": "¿Aprender en línea es tan efectivo como las clases presenciales para ti?", "a": "No, it isn't. Whereas some students thrive online, I need a real classroom.", "qau": "y4b853bde02", "aau": "y402e5539ac"}, {"q": "Does online learning require more self-discipline?", "es": "¿Aprender en línea requiere más autodisciplina?", "a": "Yes, it does. It requires far more self-discipline than face-to-face classes.", "qau": "y4e1a15425e", "aau": "y477e3b4f1e"}, {"q": "Will schools use more blended learning in the future?", "es": "¿Los colegios usarán más aprendizaje mixto en el futuro?", "a": "Yes, they will. The more technology improves, the more schools will use it.", "qau": "y4480d23a85", "aau": "y4e8c2b2406"}]}, "t20p1": {"reading": {"title": "Student Council Debate", "text": "This year, our student council debated how to spend the money from the school fair: a music room or new sports equipment? The moderator, Isabella, kept the discussion calm. When Andrés interrupted, she said, \"Please let him finish.\" When someone claimed that most students hate sports, she asked, \"Do you have a source for that?\" Granted, the music room was popular, but the sports teams needed new balls. \"I take your point, but could you elaborate on the costs?\" asked Laura. Isabella reminded everyone to focus on the argument, not the person. If every debate were this respectful, our school might be an even better place.", "au": "y4b50505259", "img": "u:photo-1758270704763-22072a90d3b6", "q": [{"s": "Isabella was the moderator.", "a": "yes"}, {"s": "Andrés never interrupted.", "a": "no"}, {"s": "Isabella asked for a source.", "a": "yes"}, {"s": "Laura asked about the music teachers.", "a": "no"}]}, "keyq": [{"q": "Should the student council listen to every student?", "es": "¿El consejo estudiantil debería escuchar a todos los estudiantes?", "a": "Yes, it should. If everyone felt heard, students might participate more.", "qau": "y470482e365", "aau": "y4f0313bae4"}, {"q": "Do you check sources before you share news?", "es": "¿Verificas las fuentes antes de compartir noticias?", "a": "Yes, I do. Granted, it takes time, but fake news spreads fast.", "qau": "y46868b9ae8", "aau": "y4fab6c7158"}, {"q": "Have you ever moderated a class debate?", "es": "¿Alguna vez has moderado un debate en clase?", "a": "No, I haven't. But if I did, I'd ask quiet students to elaborate.", "qau": "y4f24ad4b57", "aau": "y464f302751"}]}, "t21p1": {"reading": {"title": "Is Space Worth It?", "text": "Our science club debated a big question: is space exploration worth the cost? Supporters said that satellite technology gives us GPS, weather forecasts and video calls. \"Had we not explored space, our phones would be far less useful,\" said Kevin. Others disagreed. With so many problems on Earth, like pollution and hunger, they argued that rockets are too expensive. Then Ana had an interesting idea: \"Were Earth to face a huge disaster, a colony on Mars could help humans survive.\" Should we ever build a city on Mars, it would be the biggest scientific project in history. The debate ended without a winner, but everyone left with new ideas.", "au": "y49b88ad8c4", "img": "u:photo-1785112927376-df14ff97ea4f", "q": [{"s": "Kevin said that space exploration makes phones more useful.", "a": "yes"}, {"s": "Everyone agreed that rockets are cheap.", "a": "no"}, {"s": "Ana talked about a colony on Mars.", "a": "yes"}, {"s": "The debate had a clear winner.", "a": "no"}]}, "keyq": [{"q": "Is space exploration a waste of money?", "es": "¿La exploración espacial es un desperdicio de dinero?", "a": "No, it isn't. Had we not explored space, we wouldn't have GPS.", "qau": "y48f1570bd8", "aau": "y42cfeaef27"}, {"q": "Should humans try to live on Mars?", "es": "¿Los seres humanos deberían intentar vivir en Marte?", "a": "Yes, they should. Were Earth to face a disaster, Mars could help us survive.", "qau": "y468f9b11fa", "aau": "y4a052b1ac8"}, {"q": "Would you join a crewed mission to the Moon?", "es": "¿Te unirías a una misión tripulada a la Luna?", "a": "Yes, I would. Should I ever get the chance, I'd go immediately.", "qau": "y4d385f511a", "aau": "y4548f00158"}]}}};
